// Banque de questions de connaissances générales (ETG) — 10 thèmes officiels.
// Généré/enrichi à partir de la banque initiale ; chaque question a une explication pédagogique.
const knowledgeQuestions = [
  {"id":"kq1","type":"knowledge","theme":"circulation","question":"Quel est le temps de réaction moyen d'un conducteur attentif ?","options":["Environ 1 seconde","Environ 0,3 seconde","Environ 3 secondes, sans fatigue","Environ 5 secondes"],"correctIndex":0,"explanation":"Un conducteur attentif met en moyenne 1 seconde pour percevoir un danger et commencer à réagir ; ce délai augmente fortement avec la fatigue, l'alcool ou la distraction."},
  {"id":"kq2","type":"knowledge","theme":"circulation","question":"À 50 km/h, quelle distance parcours-tu pendant ton temps de réaction ?","options":["Environ 5 mètres, soit la longueur d'une voiture","Environ 14 mètres avant de freiner","Environ 30 mètres avant même de freiner","Environ 50 mètres avant de freiner"],"correctIndex":1,"explanation":"À 50 km/h, on parcourt environ 14 mètres pendant la seconde de réaction, avant même d'avoir commencé à freiner."},
  {"id":"kq3","type":"knowledge","theme":"circulation","question":"Si la vitesse double, la distance de freinage est multipliée par :","options":["2, la distance double comme la vitesse","3, par ajout du temps de réaction","4, car la distance varie avec le carré de la vitesse","6, en cumulant réaction et freinage"],"correctIndex":2,"explanation":"La distance de freinage dépend du carré de la vitesse : si la vitesse double, l'énergie cinétique à absorber est multipliée par 4."},
  {"id":"kq4","type":"knowledge","theme":"circulation","question":"Sur route mouillée, la distance de freinage :","options":["Reste identique si les pneus sont en bon état","Augmente d'environ 10 %, pas davantage","Diminue, car l'eau refroidit les freins","Peut doubler sur chaussée glissante"],"correctIndex":3,"explanation":"L'eau réduit fortement l'adhérence des pneus : la distance de freinage peut doubler, voire plus sur route glissante ou avec des pneus usés."},
  {"id":"kq5","type":"knowledge","theme":"circulation","question":"À une intersection sans aucun panneau ni marquage, qui a la priorité ?","options":["Le véhicule qui vient de ta droite","Celui qui va tout droit","Celui qui est sur la route la plus large","Celui qui est arrivé le premier au carrefour"],"correctIndex":0,"explanation":"En l'absence de toute signalisation, la règle de la priorité à droite s'applique : c'est le véhicule venant de la droite qui passe en premier.","scene":"inter_droite"},
  {"id":"kq6","type":"knowledge","theme":"circulation","question":"En France, à l'entrée d'un rond-point avec un panneau « Cédez le passage », qui est prioritaire ?","options":["Le véhicule qui entre, s'il vient de la droite","Les véhicules déjà engagés dans l'anneau","Les véhicules qui vont quitter le rond-point à la prochaine sortie","Le premier véhicule arrivé à hauteur du Cédez le passage"],"correctIndex":1,"explanation":"Dans la très grande majorité des ronds-points français, un panneau cédez-le-passage impose de laisser la priorité aux véhicules déjà engagés dans l'anneau.","scene":"rond_point"},
  {"id":"kq7","type":"knowledge","theme":"circulation","question":"Que signifie un panneau STOP à une intersection ?","options":["Ralentir fortement puis passer si la voie est libre","S'arrêter si un véhicule prioritaire est visible","S'arrêter complètement, même si aucun véhicule n'arrive","Céder le passage sans obligation de s'arrêter"],"correctIndex":2,"explanation":"Le panneau STOP impose un arrêt complet du véhicule, même en l'absence de circulation visible, avant de repartir si la voie est libre."},
  {"id":"kq8","type":"knowledge","theme":"circulation","question":"Quelle est la différence entre un panneau « Cédez le passage » et un panneau STOP ?","options":["Le cédez-le-passage impose un arrêt total, le stop seulement si un véhicule arrive","Le stop s'applique aux routes de campagne, le cédez-le-passage aux villes","Le stop donne la priorité, le cédez-le-passage la retire à tous les autres usagers","Le stop impose un arrêt total, le cédez le passage non si la voie est libre"],"correctIndex":3,"explanation":"Le STOP oblige toujours à un arrêt complet, alors que le cédez-le-passage permet de continuer sans s'arrêter si la voie est réellement libre."},
  {"id":"kq9","type":"knowledge","theme":"circulation","question":"Quelle distance latérale minimale un automobiliste doit-il laisser en dépassant un cycliste ?","options":["1 mètre en agglomération, 1,5 mètre hors agglomération","1,5 mètre en agglomération, 2 mètres hors agglomération","1 mètre en agglomération, 2 mètres hors agglomération","50 centimètres en agglomération, 1 mètre hors agglomération"],"correctIndex":0,"explanation":"La loi impose une distance latérale de sécurité d'au moins 1 mètre en agglomération et 1,5 mètre hors agglomération lors d'un dépassement de cycliste."},
  {"id":"kq10","type":"knowledge","theme":"circulation","question":"Le franchissement d'une ligne blanche continue pour dépasser est :","options":["Autorisé si la route est droite et la voie libre en face","Interdit, même si la visibilité est parfaite","Toléré de nuit, quand les phares montrent la voie libre","Autorisé en dessous de 50 km/h en agglomération"],"correctIndex":1,"explanation":"Une ligne continue interdit tout franchissement, y compris pour dépasser, car elle signale un manque de visibilité ou un danger.","scene":"ligne_continue"},
  {"id":"kq11","type":"knowledge","theme":"circulation","question":"Sur autoroute, par temps de pluie, la vitesse maximale autorisée est :","options":["120 km/h, soit 10 de moins","90 km/h, soit 40 de moins","110 km/h, soit 20 de moins","100 km/h, soit 30 de moins"],"correctIndex":2,"explanation":"Par temps de pluie, la vitesse maximale sur autoroute est abaissée de 130 à 110 km/h en raison de l'allongement des distances de freinage."},
  {"id":"kq12","type":"knowledge","theme":"circulation","question":"En agglomération, sauf indication contraire, la vitesse est limitée à :","options":["30 km/h dans les grandes villes","70 km/h sur les axes à 2 voies","60 km/h dans les rues à double sens","50 km/h, sauf signalisation contraire"],"correctIndex":3,"explanation":"La vitesse par défaut en agglomération est de 50 km/h, sauf signalisation particulière indiquant une autre limite (zone 30, zone de rencontre...)."},
  {"id":"kq13","type":"knowledge","theme":"circulation","question":"Dans une zone 30, la vitesse maximale autorisée est :","options":["30 km/h pour tous les véhicules de la zone","20 km/h, comme dans une zone de rencontre","40 km/h, comme dans les rues résidentielles","50 km/h, avec 30 aux abords des écoles"],"correctIndex":0,"explanation":"Une zone 30, signalée par des panneaux d'entrée et de sortie, limite la vitesse à 30 km/h pour l'ensemble de la zone concernée."},
  {"id":"kq14","type":"knowledge","theme":"circulation","question":"La distance de sécurité entre deux véhicules qui se suivent doit permettre de respecter :","options":["Au moins 5 mètres, quelle que soit la vitesse","Au moins 2 secondes avec le véhicule qui précède","La longueur de deux véhicules par tranche de 50 km/h","Au moins 1 seconde, y compris sur route mouillée"],"correctIndex":1,"explanation":"La règle des deux secondes permet d'estimer une distance de sécurité suffisante adaptée à la vitesse, en comptant le temps entre le passage du véhicule précédent et le sien à un même point fixe."},
  {"id":"kq15","type":"knowledge","theme":"circulation","question":"Avant de changer de direction ou de voie, un conducteur doit :","options":["Actionner son clignotant au moment même d'entamer la manœuvre","Faire un appel de phares pour signaler son intention","Actionner son clignotant suffisamment tôt avant la manœuvre","Ralentir et attendre que les autres usagers s'écartent"],"correctIndex":2,"explanation":"Le clignotant doit être actionné suffisamment tôt avant de tourner ou de changer de voie, pour informer clairement les autres usagers de son intention."},
  {"id":"kq16","type":"knowledge","theme":"circulation","question":"À un feu orange clignotant, un conducteur doit :","options":["S'arrêter, comme à un feu rouge","Passer en priorité sur les autres","Passer sans ralentir si c'est libre","Ralentir et appliquer la priorité à droite"],"correctIndex":3,"explanation":"Un feu orange clignotant signale un carrefour à prudence renforcée : les règles de priorité normales, notamment la priorité à droite, s'appliquent."},
  {"id":"kq17","type":"knowledge","theme":"circulation","question":"En sortant d'un parking ou d'un chemin privé pour s'engager sur une route, un conducteur doit :","options":["Céder le passage à tous les usagers de la route","Passer en priorité s'il n'y a aucun panneau sur la route","Céder le passage seulement aux véhicules venant de la gauche","Appliquer la priorité à droite, comme à un carrefour classique"],"correctIndex":0,"explanation":"Un véhicule qui débouche d'un accès privé, d'un parking ou d'un chemin de terre doit toujours céder le passage à la circulation déjà engagée sur la route."},
  {"id":"kq18","type":"knowledge","theme":"circulation","question":"La bande d'arrêt d'urgence sur autoroute peut être empruntée :","options":["Librement quand la circulation est très dense","Uniquement en cas de panne ou d'urgence","Pour sortir plus vite d'un bouchon, à vitesse réduite","Par les motos et les deux-roues à moteur, à vitesse réduite"],"correctIndex":1,"explanation":"La bande d'arrêt d'urgence est strictement réservée aux véhicules en panne, aux urgences et aux véhicules de secours ; y circuler ou s'y arrêter sans motif est interdit."},
  {"id":"kq19","type":"knowledge","theme":"circulation","question":"Sur autoroute, la vitesse minimale imposée sur la voie de gauche par conditions normales est :","options":["60 km/h, tant que la circulation est fluide","100 km/h, sauf lors d'un dépassement","80 km/h, tant que la circulation est fluide","Aucune, la voie est libre de toute contrainte"],"correctIndex":2,"explanation":"Sur autoroute, la vitesse minimale sur la voie la plus à gauche (hors dépassement) est fixée à 80 km/h afin de fluidifier la circulation."},
  {"id":"kq20","type":"knowledge","theme":"circulation","question":"Pour dépasser un autre véhicule, il faut avant tout :","options":["Se coller au véhicule pour pouvoir le doubler vite","Faire un appel de phares puis se déporter","Attendre que le véhicule ralentisse pour le doubler","Vérifier la visibilité et l'absence de danger"],"correctIndex":3,"explanation":"Avant tout dépassement, il faut vérifier la visibilité, l'absence de véhicule en face ou en train de doubler, et signaler son intention avant de se déporter."},
  {"id":"kq21","type":"knowledge","theme":"circulation","question":"Un panneau annonçant une intersection où tu es prioritaire :","options":["N'annule pas l'obligation de rester vigilant","Dispense de regarder à droite et à gauche avant de passer","Supprime l'obligation de céder aux piétons engagés","Ne s'applique que de jour, pas de nuit"],"correctIndex":0,"explanation":"Même annoncé prioritaire, un conducteur doit rester vigilant : un autre usager peut ne pas respecter la priorité, notamment un piéton ou un véhicule ne cédant pas le passage."},
  {"id":"kq22","type":"knowledge","theme":"circulation","question":"Sur une route à trois voies avec sens de circulation alterné au centre, la voie centrale sert :","options":["À la circulation des véhicules lents dans les deux sens","Au dépassement, de façon temporaire et prudente","À l'arrêt d'urgence en cas de panne ou d'accident","Au sens de circulation le plus chargé, selon l'heure"],"correctIndex":1,"explanation":"Sur ce type de route, la voie centrale est réservée au dépassement temporaire dans un sens ou dans l'autre, et doit être quittée dès la manœuvre terminée."},
  {"id":"kq23","type":"knowledge","theme":"circulation","question":"À un carrefour à sens giratoire, il faut céder le passage :","options":["Aux véhicules qui entrent par ta droite","Aux véhicules qui s'apprêtent à sortir du giratoire","Aux véhicules déjà engagés dans l'anneau","Aux cyclistes et deux-roues, mais pas aux voitures"],"correctIndex":2,"explanation":"Sauf signalisation contraire exceptionnelle, les véhicules circulant déjà dans l'anneau du giratoire sont prioritaires sur ceux qui souhaitent y entrer.","scene":"rond_point"},
  {"id":"kq24","type":"knowledge","theme":"circulation","question":"Le clignotant doit être coupé :","options":["Dès que le véhicule a commencé à tourner","À l'arrêt complet du véhicule","Après avoir parcouru 100 mètres dans la nouvelle direction","Dès que la manœuvre de changement de direction est terminée"],"correctIndex":3,"explanation":"Une fois le changement de direction ou de voie effectué, le clignotant doit être coupé pour ne pas induire les autres usagers en erreur."},
  {"id":"kq25","type":"knowledge","theme":"conducteur","question":"Quel est le taux d'alcoolémie maximal autorisé avec un permis classique en France ?","options":["0,5 g/L de sang","0,2 g/L de sang pour tous les conducteurs","0,8 g/L de sang, seuil du délit","0,4 g/L de sang en agglomération"],"correctIndex":0,"explanation":"Le taux légal maximal pour un permis classique est de 0,5 gramme d'alcool par litre de sang, soit 0,25 mg par litre d'air expiré."},
  {"id":"kq26","type":"knowledge","theme":"conducteur","question":"Pour un conducteur en permis probatoire, le taux limite d'alcoolémie est :","options":["0,5 g/L de sang, comme tout conducteur","0,2 g/L de sang","0,3 g/L de sang pendant deux ans","0 g/L de sang, tolérance zéro"],"correctIndex":1,"explanation":"Pendant la période probatoire, le taux d'alcoolémie autorisé est abaissé à 0,2 g/L de sang, soit une quasi-tolérance zéro."},
  {"id":"kq27","type":"knowledge","theme":"conducteur","question":"Concernant les stupéfiants au volant, la règle est :","options":["Toléré sous un seuil fixé, comme pour l'alcool","Autorisé si le dernier usage date de la veille","Tolérance zéro, quel que soit le taux détecté","Toléré en cas d'usage ponctuel sans accident"],"correctIndex":2,"explanation":"Pour les stupéfiants, la loi française applique une tolérance zéro : la moindre trace détectée dans l'organisme est sanctionnée."},
  {"id":"kq28","type":"knowledge","theme":"conducteur","question":"Utiliser une oreillette ou un casque au volant en France est :","options":["Autorisé si les mains restent sur le volant","Toléré sur autoroute, où la conduite est monotone","Autorisé s'il ne couvre qu'une seule oreille","Interdit, comme le téléphone tenu en main"],"correctIndex":3,"explanation":"Le port d'une oreillette ou d'un casque audio au volant est interdit, car il isole le conducteur des bruits environnants indispensables à la conduite."},
  {"id":"kq29","type":"knowledge","theme":"conducteur","question":"Tenir son téléphone en main au volant expose à :","options":["Une amende de 135€ et un retrait de 3 points","Une amende de 90€ et un retrait de 1 point si l'appel est bref","Une amende de 68€ sans retrait de points en agglomération","Une amende de 135€ et un retrait de 6 points avec suspension"],"correctIndex":0,"explanation":"Tenir son téléphone en main en conduisant est sanctionné par une amende forfaitaire de 135€ et un retrait de 3 points sur le permis."},
  {"id":"kq30","type":"knowledge","theme":"conducteur","question":"Les signes annonciateurs de la fatigue au volant comprennent :","options":["Un regain d'énergie et des réflexes plus vifs en fin de trajet","Bâillements, yeux qui piquent et perte de concentration","Des mains moites et un rythme cardiaque qui s'accélère","Une envie soudaine d'accélérer et une impression de lucidité"],"correctIndex":1,"explanation":"Bâillements répétés, yeux qui piquent, paupières lourdes et perte de concentration sont des signaux d'alerte à prendre au sérieux avant qu'il ne soit trop tard."},
  {"id":"kq31","type":"knowledge","theme":"conducteur","question":"Que faire dès les premiers signes de somnolence au volant ?","options":["Ouvrir la fenêtre, mettre la radio et rouler jusqu'à la prochaine aire","Boire un café et reprendre la route sans attendre","S'arrêter au plus vite pour faire une pause ou dormir","Réduire la vitesse de 20 km/h et poursuivre le trajet"],"correctIndex":2,"explanation":"Face aux signes de somnolence, il faut s'arrêter au plus vite : seule une vraie pause, voire une sieste courte, restaure réellement la vigilance."},
  {"id":"kq32","type":"knowledge","theme":"conducteur","question":"Les bandes rugueuses (ou bandes sonores) situées sur le bas-côté de certaines routes servent à :","options":["Signaler une zone de limitation de vitesse à venir","Matérialiser une voie réservée aux véhicules lents","Améliorer l'adhérence des véhicules par temps de pluie","Alerter un conducteur qui s'endort ou sort de sa voie"],"correctIndex":3,"explanation":"Ces bandes rugueuses provoquent un bruit et des vibrations qui alertent un conducteur somnolent en train de sortir de sa voie."},
  {"id":"kq33","type":"knowledge","theme":"conducteur","question":"Concernant les médicaments et la conduite, un pictogramme de niveau 3 (fond rouge) signifie :","options":["Danger : ne pas conduire sans avis médical","Prudence : le médicament peut gêner, mais conduire reste possible","Vigilance : conduire avec prudence après lecture de la notice","Information : le risque n'existe qu'avec de l'alcool en plus"],"correctIndex":0,"explanation":"Le pictogramme rouge (niveau 3) signale un danger potentiellement grave pour la conduite : il faut impérativement consulter un médecin avant de prendre le volant."},
  {"id":"kq34","type":"knowledge","theme":"conducteur","question":"La vision périphérique d'un conducteur :","options":["S'élargit quand la vitesse augmente, ce qui aide à anticiper","Se réduit quand la vitesse augmente","Reste identique quelle que soit la vitesse","Se réduit quand la vitesse diminue, le regard se fixant"],"correctIndex":1,"explanation":"Plus la vitesse augmente, plus le champ de vision périphérique se rétrécit, ce qui réduit la perception des dangers latéraux."},
  {"id":"kq35","type":"knowledge","theme":"conducteur","question":"Un angle mort est :","options":["Une zone toujours visible dans les rétroviseurs extérieurs","Une zone masquée par les phares lors d'un croisement de nuit","Une zone non visible de face ni dans les rétroviseurs","Un défaut de réglage du rétroviseur intérieur du véhicule"],"correctIndex":2,"explanation":"L'angle mort désigne les zones proches du véhicule que le conducteur ne peut pas voir directement ni dans ses rétroviseurs, d'où le besoin de tourner la tête avant de changer de direction."},
  {"id":"kq36","type":"knowledge","theme":"conducteur","question":"À quel âge minimum peut-on commencer la conduite accompagnée (AAC) en France ?","options":["17 ans, avec l'accord des parents et le code","16 ans, après un stage de sensibilisation","18 ans, dès l'obtention du code","15 ans, après la formation initiale"],"correctIndex":3,"explanation":"La conduite accompagnée est accessible dès 15 ans, après avoir suivi une formation initiale et réussi l'examen du code de la route."},
  {"id":"kq37","type":"knowledge","theme":"conducteur","question":"La durée du permis probatoire est de :","options":["3 ans, réduite à 2 ans en cas de conduite accompagnée","2 ans, réduite à 1 an en cas de conduite accompagnée","3 ans, réduite à 1 an après un stage de récupération","1 an, quel que soit le mode d'apprentissage suivi"],"correctIndex":0,"explanation":"Le permis probatoire dure normalement 3 ans, réduit à 2 ans pour les conducteurs ayant suivi la conduite accompagnée (AAC)."},
  {"id":"kq38","type":"knowledge","theme":"conducteur","question":"Un conducteur qui perd tous ses points de permis :","options":["Récupère automatiquement ses points au bout de 3 mois","Voit son permis invalidé et doit repasser l'examen après un délai","Garde son permis mais ne conduit que de jour, accompagné","Reçoit un nouveau capital de 12 points après un stage obligatoire"],"correctIndex":1,"explanation":"La perte de la totalité des points entraîne l'invalidation du permis : il faut respecter un délai avant de pouvoir repasser le code et la conduite."},
  {"id":"kq39","type":"knowledge","theme":"conducteur","question":"Un taux d'alcoolémie égal ou supérieur à 0,8 g/L de sang constitue :","options":["Une contravention de 5e classe sans suspension possible du permis","Une contravention de 4e classe, comme entre 0,5 et 0,8 g/L","Un délit passible d'une amende, d'une suspension du permis et de prison","Une faute administrative sanctionnée par un simple retrait de points"],"correctIndex":2,"explanation":"Au-delà de 0,8 g/L, l'infraction devient un délit : amende pouvant atteindre 4 500€, suspension ou annulation du permis, voire peine de prison en cas de récidive ou d'accident."},
  {"id":"kq40","type":"knowledge","theme":"conducteur","question":"Après combien d'heures de conduite continue est-il recommandé de faire une pause ?","options":["Toutes les 30 minutes, même sur un trajet court","Toutes les six heures, avec une pause d'une heure","Après 4 heures de conduite, quelle que soit la distance","Environ toutes les deux heures de conduite"],"correctIndex":3,"explanation":"Il est recommandé de faire une vraie pause de 15 à 20 minutes toutes les deux heures environ, ou tous les 200 km, pour préserver sa vigilance."},
  {"id":"kq41","type":"knowledge","theme":"conducteur","question":"Les stages de récupération de points permettent de récupérer :","options":["Jusqu'à 4 points, sans dépasser le plafond, une fois par an","Jusqu'à 6 points, sans dépasser le plafond, deux fois par an","Jusqu'à 2 points par stage, dans la limite de trois stages par an","Les points perdus depuis 3 ans, une fois par permis"],"correctIndex":0,"explanation":"Un stage de sensibilisation à la sécurité routière permet de récupérer jusqu'à 4 points, sans dépasser le plafond du permis, et n'est valable qu'une fois par période de 12 mois."},
  {"id":"kq42","type":"knowledge","theme":"conducteur","question":"La consommation de cannabis avant de conduire :","options":["N'altère les réflexes qu'en cas de consommation importante","Altère les réflexes et la perception pendant plusieurs heures","N'est détectable qu'après 24 heures, donc sans risque immédiat","Ne présente un danger qu'associé à de l'alcool"],"correctIndex":1,"explanation":"Le cannabis altère les réflexes, la coordination et la perception des distances pendant plusieurs heures, tout en étant soumis à une tolérance zéro sur la route."},
  {"id":"kq43","type":"knowledge","theme":"route","question":"Un panneau de danger a généralement la forme :","options":["D'un cercle à fond blanc bordé de rouge","D'un carré à fond bleu avec pictogramme blanc","D'un triangle à fond blanc bordé de rouge","D'un losange à fond jaune bordé de noir"],"correctIndex":2,"explanation":"Les panneaux de danger sont traditionnellement des triangles à fond blanc avec une bordure rouge, annonçant un risque particulier sur la route."},
  {"id":"kq44","type":"knowledge","theme":"route","question":"Un panneau d'interdiction a généralement la forme :","options":["D'un cercle à fond bleu","D'un triangle à fond jaune","D'un carré à fond vert","D'un cercle à fond blanc bordé de rouge"],"correctIndex":3,"explanation":"Les panneaux d'interdiction sont ronds, avec un fond généralement blanc et une bordure rouge, parfois un pictogramme barré."},
  {"id":"kq45","type":"knowledge","theme":"route","question":"Un panneau d'obligation a généralement la forme :","options":["Un cercle à fond bleu et pictogramme blanc","Un triangle à fond blanc bordé de rouge","Un carré à fond blanc bordé de noir","Un octogone à fond rouge bordé de blanc"],"correctIndex":0,"explanation":"Les panneaux d'obligation sont ronds avec un fond bleu, indiquant une direction ou un comportement obligatoire (piste cyclable, vitesse minimale...)."},
  {"id":"kq46","type":"knowledge","theme":"route","question":"Les panneaux d'indication (parkings, services, directions) ont le plus souvent la forme :","options":["D'un triangle à fond blanc bordé de rouge","D'un carré ou rectangle, fond bleu ou vert","D'un cercle à fond blanc bordé de rouge","D'un losange à fond jaune bordé de noir"],"correctIndex":1,"explanation":"Les panneaux d'indication sont carrés ou rectangulaires, à fond bleu (ou vert sur autoroute) et donnent des informations utiles sans imposer d'obligation."},
  {"id":"kq47","type":"knowledge","theme":"route","question":"Une ligne blanche continue au sol signifie :","options":["Le franchissement est autorisé à vitesse réduite","Elle réserve la voie aux véhicules prioritaires","Le franchissement est interdit, quelle que soit la manœuvre","Elle autorise le stationnement sur le bas-côté"],"correctIndex":2,"explanation":"Une ligne continue interdit tout franchissement, quelle que soit la manœuvre envisagée, car elle marque une zone où la visibilité ou la sécurité est insuffisante.","scene":"ligne_continue"},
  {"id":"kq48","type":"knowledge","theme":"route","question":"Une ligne blanche discontinue au sol signifie :","options":["Le franchissement est interdit, même pour dépasser un cycliste","Elle signale une sortie de voie rapide dans les 500 mètres","Elle impose de céder le passage à la prochaine intersection","Le franchissement est autorisé si la manœuvre est sûre"],"correctIndex":3,"explanation":"Une ligne discontinue autorise le franchissement, par exemple pour dépasser ou changer de voie, à condition que la manœuvre soit faite en toute sécurité.","scene":"ligne_discontinue"},
  {"id":"kq49","type":"knowledge","theme":"route","question":"Lorsqu'une ligne continue et une ligne discontinue sont accolées, la règle à respecter est celle :","options":["De la ligne la plus proche de son propre véhicule","De la ligne continue, qui prime toujours sur la discontinue","De la ligne discontinue, qui prime si la visibilité est bonne","De la ligne la plus éloignée de son véhicule, côté sens inverse"],"correctIndex":0,"explanation":"C'est la ligne située du côté où circule le véhicule qui s'applique : si elle est continue de son côté, le franchissement est interdit ; si elle est discontinue, il est autorisé sous conditions de sécurité."},
  {"id":"kq50","type":"knowledge","theme":"route","question":"La signalisation temporaire de chantier, généralement de couleur jaune-orange :","options":["A une valeur indicative et laisse prévaloir la signalisation permanente","Prévaut sur la signalisation permanente en cas de contradiction","Ne s'applique qu'aux véhicules de chantier et aux riverains","N'est valable que de nuit, entre 20 h et 6 h"],"correctIndex":1,"explanation":"En cas de chantier ou de danger temporaire, la signalisation jaune-orange prévaut sur la signalisation permanente, le temps que dure la situation."},
  {"id":"kq51","type":"knowledge","theme":"route","question":"Sur autoroute, les panneaux de direction sont généralement de couleur :","options":["Verte, avec inscriptions blanches","Blanche, avec inscriptions noires","Bleue, avec inscriptions blanches","Jaune, avec inscriptions noires"],"correctIndex":2,"explanation":"Les panneaux de direction sur autoroute sont bleus, tandis que ceux des routes nationales sont généralement verts et ceux des petites routes blancs."},
  {"id":"kq52","type":"knowledge","theme":"route","question":"Une voie réservée aux bus est le plus souvent signalée par :","options":["Un panneau STOP placé à chaque arrêt de bus le long de la voie","Un simple marquage jaune au sol, sans panneau particulier à l'entrée","Une ligne continue jaune au bord de la chaussée, comme pour un arrêt interdit","Un marquage au sol et un panneau spécifique, parfois avec le mot « BUS »"],"correctIndex":3,"explanation":"Ces voies sont identifiées par un marquage au sol dédié et une signalisation verticale spécifique, réservant leur usage aux bus (et parfois taxis, vélos)."},
  {"id":"kq53","type":"knowledge","theme":"route","question":"Une bande cyclable se différencie d'une piste cyclable par le fait qu'elle :","options":["Est simplement marquée au sol, sur la chaussée partagée","Est séparée de la chaussée par une bordure ou un terre-plein","Est réservée aux piétons et aux cyclistes sur le trottoir","Se trouve sur le trottoir, avec un revêtement de couleur différente"],"correctIndex":0,"explanation":"La bande cyclable est un espace délimité par un marquage au sol sur la chaussée, alors que la piste cyclable est physiquement séparée du reste de la circulation."},
  {"id":"kq54","type":"knowledge","theme":"route","question":"Une voie verte est réservée :","options":["Aux véhicules motorisés légers dont la vitesse n'excède pas 30 km/h","Aux déplacements non motorisés : piétons, cyclistes, cavaliers","Aux piétons et aux véhicules de service, hors cyclistes et cavaliers","Aux transports en commun et aux taxis, sur des horaires précis"],"correctIndex":1,"explanation":"Une voie verte est un aménagement réservé aux usagers non motorisés : piétons, cyclistes, rollers, cavaliers, etc."},
  {"id":"kq55","type":"knowledge","theme":"route","question":"Sur une chaussée à double sens sans séparateur physique, l'axe central :","options":["Marque la limite de la zone où le stationnement est autorisé","Indique que la chaussée devient à sens unique plus loin","Sépare virtuellement les deux sens de circulation","Autorise les véhicules à rouler dessus pour dépasser"],"correctIndex":2,"explanation":"Même sans séparateur physique, l'axe central (souvent marqué) délimite les deux sens de circulation que chaque conducteur doit respecter."},
  {"id":"kq56","type":"knowledge","theme":"route","question":"Le panneau STOP est reconnaissable entre tous les panneaux car il est le seul à avoir la forme :","options":["Ronde, avec un liseré rouge","Triangulaire, pointe vers le bas","Carrée, posée sur une pointe","Octogonale, à huit côtés"],"correctIndex":3,"explanation":"Le panneau STOP a une forme octogonale unique en signalisation routière, ce qui permet de le reconnaître même de dos ou masqué partiellement."},
  {"id":"kq57","type":"knowledge","theme":"route","question":"Sur la chaussée, des flèches blanches obliques au sol avant un rétrécissement de voie servent à :","options":["Inviter les conducteurs à se rabattre progressivement","Signaler une zone où le dépassement est autorisé","Indiquer une priorité à droite à la prochaine intersection","Interdire de changer de voie sur 200 mètres"],"correctIndex":0,"explanation":"Ces flèches de rabattement invitent les conducteurs à anticiper la fusion des voies et à se rabattre en douceur, en respectant l'alternat si besoin."},
  {"id":"kq58","type":"knowledge","theme":"route","question":"Le panneau annonçant un « Cédez le passage » a la forme :","options":["D'un triangle pointe en haut, fond blanc, bordure rouge","D'un triangle pointe en bas, fond blanc, bordure rouge","D'un octogone à fond rouge, avec inscription blanche","D'un cercle à fond blanc, bordure rouge et barre oblique"],"correctIndex":1,"explanation":"Le panneau cédez-le-passage est un triangle inversé (pointe vers le bas) à fond blanc bordé de rouge, unique par cette orientation."},
  {"id":"kq59","type":"knowledge","theme":"route","question":"Un panneau à fond blanc et bordure rouge portant un chiffre indique généralement :","options":["Une vitesse minimale conseillée ici","Un numéro de route départementale","Une vitesse maximale autorisée à cet endroit","Une distance avant la ville suivante"],"correctIndex":2,"explanation":"Un panneau rond à fond blanc bordé de rouge affichant un nombre indique la vitesse maximale autorisée à cet endroit."},
  {"id":"kq60","type":"knowledge","theme":"usagers","question":"Sur un passage piéton, dès qu'un piéton est engagé ou s'apprête clairement à traverser :","options":["Il ralentit et passe derrière le piéton sans s'arrêter","Il s'arrête si le passage piéton est équipé de feux","Il ne s'arrête que si le piéton est un enfant ou une personne âgée","Il doit s'arrêter pour laisser passer le piéton"],"correctIndex":3,"explanation":"Dès qu'un piéton est engagé ou sur le point de traverser sur un passage protégé, il est prioritaire et le conducteur doit s'arrêter."},
  {"id":"kq61","type":"knowledge","theme":"usagers","question":"Un poids lourd qui tourne à droite présente un risque particulier lié :","options":["À ses angles morts, très étendus côté passager","À son absence de feux de position sur le côté droit","À sa vitesse de rotation, trop rapide dans les virages","À sa hauteur, qui masque les feux des autres usagers"],"correctIndex":0,"explanation":"Les poids lourds ont des angles morts très importants, notamment côté passager : il faut éviter de se placer à leur droite lorsqu'ils s'apprêtent à tourner."},
  {"id":"kq62","type":"knowledge","theme":"usagers","question":"Au feu rouge, un cycliste peut parfois tourner à droite (ou aller tout droit à une intersection en T) si :","options":["Il n'y a pas de véhicule en vue à l'intersection","Un panonceau spécifique l'y autorise","Il s'est arrêté complètement et a regardé avant de repartir","Le feu est rouge depuis plus de trente secondes"],"correctIndex":1,"explanation":"Un panonceau spécifique (type M12) peut autoriser les cyclistes à franchir un feu rouge pour tourner à droite ou continuer tout droit, en cédant le passage aux autres usagers prioritaires."},
  {"id":"kq63","type":"knowledge","theme":"usagers","question":"Les trottinettes électriques sont en principe autorisées à circuler :","options":["Sur les trottoirs et les pistes cyclables, mais pas sur la chaussée en agglomération","Sur la chaussée, uniquement sur les routes limitées à 30 km/h ou moins","Sur la chaussée et les aménagements cyclables, pas sur le trottoir sauf autorisation locale","Sur les trottoirs comme les piétons, à condition de rouler au pas"],"correctIndex":2,"explanation":"Les trottinettes électriques doivent circuler sur la chaussée ou les aménagements cyclables ; l'usage du trottoir est en principe interdit, sauf autorisation municipale à vitesse réduite."},
  {"id":"kq64","type":"knowledge","theme":"usagers","question":"Une personne à mobilité réduite disposant d'une carte de stationnement peut :","options":["Se garer sur les emplacements de livraison sans limite de durée","Se garer sur les trottoirs dès lors qu'il reste un passage d'un mètre","Rouler dans les voies de bus et les zones piétonnes sans autorisation","Utiliser les places réservées et bénéficier de facilités selon la réglementation locale"],"correctIndex":3,"explanation":"La carte de stationnement pour personnes handicapées donne accès à des places réservées et à certaines facilités, définies par la réglementation locale, mais ne dispense pas de respecter la sécurité."},
  {"id":"kq65","type":"knowledge","theme":"usagers","question":"La nuit, hors agglomération, un cycliste doit porter :","options":["Un gilet ou des équipements rétro-réfléchissants","Un casque muni de bandes lumineuses sur les deux côtés","Une tenue de couleur claire et une lampe frontale","Des gants et des genouillères homologués"],"correctIndex":0,"explanation":"Hors agglomération et de nuit (ou par visibilité insuffisante), le port d'un gilet ou d'équipements rétro-réfléchissants est obligatoire pour les cyclistes."},
  {"id":"kq66","type":"knowledge","theme":"usagers","question":"Face à un deux-roues motorisé, un automobiliste doit :","options":["Se tenir plus près, un deux-roues freinant sur une distance plus courte","Garder la même distance qu'avec une voiture, voire plus","Réduire la distance dès que la route est sèche et rectiligne","Laisser la distance qu'on laisserait à un cycliste en ville"],"correctIndex":1,"explanation":"Les deux-roues sont plus vulnérables et moins visibles : il faut leur laisser une distance de sécurité au moins équivalente à celle d'une voiture, voire plus grande."},
  {"id":"kq67","type":"knowledge","theme":"usagers","question":"Sur autoroute, la vitesse maximale autorisée pour un poids lourd est généralement inférieure à celle des voitures, soit environ :","options":["110 km/h par temps sec et 90 km/h par temps de pluie","80 km/h, la même limite que sur route à double sens","90 km/h pour les poids lourds de plus de 3,5 tonnes","100 km/h pour tous les véhicules de transport de marchandises"],"correctIndex":2,"explanation":"Les poids lourds sont limités à environ 90 km/h sur autoroute (selon leur catégorie), une vitesse inférieure à celle des véhicules légers."},
  {"id":"kq68","type":"knowledge","theme":"usagers","question":"Doubler un poids lourd nécessite en général :","options":["Moins de distance, car il roule plus lentement qu'une voiture","La même distance qu'une voiture dès que la route est dégagée","Un dépassement par la droite, plus court que par la gauche","Plus de distance et d'anticipation, vu sa longueur"],"correctIndex":3,"explanation":"En raison de sa longueur, dépasser un poids lourd demande davantage de distance et d'anticipation qu'un dépassement de voiture classique."},
  {"id":"kq69","type":"knowledge","theme":"usagers","question":"À proximité d'une école, un conducteur doit :","options":["Ralentir et redoubler de prudence, surtout aux heures d'entrée et de sortie","Ne ralentir que si des enfants sont déjà engagés sur la chaussée","Maintenir sa vitesse et klaxonner à l'approche de la sortie des classes","Respecter la limite de vitesse affichée sans autre précaution particulière"],"correctIndex":0,"explanation":"Aux abords des écoles, la prudence et une vitesse réduite sont indispensables, car le comportement des enfants peut être imprévisible."},
  {"id":"kq70","type":"knowledge","theme":"usagers","question":"Face à un piéton muni d'une canne blanche qui s'engage sur la chaussée, un conducteur doit :","options":["Klaxonner pour qu'il se dépêche de traverser","Ralentir, au besoin s'arrêter, et lui laisser le temps de traverser","Passer rapidement devant lui avant qu'il ne s'avance davantage","Lui faire des appels de phares pour qu'il retourne sur le trottoir"],"correctIndex":1,"explanation":"Un piéton muni d'une canne blanche est un usager vulnérable dont les déplacements sont difficiles à anticiper : le conducteur doit ralentir, au besoin s'arrêter, et lui laisser le temps de traverser sans le presser ni l'effrayer."},
  {"id":"kq71","type":"knowledge","theme":"usagers","question":"Le stationnement sur une piste cyclable est :","options":["Autorisé le temps de charger ou décharger, feux de détresse allumés","Toléré pour les véhicules de livraison pendant moins de quinze minutes","Interdit, car il force les cyclistes à se déporter sur la chaussée","Permis aux deux-roues motorisés dont la largeur ne dépasse pas un mètre"],"correctIndex":2,"explanation":"Stationner sur une piste cyclable est interdit et dangereux, car cela force les cyclistes à se déporter brusquement vers la circulation motorisée."},
  {"id":"kq72","type":"knowledge","theme":"usagers","question":"En France, la circulation inter-files des motos est autorisée, sous conditions :","options":["Sur toutes les routes, dès que la circulation est ralentie","Sur autoroutes et routes à chaussées séparées, à 50 km/h maximum","Uniquement dans les départements ayant une expérimentation","Jamais, elle reste interdite sur tout le territoire national"],"correctIndex":1,"explanation":"Depuis le 11 janvier 2025 (décret du 9 janvier 2025), l'inter-files est autorisée pour les deux-roues motorisés de largeur au plus 1 m, sur autoroutes et routes à chaussées séparées d'au moins deux voies par sens et limitées à 70 km/h ou plus, en circulation dense et continue, entre les deux voies les plus à gauche, à 50 km/h maximum. Sinon : 135 euros et 3 points."},
  {"id":"kq73","type":"knowledge","theme":"usagers","question":"Face à une personne âgée qui traverse lentement sur un passage piéton, un conducteur doit :","options":["Patienter le temps qu'il faut, sans la presser ni la contourner","Redémarrer dès qu'elle a dépassé l'axe de son véhicule","Klaxonner brièvement pour l'inciter à accélérer le pas","Lui laisser le passage jusqu'au milieu, puis repartir"],"correctIndex":0,"explanation":"Il faut laisser le temps nécessaire à toute personne traversant plus lentement, notamment les personnes âgées ou à mobilité réduite, sans mettre la pression."},
  {"id":"kq74","type":"knowledge","theme":"usagers","question":"Le port du casque pour un passager de deux-roues motorisé est :","options":["Facultatif sur un trajet court en agglomération","Obligatoire, au même titre que pour le conducteur","Facultatif pour un adulte, obligatoire pour un enfant","Obligatoire hors agglomération et sur route rapide"],"correctIndex":1,"explanation":"Le port du casque homologué est obligatoire pour le conducteur ET pour tout passager d'un deux-roues motorisé, quelle que soit la distance parcourue."},
  {"id":"kq75","type":"knowledge","theme":"usagers","question":"Face à un cycliste circulant devant soi sur une route étroite, un automobiliste doit :","options":["Klaxonner dès qu'on arrive derrière lui, puis le doubler sans attendre","Le dépasser au plus près à vitesse modérée pour limiter la gêne","Ralentir et attendre un espace suffisant pour le dépasser","Rester derrière lui en klaxonnant jusqu'à ce qu'il se range"],"correctIndex":2,"explanation":"Sur une route étroite, il vaut mieux ralentir et patienter jusqu'à disposer d'un espace suffisant pour dépasser le cycliste en toute sécurité et à distance réglementaire."},
  {"id":"kq76","type":"knowledge","theme":"reglementation","question":"Le permis de conduire français fonctionne sur un barème de :","options":["6 points maximum, quel que soit l'âge du permis","20 points maximum pour un conducteur expérimenté","15 points maximum après trois ans sans infraction","12 points maximum"],"correctIndex":3,"explanation":"Le permis de conduire dispose d'un capital initial de 12 points au maximum pour un conducteur expérimenté (hors période probatoire)."},
  {"id":"kq77","type":"knowledge","theme":"reglementation","question":"Pendant la période probatoire, le capital de points du permis est de :","options":["6 points, augmentant progressivement jusqu'à 12","8 points, augmentant de 1 point par an jusqu'à 12","12 points dès l'obtention, mais retraits doublés","3 points, puis 12 points après un an"],"correctIndex":0,"explanation":"En période probatoire, le permis démarre avec 6 points et gagne 2 points par an sans infraction (3 ans, jusqu'à 12 points). Avec la conduite accompagnée, la période dure 2 ans (+3 points par an)."},
  {"id":"kq78","type":"knowledge","theme":"reglementation","question":"Lorsqu'un conducteur perd la totalité de ses points, son permis est :","options":["Suspendu six mois, puis les points sont restitués automatiquement","Invalidé ; il doit repasser le code (et parfois la conduite) après un délai","Annulé définitivement, sans possibilité de repasser l'examen","Conservé, mais limité à la conduite accompagnée pendant un an"],"correctIndex":1,"explanation":"La perte totale des points entraîne l'invalidation du permis : le conducteur doit attendre un délai fixé par la loi avant de pouvoir repasser les examens."},
  {"id":"kq79","type":"knowledge","theme":"reglementation","question":"L'assurance responsabilité civile automobile est :","options":["Facultative pour les véhicules de plus de 10 ans qui ne roulent pas","Obligatoire seulement pour les véhicules qui roulent plus de 5 000 km par an","Obligatoire pour tout véhicule motorisé, même à l'arrêt sur la voie publique","Réservée aux véhicules professionnels ou loués, sauf à l'arrêt"],"correctIndex":2,"explanation":"Tout véhicule à moteur doit être couvert au minimum par une assurance responsabilité civile, dès lors qu'il est susceptible de circuler ou même simplement stationné sur la voie publique."},
  {"id":"kq80","type":"knowledge","theme":"reglementation","question":"Le contrôle technique d'un véhicule particulier doit être renouvelé :","options":["Tous les 3 ans, après un premier contrôle 5 ans après la mise en circulation","Tous les ans, après un premier contrôle 2 ans après la mise en circulation","Tous les 4 ans, après un premier contrôle 6 ans après la mise en circulation","Tous les 2 ans, après un premier contrôle 4 ans après la mise en circulation"],"correctIndex":3,"explanation":"Après un premier contrôle technique 4 ans après la mise en circulation, celui-ci doit ensuite être renouvelé tous les 2 ans."},
  {"id":"kq81","type":"knowledge","theme":"reglementation","question":"Conduire sans assurance expose à :","options":["Une amende importante, une possible confiscation du véhicule et d'autres sanctions","Une amende de 35 € et un simple délai pour régulariser sa situation d'assurance","Une amende de 135 € et un retrait automatique de 3 points sur le permis","Une régularisation sous huit jours, sans amende si l'assurance est souscrite ensuite"],"correctIndex":0,"explanation":"Défaut d'assurance est une infraction grave, sanctionnée par une amende pouvant être élevée, une possible confiscation du véhicule et d'autres peines complémentaires."},
  {"id":"kq82","type":"knowledge","theme":"reglementation","question":"Lors d'un contrôle routier, quels documents un conducteur de voiture doit-il pouvoir présenter ?","options":["La carte nationale d'identité, la carte grise et le livret d'entretien","Le permis de conduire et la carte grise du véhicule (certificat d'immatriculation)","Le permis de conduire, la carte grise et le dernier rapport de contrôle technique","Le permis de conduire, la facture d'achat et le certificat de cession"],"correctIndex":1,"explanation":"Le conducteur doit pouvoir présenter son permis de conduire et le certificat d'immatriculation (carte grise). Depuis le 1er avril 2024, la carte verte n'est plus exigée : les forces de l'ordre vérifient l'assurance dans le fichier des véhicules assurés (FVA)."},
  {"id":"kq83","type":"knowledge","theme":"reglementation","question":"Un excès de vitesse inférieur à 20 km/h au-dessus de la limite autorisée entraîne :","options":["Une amende et un retrait de 3 points minimum","Une amende sans retrait de points, sauf en cas de récidive","Une amende et un retrait d'au moins 1 point","Une amende et une suspension de permis de 1 mois"],"correctIndex":2,"explanation":"Même un petit excès de vitesse (moins de 20 km/h au-dessus de la limite) donne lieu à une amende et à un retrait de points, généralement 1 point."},
  {"id":"kq84","type":"knowledge","theme":"reglementation","question":"Un excès de vitesse de 50 km/h ou plus au-dessus de la limite autorisée constitue :","options":["Une infraction qui ne peut être sanctionnée que par une amende forfaitaire","Une contravention de 3e classe, avec un retrait de 2 points et sans suspension","Une faute administrative, sanctionnée uniquement par un retrait de points","Un délit, pouvant entraîner suspension du permis et lourde amende"],"correctIndex":3,"explanation":"Un grand excès de vitesse (50 km/h et plus) est un délit : il peut entraîner une suspension immédiate du permis par les forces de l'ordre, une lourde amende et une comparution devant un tribunal."},
  {"id":"kq85","type":"knowledge","theme":"reglementation","question":"Le non-respect d'un feu rouge ou d'un STOP entraîne généralement :","options":["Une amende et un retrait de 4 points","Une amende et un retrait de 2 points seulement","Une amende et un retrait de 6 points systématique","Une amende et une suspension de permis de 15 jours"],"correctIndex":0,"explanation":"Griller un feu rouge ou un STOP est sanctionné par une amende forfaitaire et un retrait de 4 points sur le permis de conduire."},
  {"id":"kq86","type":"knowledge","theme":"reglementation","question":"Le stationnement dit « très gênant » (sur trottoir, passage piéton, piste cyclable...) est sanctionné par une amende :","options":["Identique à celle d'un stationnement gênant, quel que soit le lieu","Plus élevée qu'un stationnement simplement gênant","Moins élevée qu'un stationnement gênant, car aucun usager n'est mis en danger","Plus élevée seulement dans les zones payantes situées en agglomération"],"correctIndex":1,"explanation":"Le stationnement très gênant, qui met en danger ou bloque fortement d'autres usagers, est sanctionné plus lourdement qu'un simple stationnement gênant."},
  {"id":"kq87","type":"knowledge","theme":"reglementation","question":"Le délit de fuite après un accident expose à :","options":["Une amende forfaitaire, sans conséquence pénale si les dégâts sont minimes","Une suspension du permis de 3 mois, sans poursuite devant un tribunal","De lourdes sanctions pénales, bien plus graves que l'accident lui-même","Le seul remboursement des dégâts par l'assurance, sans aucune poursuite"],"correctIndex":2,"explanation":"Quitter les lieux d'un accident sans s'identifier constitue un délit pénal grave, souvent sanctionné plus lourdement que l'accident lui-même."},
  {"id":"kq88","type":"knowledge","theme":"reglementation","question":"Vendre ou faire circuler un véhicule sans contrôle technique valide est :","options":["Autorisé pour les véhicules de plus de 10 ans, qui en sont dispensés","Autorisé si le dernier contrôle a expiré depuis moins de six mois","Autorisé entre particuliers, la règle ne visant que les professionnels","Interdit, sauf exceptions prévues par la loi"],"correctIndex":3,"explanation":"Un véhicule doit disposer d'un contrôle technique en cours de validité pour circuler ou être vendu, sauf cas particuliers prévus par la réglementation."},
  {"id":"kq89","type":"knowledge","theme":"reglementation","question":"L'immatriculation d'un véhicule doit être visible :","options":["À l'avant et à l'arrière du véhicule","À l'arrière du véhicule, et sur le pare-brise pour les véhicules neufs","Sur le pare-brise et la lunette arrière, sous forme d'autocollants","À l'arrière seulement pour les véhicules de moins de 3,5 tonnes"],"correctIndex":0,"explanation":"Un véhicule doit porter une plaque d'immatriculation réglementaire à l'avant et à l'arrière, lisible et conforme."},
  {"id":"kq90","type":"knowledge","theme":"reglementation","question":"Le défaut de port de la ceinture de sécurité entraîne :","options":["Une amende uniquement si un accident a eu lieu pendant le trajet","Une amende, et un retrait de 3 points pour le conducteur","Un simple avertissement au premier contrôle, puis une amende à la récidive","Une immobilisation du véhicule et un retrait du permis pour 3 mois"],"correctIndex":1,"explanation":"Le non-port de la ceinture est sanctionné par une amende forfaitaire de 135 €. Le conducteur perd 3 points, pour lui-même ou pour un mineur non attaché ; un passager majeur non attaché paie l'amende sans perte de points."},
  {"id":"kq91","type":"knowledge","theme":"reglementation","question":"Un conducteur récupère automatiquement la totalité de ses points de permis après :","options":["1 an sans infraction, ou 6 mois pour un retrait de 1 point","5 ans sans nouvelle infraction, ou 3 ans pour un simple retrait de 1 point","2 ans sans nouvelle infraction (3 ans en cas de délit ou de contravention grave)","4 ans sans nouvelle infraction, avec un stage de sensibilisation obligatoire"],"correctIndex":2,"explanation":"Les points sont réattribués après 2 ans sans nouvelle infraction avec retrait de points, ou 3 ans si l'une des infractions est un délit ou une contravention de 4e ou 5e classe. Un point perdu seul est récupéré après 6 mois (art. L223-6)."},
  {"id":"kq92","type":"knowledge","theme":"reglementation","question":"Un grand excès de vitesse peut entraîner une rétention immédiate du permis par les forces de l'ordre :","options":["Faux, seul un juge peut retenir un permis, après une audience","Vrai, mais seulement pour les conducteurs en période probatoire","Faux, la rétention n'est possible qu'en cas d'accident corporel","Vrai, une rétention immédiate est possible sur place"],"correctIndex":3,"explanation":"En cas de grand excès de vitesse ou d'infraction grave (alcool, stupéfiants...), les forces de l'ordre peuvent procéder à une rétention immédiate du permis sur place."},
  {"id":"kq93","type":"knowledge","theme":"reglementation","question":"Un jeune conducteur en période probatoire qui commet une infraction entraînant un retrait de 3 points ou plus :","options":["Peut être tenu de suivre un stage de sensibilisation obligatoire","Voit sa période probatoire prolongée de deux ans, sans autre obligation","Doit repasser l'épreuve pratique du permis dans un délai de trois mois","N'a aucune obligation tant que son solde reste supérieur à 3 points"],"correctIndex":0,"explanation":"En période probatoire, une infraction entraînant le retrait d'au moins 3 points peut obliger le conducteur à suivre un stage de sensibilisation à la sécurité routière."},
  {"id":"kq94","type":"knowledge","theme":"environnement","question":"L'écoconduite consiste principalement à :","options":["Maintenir un régime moteur élevé pour garder le moteur performant","Anticiper la circulation pour limiter accélérations et freinages brusques","Couper le moteur dans les descentes pour économiser du carburant","Rouler à vitesse réduite en toutes circonstances"],"correctIndex":1,"explanation":"L'écoconduite repose sur l'anticipation et la régularité de la conduite : moins d'accélérations et de freinages brusques réduisent la consommation et les émissions."},
  {"id":"kq95","type":"knowledge","theme":"environnement","question":"La vignette Crit'Air permet :","options":["De bénéficier d'un tarif réduit sur les péages d'autoroute","D'être dispensé de contrôle technique pendant deux ans","De classer les véhicules selon leur niveau de pollution, notamment pour accéder aux ZFE","De justifier du paiement de l'assurance obligatoire du véhicule"],"correctIndex":2,"explanation":"La vignette Crit'Air classe les véhicules par niveau de pollution ; elle est notamment nécessaire pour circuler dans les zones à faibles émissions (ZFE)."},
  {"id":"kq96","type":"knowledge","theme":"environnement","question":"Une zone à faibles émissions (ZFE) a pour but de :","options":["Limiter la vitesse à 30 km/h sur l'ensemble des voies d'une agglomération","Réserver l'accès du centre-ville aux seuls véhicules des résidents et des commerçants","Réduire le bruit généré par les deux-roues motorisés dans les centres-villes","Restreindre la circulation des véhicules les plus polluants dans certaines zones"],"correctIndex":3,"explanation":"Les ZFE visent à améliorer la qualité de l'air en limitant ou en interdisant l'accès des véhicules les plus polluants à certaines zones urbaines."},
  {"id":"kq97","type":"knowledge","theme":"environnement","question":"Couper le moteur lors d'un arrêt prolongé (feu long, passage à niveau) permet de :","options":["Réduire la consommation de carburant et les émissions inutiles","Augmenter les émissions de polluants au redémarrage, au point d'annuler tout gain","Abîmer le démarreur et la batterie, ce qui compense l'économie réalisée","Limiter l'usure du moteur mais sans effet sur la consommation de carburant"],"correctIndex":0,"explanation":"Couper le moteur lors d'un arrêt prolongé évite une consommation et des émissions inutiles, sans risque pour un moteur en bon état."},
  {"id":"kq98","type":"knowledge","theme":"environnement","question":"Une conduite avec des accélérations progressives, plutôt que brusques, permet de :","options":["Augmenter la puissance disponible mais consommer davantage de carburant","Réduire la consommation de carburant et les émissions de CO2","Limiter l'usure des pneus, sans effet sur la consommation","Améliorer le confort des passagers sans effet sur les rejets de CO2"],"correctIndex":1,"explanation":"Des accélérations progressives sollicitent moins le moteur et réduisent la consommation de carburant ainsi que les émissions de CO2."},
  {"id":"kq99","type":"knowledge","theme":"environnement","question":"Un entretien régulier du véhicule (filtres, moteur, pneus) contribue à :","options":["Diminuer les émissions, mais seulement sur les véhicules diesel","Réduire les émissions de CO2 sans modifier la consommation de carburant","Réduire la consommation et les émissions polluantes","Limiter le bruit du moteur sans effet sur les émissions polluantes"],"correctIndex":2,"explanation":"Un véhicule bien entretenu consomme moins et pollue moins : filtres propres, moteur réglé et pneus corrects optimisent le fonctionnement."},
  {"id":"kq100","type":"knowledge","theme":"environnement","question":"Le covoiturage contribue à réduire l'impact environnemental de la route principalement en :","options":["Diminuant le nombre de passagers dans chaque véhicule","Évitant d'avoir à entretenir son véhicule régulièrement","Ne s'appliquant qu'aux trajets de plus de 100 km","Réduisant le nombre de véhicules utilisés pour un même trajet"],"correctIndex":3,"explanation":"En partageant un même véhicule pour un trajet, le covoiturage réduit le nombre total de véhicules en circulation, donc les émissions et la congestion."},
  {"id":"kq101","type":"knowledge","theme":"environnement","question":"Des pneus sous-gonflés entraînent :","options":["Une consommation de carburant augmentée et une usure prématurée","Une consommation réduite et une usure plus régulière des pneus","Une consommation inchangée, mais un bruit de roulement plus fort","Une meilleure adhérence sur sol mouillé et une consommation stable"],"correctIndex":0,"explanation":"Des pneus sous-gonflés augmentent la résistance au roulement, ce qui accroît la consommation de carburant et use les pneus plus rapidement."},
  {"id":"kq102","type":"knowledge","theme":"environnement","question":"Rouler à vitesse stabilisée plutôt qu'en accélérant et freinant sans cesse permet de :","options":["Réduire la consommation en ville mais l'augmenter sur route","Réduire significativement la consommation de carburant","Limiter la fatigue du conducteur sans effet sur la consommation","Gagner du temps de trajet tout en consommant davantage"],"correctIndex":1,"explanation":"Une vitesse stabilisée, sans à-coups, réduit nettement la consommation de carburant par rapport à une conduite en accélérations et freinages répétés."},
  {"id":"kq103","type":"knowledge","theme":"environnement","question":"Transporter un poids inutile dans son véhicule (coffre chargé, galerie non utilisée) :","options":["N'a d'effet que sur les véhicules diesel de forte puissance","Réduit la consommation en améliorant la stabilité du véhicule","Augmente la consommation de carburant","Améliore l'aérodynamisme mais augmente l'usure des pneus"],"correctIndex":2,"explanation":"Un poids ou une résistance aérodynamique supplémentaire (charge inutile, galerie de toit) augmente la consommation de carburant du véhicule."},
  {"id":"kq104","type":"knowledge","theme":"environnement","question":"L'usage intensif de la climatisation en ville :","options":["Ne modifie pas la consommation si les vitres restent fermées","Réduit la consommation en refroidissant le moteur","Ne concerne que les véhicules électriques à batterie","Peut augmenter sensiblement la consommation de carburant"],"correctIndex":3,"explanation":"La climatisation sollicite le moteur (ou la batterie) et peut augmenter sensiblement la consommation, en particulier en usage intensif en ville."},
  {"id":"kq105","type":"knowledge","theme":"environnement","question":"Le transport routier est l'une des principales sources d'émissions de :","options":["Dioxyde de carbone (CO2), un gaz à effet de serre","Azote pur, un gaz présent naturellement dans l'air respiré","Hélium, un gaz sans effet sur le climat","Oxygène, un gaz indispensable à la respiration"],"correctIndex":0,"explanation":"Le transport routier est l'un des principaux secteurs émetteurs de CO2, un gaz à effet de serre qui contribue au réchauffement climatique."},
  {"id":"kq106","type":"knowledge","theme":"environnement","question":"Sur une place de stationnement équipée d'une borne de recharge pour véhicule électrique :","options":["Le stationnement est ouvert à tout véhicule pendant deux heures maximum","Le stationnement est réservé aux véhicules en cours de recharge","Le stationnement est réservé aux véhicules électriques, même sans recharge","Le stationnement est libre entre 20 h et 8 h pour les autres véhicules"],"correctIndex":1,"explanation":"Ces places sont réservées aux véhicules électriques ou hybrides rechargeables en cours de recharge ; les autres véhicules ne doivent pas y stationner."},
  {"id":"kq107","type":"knowledge","theme":"environnement","question":"L'utilisation du régulateur de vitesse sur autoroute, en conditions stables, peut aider à :","options":["Augmenter la vitesse moyenne sans changer la consommation","Dépasser plus facilement les véhicules plus lents","Maintenir une vitesse stable et réduire la consommation","Remplacer la vigilance du conducteur dans les virages"],"correctIndex":2,"explanation":"En maintenant une vitesse constante sur autoroute, le régulateur évite les variations inutiles de vitesse et peut contribuer à réduire la consommation."},
  {"id":"kq108","type":"knowledge","theme":"environnement","question":"Un filtre à particules encrassé sur un véhicule diesel entraîne :","options":["Une baisse de la puissance sans effet sur la pollution émise","Une réduction des émissions de particules fines mais plus de bruit","Une surconsommation d'huile moteur sans incidence sur les rejets","Une augmentation des émissions polluantes et des risques de panne"],"correctIndex":3,"explanation":"Un filtre à particules encrassé ou défaillant laisse passer davantage de particules polluantes et peut entraîner des dysfonctionnements du moteur."},
  {"id":"kq109","type":"knowledge","theme":"notions","question":"Un enfant de moins de 10 ans doit voyager :","options":["Dans un dispositif de retenue adapté à sa taille et son poids","Sur la banquette arrière avec la ceinture adulte, s'il mesure plus d'un mètre","Avec la ceinture adulte réglée en hauteur, dès qu'il sait rester assis","À l'avant, attaché avec la ceinture du véhicule, si l'airbag est actif"],"correctIndex":0,"explanation":"Tout enfant de moins de 10 ans doit être installé dans un dispositif de retenue homologué (siège auto, réhausseur) adapté à sa morphologie."},
  {"id":"kq111","type":"knowledge","theme":"notions","question":"Installer un siège enfant dos à la route à l'avant nécessite de :","options":["Reculer le siège passager au maximum et laisser l'airbag actif","Débrancher la batterie du véhicule avant chaque trajet","Désactiver l'airbag frontal passager","Incliner le dossier du siège passager pour limiter la portée de l'airbag"],"correctIndex":2,"explanation":"Un siège dos à la route ne doit jamais être installé à l'avant avec un airbag frontal actif : celui-ci doit impérativement être désactivé, sous peine de danger grave pour l'enfant."},
  {"id":"kq112","type":"knowledge","theme":"notions","question":"Un chargement qui dépasse de plus d'un mètre à l'arrière du véhicule doit :","options":["Être masqué par une bâche noire pour ne pas être éparpillé","Être signalé à partir de 3 mètres de dépassement, de jour comme de nuit","Être maintenu par une sangle, sans autre signalisation","Être signalé par un dispositif visible (panneau, tissu rouge et blanc, etc.)"],"correctIndex":3,"explanation":"Au-delà d'1 m de saillie à l'arrière (3 m maximum), le chargement doit être signalé par un dispositif visible (panneau à bandes rouges et blanches, et feu rouge ou dispositif réfléchissant la nuit)."},
  {"id":"kq113","type":"knowledge","theme":"notions","question":"Avec un permis B classique, on peut en général tracter une remorque à condition que :","options":["Le poids total en charge de l'ensemble ne dépasse pas certaines limites réglementaires","Le conducteur ait au moins cinq ans de permis, quel que soit le poids de la remorque attelée","Le véhicule tracteur pèse plus de 1 500 kg à vide, sans autre condition sur le poids total","Le poids de la remorque ne dépasse pas 500 kg, quel que soit le véhicule"],"correctIndex":0,"explanation":"Le permis B permet de tracter une remorque dans certaines limites de poids total en charge de l'ensemble véhicule + remorque, au-delà desquelles une formation ou catégorie supplémentaire est nécessaire."},
  {"id":"kq114","type":"knowledge","theme":"notions","question":"Un chargement mal arrimé qui se détache sur la route constitue :","options":["Une faute sanctionnée seulement en cas d'accident","Une infraction pouvant être sanctionnée, en plus du danger créé","Un incident dont seul le propriétaire du chargement est responsable","Une infraction uniquement pour les poids lourds et les transports de marchandises"],"correctIndex":1,"explanation":"Un chargement mal arrimé qui se détache est dangereux et engage la responsabilité du conducteur, en plus d'être une infraction sanctionnable."},
  {"id":"kq115","type":"knowledge","theme":"notions","question":"Le poids total en charge d'un véhicule (chargement inclus) doit respecter :","options":["Le poids à vide indiqué sur la carte grise, passagers et bagages exclus","La charge utile maximale de 500 kg fixée pour tous les véhicules de tourisme","Le poids total autorisé en charge (PTAC) indiqué sur la carte grise","La limite de 3,5 tonnes, quel que soit le modèle ou l'usage du véhicule"],"correctIndex":2,"explanation":"Le poids total en charge doit respecter le PTAC indiqué sur le certificat d'immatriculation, sous peine de sanctions et de risques pour la tenue de route."},
  {"id":"kq116","type":"knowledge","theme":"notions","question":"Le covoiturage régulier permet notamment de :","options":["Dégager un bénéfice sur chaque trajet grâce à un tarif fixé librement par le conducteur","Se dispenser de l'assurance du véhicule pour les passagers transportés","Être dispensé de la ceinture de sécurité sur les trajets de courte distance en ville","Réduire le nombre de véhicules en circulation et partager les frais de trajet"],"correctIndex":3,"explanation":"Le covoiturage permet de réduire le nombre de véhicules utilisés pour un même trajet tout en partageant les frais entre les passagers."},
  {"id":"kq117","type":"knowledge","theme":"notions","question":"Le transport d'un animal dans le véhicule doit se faire :","options":["De façon sécurisée (caisse de transport, harnais, grille de séparation...)","Sur la plage arrière, dès lors qu'il reste calme pendant le trajet","Sur le siège passager avant, tenu en laisse par le conducteur","Dans un sac posé sur les genoux d'un passager, sans autre dispositif"],"correctIndex":0,"explanation":"Un animal doit être transporté de manière sécurisée, afin de ne pas gêner la conduite ni risquer de se blesser ou de blesser les occupants en cas de freinage."},
  {"id":"kq118","type":"knowledge","theme":"notions","question":"Sur autoroute, un ensemble (voiture + caravane) dont le PTRA dépasse 3,5 tonnes est limité à :","options":["90 km/h, quelles que soient les conditions météorologiques","110 km/h, comme par temps de pluie pour un véhicule seul","100 km/h, comme les véhicules de transport en commun","130 km/h, comme un véhicule léger circulant sans remorque"],"correctIndex":0,"explanation":"La vitesse maximale d'un ensemble dont le PTRA (inscrit sur la carte grise) dépasse 3,5 t est de 90 km/h sur autoroute. Si le PTRA reste inférieur ou égal à 3,5 t, la limite de 130 km/h s'applique."},
  {"id":"kq119","type":"knowledge","theme":"notions","question":"Avec une caravane large tractée, il est souvent nécessaire d'équiper le véhicule de :","options":["Un système de freinage hydraulique sur toutes les roues du véhicule tracteur","Feux de brouillard supplémentaires à l'arrière du véhicule tracteur","Rétroviseurs additionnels élargis","Pneus à carcasse renforcée sur l'essieu avant"],"correctIndex":2,"explanation":"Des rétroviseurs élargis peuvent être nécessaires pour compenser la largeur de la caravane et assurer une visibilité suffisante sur les côtés."},
  {"id":"kq120","type":"knowledge","theme":"notions","question":"Un enfant ne peut en principe pas être installé à l'avant du véhicule :","options":["S'il mesure moins de 1,35 m, sans aucune exception possible, même sans place arrière","Seulement s'il a moins de 6 ans, avec une dérogation pour les trajets courts en ville","S'il a moins de 12 ans, sauf s'il est accompagné d'un adulte à l'arrière","S'il est âgé de moins de 10 ans, sauf conditions particulières prévues par la loi"],"correctIndex":3,"explanation":"En principe, un enfant de moins de 10 ans ne doit pas être installé à l'avant, sauf exceptions prévues (véhicule sans place arrière, sièges arrière déjà occupés par d'autres enfants, etc.), avec les précautions adaptées."},
  {"id":"kq121","type":"knowledge","theme":"notions","question":"Le passager d'une moto ou d'un scooter doit obligatoirement :","options":["Porter un casque homologué et un équipement de protection adapté","Porter un casque seulement si le conducteur en porte un et si le trajet dépasse 20 km","Être équipé de repose-pieds, le casque n'étant exigé qu'hors agglomération","Avoir au moins 16 ans et un permis de la catégorie du véhicule conduit"],"correctIndex":0,"explanation":"Comme le conducteur, tout passager d'un deux-roues motorisé doit porter un casque homologué et un équipement de protection adapté (gants notamment)."},
  {"id":"kq122","type":"knowledge","theme":"notions","question":"La conduite accompagnée (AAC) permet à un jeune conducteur de :","options":["Conduire dès 16 ans, accompagné uniquement d'un moniteur d'auto-école titulaire du permis","Conduire dès 15 ans accompagné d'un conducteur expérimenté, avant de passer seul","Passer l'épreuve pratique dès 15 ans, avant même d'avoir roulé en étant accompagné","Conduire dès 16 ans seul sur routes départementales en dehors des autoroutes"],"correctIndex":1,"explanation":"L'apprentissage anticipé de la conduite (AAC) permet de conduire dès 15 ans accompagné d'un conducteur expérimenté, avant de se présenter à l'épreuve pratique du permis."},
  {"id":"kq123","type":"knowledge","theme":"notions","question":"Un chargement dépassant l'arrière du véhicule de plus d'un mètre doit être signalé, y compris de nuit, par :","options":["Un simple tissu blanc noué à l'extrémité du chargement, suffisant de jour comme de nuit","Une seconde plaque d'immatriculation fixée sur le chargement","Un panneau ou dispositif réglementaire visible, y compris réfléchissant la nuit","Un panneau triangulaire de présignalisation posé sur la chaussée à chaque arrêt du véhicule chargé"],"correctIndex":2,"explanation":"Un chargement qui dépasse significativement doit être signalé par un dispositif réglementaire (panneau à bandes rouges et blanches), visible également de nuit grâce à un système réfléchissant."},
  {"id":"kq124","type":"knowledge","theme":"securite_passagers","question":"Le port de la ceinture de sécurité est obligatoire :","options":["Pour le conducteur et le passager avant, mais pas à l'arrière en ville","Pour les occupants, sauf en agglomération où la vitesse est limitée","Pour le conducteur et les passagers adultes, pas pour les enfants","Pour tous les occupants du véhicule, à l'avant comme à l'arrière"],"correctIndex":3,"explanation":"La ceinture de sécurité doit être portée par tous les occupants du véhicule, à l'avant comme à l'arrière, dès que des ceintures sont installées."},
  {"id":"kq125","type":"knowledge","theme":"securite_passagers","question":"Un conducteur surpris sans ceinture de sécurité est sanctionné par :","options":["Une amende de 135 € et un retrait de 3 points","Une amende de 90 € et un retrait de 2 points","Une amende de 135 € sans retrait de points","Une amende de 68 € et un retrait de 1 point"],"correctIndex":0,"explanation":"Le conducteur non attaché encourt une amende forfaitaire de 135 € et un retrait de 3 points (R412-1). Un passager majeur non attaché paie lui-même l'amende de 135 €, sans retrait de points pour le conducteur."},
  {"id":"kq126","type":"knowledge","theme":"securite_passagers","question":"Le port du casque est obligatoire :","options":["Pour le conducteur, le passager pouvant s'en passer s'il est majeur","Pour le conducteur et tout passager d'un deux-roues motorisé","Pour tous les trajets hors agglomération, sur route ou autoroute","Pour les motos de forte cylindrée, pas pour les scooters"],"correctIndex":1,"explanation":"Le casque homologué est obligatoire aussi bien pour le conducteur que pour tout passager d'un deux-roues motorisé, quelle que soit la distance à parcourir."},
  {"id":"kq127","type":"knowledge","theme":"securite_passagers","question":"Un siège enfant installé dos à la route à l'avant impose :","options":["De laisser l'airbag actif en réglant le siège au plus loin","De reculer le siège au maximum en gardant l'airbag frontal actif","De désactiver impérativement l'airbag frontal passager","D'attacher le siège avec la ceinture, sans autre précaution"],"correctIndex":2,"explanation":"Le déclenchement d'un airbag frontal sur un siège dos à la route peut gravement blesser l'enfant : la désactivation de l'airbag est impérative dans ce cas."},
  {"id":"kq128","type":"knowledge","theme":"securite_passagers","question":"Les sièges auto homologués sont généralement classés selon :","options":["La cylindrée du véhicule et la puissance de son moteur","Le nombre de points d'ancrage Isofix disponibles dans le véhicule","Le type de ceinture équipant le véhicule (2 ou 3 points)","Le poids ou la taille de l'enfant (groupes 0+ à 3 ou i-Size)"],"correctIndex":3,"explanation":"Les sièges auto sont homologués selon des groupes basés sur le poids (0+, 1, 2, 3) ou, plus récemment, selon la taille de l'enfant pour la norme i-Size."},
  {"id":"kq129","type":"knowledge","theme":"securite_passagers","question":"Un enfant de moins de 10 ans doit en principe voyager :","options":["À l'arrière du véhicule, sauf exceptions prévues par la loi","À l'avant, à condition d'être attaché par la ceinture adulte","À l'avant dès 6 ans, sans dispositif de retenue particulier","Indifféremment à l'avant ou à l'arrière selon la place disponible"],"correctIndex":0,"explanation":"Sauf exceptions prévues par la réglementation, un enfant de moins de 10 ans doit être installé à l'arrière du véhicule, dans un dispositif adapté."},
  {"id":"kq130","type":"knowledge","theme":"securite_passagers","question":"Le casque d'un motard doit impérativement être :","options":["Légèrement desserré pour ne pas gêner la respiration","Correctement attaché avec la jugulaire fermée","Fixé avec la jugulaire, sauf à basse vitesse en ville","Porté avec la visière relevée pour mieux voir la route"],"correctIndex":1,"explanation":"Un casque non attaché ne protège pas efficacement en cas de choc : la jugulaire doit toujours être correctement fermée avant de rouler."},
  {"id":"kq131","type":"knowledge","theme":"securite_passagers","question":"Le gilet de haute visibilité doit être enfilé par le conducteur :","options":["Dès le départ, il doit être porté pendant toute la conduite de nuit","Après être sorti du véhicule, une fois le triangle posé","Avant de sortir du véhicule en cas de panne ou d'accident","Dès que la nuit tombe, même en roulant en agglomération"],"correctIndex":2,"explanation":"En cas d'arrêt d'urgence ou de panne, il faut enfiler le gilet haute visibilité avant de sortir du véhicule, pour être vu par les autres usagers, en particulier de nuit ou sur autoroute."},
  {"id":"kq132","type":"knowledge","theme":"securite_passagers","question":"Une ceinture de sécurité à trois points offre :","options":["Une protection comparable à celle d'une ceinture ventrale seule","Une protection moindre mais un meilleur confort de conduite","Une meilleure protection du bassin, mais pas du buste","Une meilleure répartition des forces qu'une ceinture ventrale seule"],"correctIndex":3,"explanation":"La ceinture trois points répartit les forces sur le bassin et le buste, offrant une protection nettement supérieure à une simple ceinture ventrale."},
  {"id":"kq133","type":"knowledge","theme":"securite_passagers","question":"Les airbags du véhicule :","options":["Complètent la ceinture de sécurité mais ne la remplacent pas","Dispensent de la ceinture à l'avant sur les véhicules récents","Ne se déclenchent qu'en l'absence de ceinture attachée au moment du choc","Sont efficaces même sans ceinture dès que le véhicule roule à plus de 50 km/h"],"correctIndex":0,"explanation":"Les airbags sont conçus pour compléter la ceinture de sécurité, pas pour la remplacer : leur efficacité est optimale seulement si la ceinture est également attachée."},
  {"id":"kq134","type":"knowledge","theme":"securite_passagers","question":"Il est recommandé de maintenir un enfant dans un siège dos à la route :","options":["Jusqu'à 6 mois, âge où la nuque est suffisamment solide pour se tenir","Le plus longtemps possible, tant que sa taille le permet","Jusqu'à son premier anniversaire, avant de passer face à la route","Le moins longtemps possible, pour qu'il voie mieux la route"],"correctIndex":1,"explanation":"Voyager dos à la route protège mieux la tête et la nuque de l'enfant en cas de choc frontal ; il est donc recommandé de conserver cette position le plus longtemps possible."},
  {"id":"kq135","type":"knowledge","theme":"securite_passagers","question":"Le verrouillage de sécurité enfant sur les portières arrière sert à :","options":["Empêcher les portières de se refermer sur la main de l'enfant","Verrouiller les portières depuis l'extérieur pour empêcher le vol","Bloquer l'ouverture des portières arrière de l'intérieur","Désactiver l'airbag latéral situé dans la portière arrière"],"correctIndex":2,"explanation":"Ce dispositif empêche l'ouverture des portières arrière depuis l'intérieur, évitant qu'un enfant ne les ouvre accidentellement en roulant."},
  {"id":"kq136","type":"knowledge","theme":"securite_passagers","question":"Ne pas utiliser un dispositif de retenue adapté pour un enfant expose le conducteur à :","options":["Une amende, mais sans perte de point","Un avertissement écrit du service de police","Un retrait de points sans amende forfaitaire","Une amende et un retrait de points"],"correctIndex":3,"explanation":"L'absence de dispositif de retenue adapté pour un enfant qui doit en être équipé est sanctionnée par une amende et un retrait de points."},
  {"id":"kq137","type":"knowledge","theme":"securite_passagers","question":"Un appui-tête correctement réglé permet notamment de :","options":["Limiter le risque de coup du lapin en cas de choc arrière","Améliorer le confort du conducteur sur les longs trajets","Amortir le choc de la tête contre la vitre latérale lors d'un impact","Remplacer la ceinture sur les trajets de courte durée"],"correctIndex":0,"explanation":"Un appui-tête bien positionné, proche de la tête, limite le mouvement brusque de la nuque en cas de choc arrière et réduit le risque de traumatisme cervical."},
  {"id":"kq138","type":"knowledge","theme":"securite_passagers","question":"Concernant les vitres avant du véhicule, la réglementation impose :","options":["Une teinte foncée imposée sur les vitres avant contre l'éblouissement","Un seuil minimal de transparence du pare-brise et des vitres avant","Un seuil de transparence qui ne s'applique qu'au pare-brise","Des vitres avant opaques tolérées si elles sont homologuées"],"correctIndex":1,"explanation":"La réglementation impose un niveau minimal de transparence pour le pare-brise et les vitres avant, afin de garantir une bonne visibilité du conducteur et des autres usagers."},
  {"id":"kq139","type":"knowledge","theme":"securite_passagers","question":"En cas de choc, un passager non attaché à l'arrière :","options":["Ne présente un danger que pour lui-même, pas pour les autres","Est protégé par les airbags rideaux comme s'il était attaché","Peut être projeté et blesser les occupants de devant","Ne risque rien tant que les passagers avant sont attachés"],"correctIndex":2,"explanation":"Un passager arrière non attaché peut être projeté violemment vers l'avant lors d'un choc et blesser gravement les occupants situés devant lui, en plus de se mettre lui-même en danger."},
  {"id":"kq140","type":"knowledge","theme":"equipements","question":"Le kit de sécurité obligatoire à bord d'une voiture comprend au minimum :","options":["Un extincteur, une trousse de secours et une couverture de survie","Une roue de secours accompagnée d'un cric et d'une clé à roue","Une lampe torche et un jeu complet d'ampoules de rechange","Un triangle de présignalisation et un gilet de haute visibilité"],"correctIndex":3,"explanation":"Depuis 2008, tout véhicule doit disposer à bord d'un triangle de présignalisation et d'un gilet de haute visibilité, à utiliser en cas d'arrêt d'urgence."},
  {"id":"kq141","type":"knowledge","theme":"equipements","question":"Le système ABS (antiblocage des roues) sert à :","options":["Éviter le blocage des roues pour garder la maîtrise en freinage brusque","Raccourcir la distance de freinage sur n'importe quel revêtement, même meuble ou enneigé","Freiner à la place du conducteur dès qu'un obstacle est détecté devant","Répartir la force de freinage entre les essieux pour limiter l'usure des plaquettes"],"correctIndex":0,"explanation":"L'ABS empêche les roues de se bloquer lors d'un freinage d'urgence, ce qui permet de conserver la maîtrise de la direction du véhicule."},
  {"id":"kq142","type":"knowledge","theme":"equipements","question":"Le système ESP (contrôle électronique de stabilité) intervient principalement pour :","options":["Empêcher le blocage des roues lors d'un freinage d'urgence","Corriger une perte d'adhérence ou un début de dérapage","Maintenir une distance de sécurité avec le véhicule qui précède","Réguler la vitesse sur une valeur choisie par le conducteur"],"correctIndex":1,"explanation":"L'ESP détecte une perte d'adhérence ou un début de dérapage et freine automatiquement certaines roues pour aider à stabiliser la trajectoire du véhicule."},
  {"id":"kq143","type":"knowledge","theme":"equipements","question":"La profondeur minimale légale des sculptures d'un pneu en France est de :","options":["3 mm, seuil en dessous duquel le contrôle technique impose le remplacement","0,5 mm, seuil à partir duquel le pneu est considéré comme lisse","1,6 mm, mesurés dans les rainures principales de la bande de roulement","2 mm, à mesurer au centre de la bande de roulement"],"correctIndex":2,"explanation":"La profondeur minimale légale des sculptures est de 1,6 mm ; en dessous, l'adhérence et l'évacuation de l'eau sont fortement compromises, surtout sur route mouillée."},
  {"id":"kq144","type":"knowledge","theme":"equipements","question":"La pression des pneus doit idéalement être vérifiée :","options":["Une fois par an, au moment du contrôle technique","Dès que le témoin de pression s'allume au tableau de bord","Après un long trajet, quand les pneus sont bien chauds","Régulièrement, de préférence à froid"],"correctIndex":3,"explanation":"La pression des pneus doit être contrôlée régulièrement, de préférence à froid (pneus non chauffés par la route), pour garantir sécurité et consommation optimales."},
  {"id":"kq145","type":"knowledge","theme":"equipements","question":"Les feux de croisement doivent être allumés :","options":["De nuit, et de jour quand la visibilité est réduite (brouillard, forte pluie)","Dès que la température descend sous 5 °C, de jour comme de nuit","Hors agglomération la nuit, et en ville lorsqu'il pleut","Sur autoroute et voie rapide, de nuit comme de jour, quel que soit le temps"],"correctIndex":0,"explanation":"Les feux de croisement sont obligatoires de nuit, mais aussi de jour dès que la visibilité est réduite (brouillard, forte pluie, tunnel)."},
  {"id":"kq146","type":"knowledge","theme":"equipements","question":"Les feux de détresse (warnings) doivent être utilisés :","options":["Pour signaler au véhicule suiveur qu'on s'arrête quelques instants en double file","En cas d'arrêt d'urgence, de danger ou pour signaler un ralentissement brutal","Dès que la visibilité est mauvaise, par brouillard ou forte pluie, en roulant","Lorsqu'on souhaite remercier un conducteur qui nous a laissé la priorité"],"correctIndex":1,"explanation":"Les feux de détresse signalent un danger ou un arrêt d'urgence, par exemple en cas de panne ou pour avertir d'un ralentissement brutal de la circulation."},
  {"id":"kq147","type":"knowledge","theme":"equipements","question":"Concernant l'extincteur dans une voiture particulière en France :","options":["Il est obligatoire dans toute voiture mise en circulation depuis 2008","Il est obligatoire dès que le véhicule roule sur autoroute ou voie express","Il n'est pas obligatoire pour une voiture particulière, mais reste recommandé","Il est exigé au contrôle technique et sa péremption est sanctionnée"],"correctIndex":2,"explanation":"Contrairement à une idée reçue, l'extincteur n'est pas obligatoire dans une voiture particulière en France (à la différence de certains véhicules professionnels), mais il reste recommandé."},
  {"id":"kq148","type":"knowledge","theme":"equipements","question":"Des essuie-glaces en mauvais état constituent :","options":["Un défaut toléré tant qu'il ne pleut pas au moment du contrôle","Un défaut qui ne concerne que les véhicules de plus de dix ans","Un simple défaut d'entretien non vérifié lors du contrôle technique","Un risque pour la visibilité et un point de contrôle technique"],"correctIndex":3,"explanation":"Des essuie-glaces usés ou inefficaces réduisent la visibilité par temps de pluie et constituent un point vérifié lors du contrôle technique."},
  {"id":"kq149","type":"knowledge","theme":"equipements","question":"Avant de démarrer, il est important de régler :","options":["Ses rétroviseurs et son siège, pour bien voir et adopter une bonne posture","La luminosité du tableau de bord et de l'écran central, pour ne pas être ébloui","La hauteur des phares et la pression des pneus, depuis le poste de conduite","Le chauffage et la climatisation, pour éviter toute somnolence"],"correctIndex":0,"explanation":"Régler correctement rétroviseurs et siège avant de démarrer est essentiel pour une bonne visibilité, réduire les angles morts et adopter une posture de conduite sûre."},
  {"id":"kq150","type":"knowledge","theme":"equipements","question":"Vérifier le niveau d'huile moteur régulièrement permet de :","options":["Supprimer le besoin de vidanger selon le calendrier du constructeur","Prévenir l'usure prématurée et les pannes moteur","Réduire de moitié la consommation de carburant du véhicule","Dispenser le conducteur de passer le contrôle technique"],"correctIndex":1,"explanation":"Un niveau d'huile insuffisant peut endommager gravement le moteur ; une vérification régulière permet de prévenir l'usure prématurée et les pannes."},
  {"id":"kq151","type":"knowledge","theme":"equipements","question":"Les feux de brouillard arrière ne peuvent être utilisés que :","options":["Dès que la chaussée est mouillée, pour mieux être vu de l'arrière","En ville, la nuit, quand l'éclairage public est insuffisant","Par brouillard ou par chute de neige, quand la visibilité est réduite","Sous une forte pluie, dès que la visibilité devient inférieure à 200 mètres"],"correctIndex":2,"explanation":"L'article R416-7 réserve les feux de brouillard arrière au brouillard ou à la chute de neige. Très éblouissants, ils sont interdits par simple pluie ou temps clair (amende de 135 €, sans retrait de point)."},
  {"id":"kq152","type":"knowledge","theme":"equipements","question":"Concernant l'éthylotest à bord du véhicule :","options":["Il est obligatoire à bord, et son absence est sanctionnée par une amende de 11 euros","Il n'est exigé que des conducteurs titulaires d'un permis probatoire","Il doit être présenté lors du contrôle technique pour valider la visite","Il n'est plus obligatoire depuis 2020, mais il reste conseillé"],"correctIndex":3,"explanation":"L'obligation de détenir un éthylotest, créée en 2012 et jamais sanctionnée depuis 2013, a été supprimée par le décret du 18 mai 2020. Il reste néanmoins un outil de prévention utile."},
  {"id":"kq153","type":"knowledge","theme":"equipements","question":"Avant un long trajet, il est recommandé de vérifier notamment :","options":["L'état des pneus, les niveaux de fluides et l'éclairage","Le nombre de places assises et la couleur de la carrosserie","Le réglage du GPS, la propreté de l'habitacle et le volume de l'autoradio","L'âge du véhicule, son kilométrage et la date du dernier contrôle technique"],"correctIndex":0,"explanation":"Avant un long trajet, il est conseillé de vérifier l'état des pneus, les niveaux (huile, liquide de refroidissement, lave-glace) et le bon fonctionnement de l'éclairage."},
  {"id":"kq154","type":"knowledge","theme":"equipements","question":"L'usage de l'avertisseur sonore (klaxon) est réservé :","options":["Au salut d'un autre usager ou à l'impatience dans un embouteillage","À un danger immédiat, ou pour prévenir en cas de dépassement hors agglomération","Aux véhicules prioritaires en intervention et aux autocars en ville","À tout moment hors agglomération, et pour danger immédiat en ville"],"correctIndex":1,"explanation":"Le klaxon doit être utilisé uniquement en cas de danger immédiat en agglomération, ou pour avertir avant un dépassement hors agglomération ; un usage abusif est sanctionnable."},
  {"id":"kq155","type":"knowledge","theme":"equipements","question":"Le triangle de présignalisation doit être placé, en cas de panne sur route normale, à une distance minimale d'environ :","options":["10 mètres au minimum, placés juste derrière le véhicule en panne","100 mètres, comme sur les routes de montagne en hiver","30 mètres au minimum, davantage si la visibilité est réduite","5 mètres, à hauteur du pare-chocs arrière du véhicule"],"correctIndex":2,"explanation":"Le triangle se place à au moins 30 mètres du véhicule en panne, et plus loin si la visibilité est réduite (nuit, brouillard, courbe). Sur autoroute, on ne le pose pas si cela présente un danger : feux de détresse, gilet, puis abri derrière la glissière."},
  {"id":"kq156","type":"knowledge","theme":"secours","question":"En cas d'accident, la conduite à tenir se résume par le sigle PAS, qui signifie :","options":["Prévenir, Assister, Soigner","Protéger, Appeler, Stationner","Prévenir, Attendre, Secourir","Protéger, Alerter, Secourir"],"correctIndex":3,"explanation":"PAS résume la marche à suivre : Protéger la zone, Alerter les secours, puis Secourir les victimes si l'on en a la capacité."},
  {"id":"kq157","type":"knowledge","theme":"secours","question":"La première étape « Protéger » face à un accident consiste à :","options":["Sécuriser la zone pour éviter un sur-accident (signalisation, gilet, triangle)","Se précipiter vers les victimes pour vérifier immédiatement leur état de conscience","Déplacer les véhicules impliqués sur le bas-côté avant l'arrivée des secours","Prévenir les proches des victimes pour qu'ils puissent rejoindre les lieux"],"correctIndex":0,"explanation":"Protéger consiste à sécuriser les lieux avant toute autre action, pour éviter qu'un nouvel accident ne se produise (baliser, se signaler, couper le contact des véhicules)."},
  {"id":"kq158","type":"knowledge","theme":"secours","question":"En France, les numéros d'urgence à connaître comprennent notamment :","options":["Le 15 (police), le 17 (SAMU), le 18 (pompiers) et le 112 (numéro européen)","Le 15 (SAMU), le 17 (police), le 18 (pompiers) et le 112 (numéro européen)","Le 15 (pompiers), le 17 (police), le 18 (SAMU) et le 112 (réservé aux appels depuis l'étranger)","Le 15 (SAMU), le 17 (police), le 18 (pompiers) et le 19 (numéro européen)"],"correctIndex":1,"explanation":"Plusieurs numéros d'urgence existent en France : 15 pour le SAMU, 17 pour la police, 18 pour les pompiers, et le 112, numéro d'urgence unique valable partout en Europe."},
  {"id":"kq159","type":"knowledge","theme":"secours","question":"La Position Latérale de Sécurité (PLS) s'applique à une victime :","options":["Consciente, qui parle normalement mais se plaint de vertiges","En arrêt cardiaque, sans pouls ni respiration perceptible","Inconsciente mais qui respire normalement","Consciente et atteinte d'une plaie au bras qui saigne abondamment"],"correctIndex":2,"explanation":"La PLS est utilisée pour une victime inconsciente qui respire, afin de dégager ses voies respiratoires et éviter qu'elle ne s'étouffe en cas de vomissement."},
  {"id":"kq160","type":"knowledge","theme":"secours","question":"Face à un motard accidenté portant son casque, il faut en principe :","options":["Le retirer dès l'arrivée sur place pour dégager ses voies respiratoires","Le retirer s'il fait chaud ou si la visière est cassée","Le retirer pour vérifier son identité et prévenir sa famille","Ne pas le retirer, sauf nécessité vitale absolue et avec les précautions adéquates"],"correctIndex":3,"explanation":"Retirer le casque d'un motard accidenté peut aggraver une éventuelle blessure de la nuque ; il ne doit être retiré qu'en cas de nécessité vitale absolue (arrêt respiratoire par exemple) et avec grande précaution."},
  {"id":"kq161","type":"knowledge","theme":"secours","question":"Un blessé conscient et douloureux après un accident doit en général être :","options":["Laissé dans sa position, sauf danger immédiat (incendie, sur-accident)","Déplacé immédiatement sur le bas-côté pour le mettre à l'abri de la circulation","Assis dans un véhicule à l'abri en attendant l'arrivée des secours","Mis debout pour vérifier qu'il tient sur ses jambes et peut marcher"],"correctIndex":0,"explanation":"Sauf danger immédiat (incendie, risque de sur-accident), il ne faut pas déplacer un blessé, au risque d'aggraver d'éventuelles fractures ou lésions internes."},
  {"id":"kq162","type":"knowledge","theme":"secours","question":"Avant de partir en trajet, il est conseillé de vérifier notamment le niveau :","options":["De graisse de transmission à chaîne et de liquide de direction électrique","D'huile moteur, de liquide de refroidissement et de lave-glace","De gaz de climatisation et d'huile de pont arrière, avant tout autre","D'additif antigel pour carburant et de solvant pour injecteurs"],"correctIndex":1,"explanation":"Vérifier les niveaux essentiels (huile, liquide de refroidissement, lave-glace) avant un trajet permet d'anticiper d'éventuelles pannes ou surchauffes."},
  {"id":"kq163","type":"knowledge","theme":"secours","question":"En cas de panne sur autoroute, il est recommandé de :","options":["Rester dans le véhicule, feux de détresse allumés, sur la voie de droite en attendant l'aide","Sortir côté conducteur pour installer le triangle derrière le véhicule, sur la chaussée","Se garer sur la BAU, enfiler son gilet et se mettre à l'abri derrière la glissière","Marcher sur la chaussée avec le gilet pour signaler la panne aux autres véhicules"],"correctIndex":2,"explanation":"En cas de panne sur autoroute, il faut se garer le plus à droite possible sur la BAU, enfiler son gilet avant de sortir, sortir côté passager si possible, et se mettre à l'abri derrière la glissière en attendant les secours."},
  {"id":"kq164","type":"knowledge","theme":"secours","question":"Après une panne sur autoroute, immobilisé sur la bande d'arrêt d'urgence, que faire du triangle de présignalisation ?","options":["Le poser sur la voie de droite, à 30 mètres, en marchant face aux véhicules","Le poser le long de la glissière, à 150 mètres, avant de mettre son gilet","Ne pas le poser si cela oblige à marcher près de la circulation, et se mettre à l'abri derrière la glissière","Le poser obligatoirement, même si l'on doit traverser la chaussée pour y parvenir"],"correctIndex":2,"explanation":"Sur autoroute, l'obligation de poser le triangle ne s'applique pas lorsque cela constituerait un danger manifeste. Il faut s'arrêter sur la BAU, enfiler le gilet, sortir côté droit, se placer derrière la glissière et appeler les secours (borne ou 112), feux de détresse allumés."},
  {"id":"kq165","type":"knowledge","theme":"secours","question":"Le numéro d'urgence européen 112 :","options":["Fonctionne dans tous les pays de l'Union européenne","Ne fonctionne qu'en France et dans les départements d'outre-mer","Est réservé aux appels professionnels émis par les entreprises de transport","Ne permet de joindre que la police et la gendarmerie"],"correctIndex":0,"explanation":"Le 112 est un numéro d'urgence unique, gratuit, joignable dans tous les pays de l'Union européenne, y compris depuis un téléphone sans carte SIM."},
  {"id":"kq166","type":"knowledge","theme":"secours","question":"Lors d'un appel aux secours après un accident, il faut préciser notamment :","options":["Le nom de la compagnie d'assurance et le numéro de contrat de chaque conducteur","Le lieu précis, le nombre de victimes et leur état apparent","La marque et l'immatriculation des véhicules impliqués ainsi que l'heure du départ","Les causes de l'accident et les torts de chaque conducteur impliqué dans la collision"],"correctIndex":1,"explanation":"Un appel de secours efficace précise la localisation exacte, le nombre de victimes, la nature de l'accident et l'état apparent des blessés, pour permettre une intervention adaptée."},
  {"id":"kq167","type":"knowledge","theme":"secours","question":"Face à une hémorragie externe importante, le premier geste à effectuer est :","options":["Lui donner un médicament contre la douleur","Retirer l'objet en cause pour mieux voir l'étendue de la plaie","Comprimer fortement la plaie avec un tissu propre","Allonger la victime et lui lever la tête pour qu'elle ne s'évanouisse pas"],"correctIndex":2,"explanation":"En cas d'hémorragie externe, il faut comprimer directement la plaie avec un tissu propre pour limiter la perte de sang, en attendant les secours."},
  {"id":"kq168","type":"knowledge","theme":"secours","question":"Il ne faut jamais donner à boire ou à manger à un blessé grave car :","options":["Cela ralentit la coagulation du sang et aggrave l'hémorragie","Cela fait chuter la température du corps et provoque une hypothermie","Cela risque de réveiller une victime inconsciente et de la faire paniquer","Cela peut être dangereux, notamment en cas d'anesthésie ou de chirurgie à venir"],"correctIndex":3,"explanation":"Donner à boire ou à manger à un blessé grave peut être risqué, en particulier en cas de besoin d'anesthésie ultérieure ; il vaut mieux s'abstenir et laisser agir les secours."},
  {"id":"kq169","type":"knowledge","theme":"secours","question":"En cas de début d'incendie sous le capot du véhicule, il ne faut surtout pas :","options":["Ouvrir le capot en grand immédiatement, ce qui peut attiser les flammes","Couper le contact pour arrêter l'alimentation électrique du véhicule","S'éloigner du véhicule et écarter les curieux de la zone du feu, sans toucher à rien","Prévenir les secours en composant le 18 ou le 112 depuis un lieu sûr"],"correctIndex":0,"explanation":"Ouvrir le capot en grand apporte brusquement de l'oxygène au feu et peut aggraver l'incendie ; il vaut mieux couper le contact, s'éloigner et alerter les secours."},
  {"id":"kq170","type":"knowledge","theme":"secours","question":"Face à une victime consciente qui se plaint de douleurs après un choc, il faut :","options":["La faire marcher quelques pas pour vérifier qu'elle n'a rien de cassé","La rassurer, éviter de la mobiliser inutilement et attendre les secours","Lui masser énergiquement la zone douloureuse pour calmer la douleur","L'installer au volant d'un véhicule pour qu'elle se rende elle-même à l'hôpital"],"correctIndex":1,"explanation":"Il faut rassurer la victime, éviter tout mouvement inutile pouvant aggraver une éventuelle lésion, et attendre l'arrivée des secours en surveillant son état."},
  {"id":"kq171","type":"knowledge","theme":"secours","question":"Après avoir alerté les secours, en attendant leur arrivée, il convient de :","options":["Quitter les lieux dès que possible, une fois l'appel passé, pour laisser les secours intervenir","Déplacer les véhicules accidentés sans attendre pour dégager la voie","Rester sur place en sécurité pour surveiller la victime et guider les secours","Empêcher toute autre personne de s'approcher, même pour aider ou rassurer"],"correctIndex":2,"explanation":"Il faut rester sur place en sécurité pour surveiller l'évolution de l'état de la victime et guider les secours à leur arrivée sur les lieux."},
  {"id":"kq172","type":"knowledge","theme":"circulation","question":"Hors agglomération, sur une route à double sens sans séparateur central, la vitesse maximale par défaut est :","options":["110 km/h, sauf abaissement local à 90 km/h","90 km/h, sauf abaissement local à 80 km/h","70 km/h, sauf relèvement local à 80 km/h","80 km/h, sauf relèvement local à 90 km/h"],"correctIndex":3,"explanation":"Depuis la réforme de 2018, la vitesse par défaut hors agglomération sur une route bidirectionnelle sans séparateur central est de 80 km/h, certains départements pouvant relever cette limite à 90 km/h par arrêté et signalisation spécifique."},
  {"id":"kq173","type":"knowledge","theme":"circulation","question":"Hors agglomération, sur une route à chaussées séparées par un terre-plein central (2x2 voies) sans autre limitation signalée, la vitesse maximale est de :","options":["110 km/h, soit 20 de moins qu'en autoroute","130 km/h, comme sur autoroute","90 km/h, comme sur route à double sens","100 km/h, selon l'état de la chaussée"],"correctIndex":0,"explanation":"Sur une route à chaussées séparées par un terre-plein central, la vitesse maximale par défaut est de 110 km/h, contre 130 km/h réservés aux autoroutes."},
  {"id":"kq174","type":"knowledge","theme":"circulation","question":"À l'approche d'un passage à niveau dont les barrières s'abaissent ou dont le feu rouge clignote, un conducteur doit :","options":["Accélérer pour passer avant la fermeture complète","S'arrêter, même si le passage semble libre","Contourner les barrières si aucun train n'est visible","Passer à vitesse réduite si aucun train n'est en vue"],"correctIndex":1,"explanation":"Dès que le feu rouge clignote ou que les barrières commencent à s'abaisser, l'arrêt est obligatoire : il ne faut jamais tenter de franchir un passage à niveau en cours de fermeture.","scene":"passage_niveau"},
  {"id":"kq175","type":"knowledge","theme":"circulation","question":"En cas d'aquaplaning (perte d'adhérence sur une flaque d'eau), la réaction correcte est de :","options":["Freiner fortement et en ligne droite pour retrouver l'adhérence","Donner un coup d'accélérateur pour retrouver du grip","Lever le pied de l'accélérateur sans freiner brusquement","Braquer franchement dans un sens puis dans l'autre pour rétablir la trajectoire"],"correctIndex":2,"explanation":"En cas d'aquaplaning, il faut relâcher doucement l'accélérateur, garder le volant droit et éviter tout freinage ou braquage brusque tant que l'adhérence n'est pas retrouvée."},
  {"id":"kq176","type":"knowledge","theme":"circulation","question":"Dépasser un véhicule au sommet d'une côte ou juste avant un sommet de côte est :","options":["Autorisé si aucune ligne continue n'est tracée au sol","Autorisé de jour lorsque le véhicule dépassé roule lentement","Autorisé à condition d'accélérer franchement","Interdit, car la visibilité sur la voie opposée est insuffisante"],"correctIndex":3,"explanation":"Le sommet d'une côte réduit fortement la visibilité sur la voie opposée ; dépasser à cet endroit est interdit car un véhicule peut survenir en face sans que l'on puisse l'anticiper."},
  {"id":"kq177","type":"knowledge","theme":"circulation","question":"En agglomération, lorsqu'un autobus signale son intention de quitter un arrêt, les autres véhicules doivent :","options":["Lui céder le passage, si la limite est de 50 km/h ou moins","Continuer normalement, c'est au bus de s'insérer dans le trafic","Lui céder le passage en toutes circonstances, même à 70 km/h","Lui céder le passage uniquement s'il a mis ses feux de détresse"],"correctIndex":0,"explanation":"En agglomération, où la vitesse est limitée à 50 km/h ou moins, les conducteurs doivent céder le passage à un autobus ou autocar qui signale son intention de quitter un arrêt signalé."},
  {"id":"kq178","type":"knowledge","theme":"circulation","question":"En circulant dans un tunnel, il est recommandé de :","options":["Réduire sa distance de sécurité pour fluidifier le trafic","Garder une distance accrue et s'arrêter seulement en urgence","Éteindre ses feux de croisement pour ne pas éblouir","Doubler dès que la voie est libre pour sortir plus vite"],"correctIndex":1,"explanation":"Dans un tunnel, il faut garder une distance de sécurité importante, allumer ses feux de croisement, et ne s'arrêter qu'en cas d'urgence absolue, en utilisant si besoin les issues de secours."},
  {"id":"kq179","type":"knowledge","theme":"circulation","question":"À l'approche d'un véhicule prioritaire (pompiers, police, SAMU) circulant gyrophares et sirène activés, un conducteur doit :","options":["Accélérer pour dégager la voie le plus vite possible","Maintenir sa trajectoire si l'on est prioritaire","Faciliter son passage en se rangeant dès que possible","S'arrêter immédiatement là où l'on se trouve, même en plein carrefour"],"correctIndex":2,"explanation":"Face à un véhicule d'intérêt général prioritaire, il faut faciliter son passage en se rangeant dès que possible, sans manœuvre brusque ni freinage dangereux pour les autres usagers."},
  {"id":"kq180","type":"knowledge","theme":"circulation","question":"Face à un convoi exceptionnel précédé d'un véhicule pilote (gyrophare orange), un conducteur doit :","options":["Le doubler dès que la route est dégagée devant lui","Lui céder la priorité comme à un véhicule de secours","Rester collé derrière lui pour profiter de son passage","Suivre les consignes du pilote, sans tenter de dépasser"],"correctIndex":3,"explanation":"Un convoi exceptionnel est annoncé et encadré par des véhicules pilotes : il faut suivre leurs indications et ne jamais tenter de le dépasser sans y être invité."},
  {"id":"kq181","type":"knowledge","theme":"circulation","question":"Le dépassement par la droite est :","options":["Interdit, sauf cas particuliers comme une file de véhicules à l'arrêt","Autorisé dans tous les cas, dès que la voie de droite est libre sur 50 mètres","Autorisé seulement sur les routes à trois voies ou plus","Autorisé pour les véhicules plus lents que le trafic"],"correctIndex":0,"explanation":"Le dépassement par la droite est en principe interdit ; il n'est toléré que dans des cas particuliers, comme doubler une file de véhicules à l'arrêt ou circuler sur une chaussée à plusieurs voies dans le même sens en respectant la discipline de voie."},
  {"id":"kq182","type":"knowledge","theme":"circulation","question":"Un panneau annonçant une « chaussée déformée » invite le conducteur à :","options":["Maintenir sa vitesse, la chaussée étant simplement abîmée","Ralentir et rester attentif aux bosses et aux creux de la chaussée","Passer rapidement pour limiter l'effet sur les amortisseurs","Allumer ses feux de détresse et rouler au centre de la chaussée"],"correctIndex":1,"explanation":"Ce panneau de danger signale des irrégularités du revêtement (bosses, nids-de-poule) qui imposent de ralentir pour garder la maîtrise du véhicule."},
  {"id":"kq183","type":"knowledge","theme":"circulation","question":"Dans un giratoire équipé de feux tricolores à son entrée, la règle qui prévaut est :","options":["Celle du panneau Cédez le passage, qui prime sur les feux","La priorité à l'anneau, les feux n'étant qu'indicatifs","Celle du feu tricolore, qui prime sur la règle du giratoire","La priorité à droite, comme à un carrefour sans feux"],"correctIndex":2,"explanation":"Lorsqu'un giratoire est équipé de feux tricolores, ceux-ci priment sur la règle habituelle de priorité à l'anneau : il faut respecter la signalisation lumineuse en priorité."},
  {"id":"kq184","type":"knowledge","theme":"circulation","question":"En cas de début de dérapage de l'arrière du véhicule sur route glissante, il faut :","options":["Freiner à fond pour bloquer l'arrière et immobiliser le véhicule","Accélérer franchement pour que le train avant reprenne le dessus","Braquer fortement à l'opposé du dérapage pour casser l'élan","Lever le pied et corriger dans le sens du dérapage, sans freiner"],"correctIndex":3,"explanation":"Face à un dérapage arrière, il faut relâcher doucement l'accélérateur et corriger la trajectoire en braquant légèrement dans le sens du dérapage, sans freiner ni braquer brutalement, ce qui aggraverait la perte de contrôle."},
  {"id":"kq185","type":"knowledge","theme":"circulation","question":"Sur une portion de route réduite à une seule voie de circulation alternée (chantier), la priorité de passage est déterminée par :","options":["La signalisation en place : feux, panneaux ou agent","Le véhicule le plus lourd, qui est prioritaire","Le véhicule qui monte, quelle que soit la signalisation","Le véhicule arrivé le premier à hauteur du chantier"],"correctIndex":0,"explanation":"Sur un alternat de circulation, la priorité est fixée par la signalisation mise en place (feux tricolores temporaires, panneaux B15/C18, ou agent), qu'il faut impérativement respecter."},
  {"id":"kq186","type":"knowledge","theme":"circulation","question":"Dépasser dans un virage où la visibilité est insuffisante est :","options":["Autorisé si la route est sèche et la voie dégagée","Interdit, même si aucun véhicule n'est visible en face","Autorisé s'il n'y a pas de ligne continue au sol","Toléré si on actionne son clignotant et klaxonne"],"correctIndex":1,"explanation":"Dans un virage sans visibilité suffisante, le dépassement est interdit car un véhicule peut arriver en sens inverse sans que l'on puisse l'anticiper à temps."},
  {"id":"kq187","type":"knowledge","theme":"circulation","question":"En cas de véhicule circulant à contresens repéré sur autoroute (annonce radio ou panneau), il faut :","options":["Faire demi-tour sur la bande d'arrêt d'urgence pour l'éviter","S'arrêter sur la voie de gauche, feux de détresse allumés pour l'alerter","Ralentir, serrer à droite, ne pas faire demi-tour, prévenir le 112","Accélérer et se placer sur la voie de gauche pour s'éloigner vite"],"correctIndex":2,"explanation":"Face à un véhicule fantôme circulant à contresens, il faut ralentir, se déporter à droite, ne jamais faire demi-tour ni marche arrière sur la chaussée, et alerter les secours dès que possible."},
  {"id":"kq188","type":"knowledge","theme":"circulation","question":"En s'insérant sur autoroute depuis une bretelle d'accès, le conducteur doit :","options":["Compter sur la priorité, car la bretelle est une voie d'accès","S'arrêter en bout de bretelle pour attendre un créneau","Rouler à vitesse réduite pour ne pas gêner le trafic","Adapter sa vitesse à celle du flux, sans avoir la priorité"],"correctIndex":3,"explanation":"Le conducteur qui s'insère n'a pas la priorité : il doit utiliser la voie d'insertion pour accélérer et adapter sa vitesse à celle du flux avant de s'insérer en toute sécurité."},
  {"id":"kq189","type":"knowledge","theme":"circulation","question":"Les distances de sécurité entre véhicules doivent être augmentées notamment :","options":["Par pluie, brouillard, de nuit ou sur chaussée glissante","Sur autoroute à 130 km/h, pas sur les autres routes","Quand le véhicule est peu chargé, car il freine moins bien","Par forte chaleur, quand l'asphalte ramollit"],"correctIndex":0,"explanation":"Les distances de sécurité doivent être augmentées dès que les conditions de visibilité ou d'adhérence se dégradent : pluie, brouillard, nuit, verglas ou neige."},
  {"id":"kq190","type":"knowledge","theme":"circulation","question":"À un carrefour dont les feux tricolores sont totalement éteints (panne de courant), un conducteur doit :","options":["S'arrêter et attendre le retour du courant","Appliquer la priorité à droite et redoubler de prudence","Se considérer prioritaire et passer sans ralentir","Laisser passer d'abord les véhicules venant de gauche"],"correctIndex":1,"explanation":"Lorsque les feux sont hors service, ce sont les règles de priorité habituelles qui s'appliquent : panneaux s'il y en a, sinon priorité à droite, avec une vigilance renforcée."},
  {"id":"kq191","type":"knowledge","theme":"circulation","question":"Coller délibérément au véhicule qui précède pour le presser d'accélérer ou de se déporter est :","options":["Un moyen toléré pour signaler son impatience au véhicule qui précède, si le trafic est dense","Une simple incivilité, qui n'est sanctionnée qu'en cas d'accident corporel","Une infraction à la distance de sécurité, sanctionnée même sans accident","Une pratique admise sur autoroute quand le trafic est fluide et la vitesse stable"],"correctIndex":2,"explanation":"Ce comportement, appelé talonnage, supprime toute distance de sécurité (au moins 2 secondes) : c'est une infraction (art. R412-12, 135 EUR et 3 points), sanctionnée indépendamment de tout accident."},
  {"id":"kq193","type":"knowledge","theme":"circulation","question":"Par vent latéral fort, notamment sur un pont ou dans une zone dégagée, un conducteur doit :","options":["Réduire sa vitesse et tenir fermement le volant","Rouler plus vite pour limiter la prise au vent","Se placer près de l'accotement pour être abrité","Desserrer les mains du volant pour absorber les rafales"],"correctIndex":0,"explanation":"Le vent latéral fort peut déporter un véhicule, en particulier les véhicules hauts, motos ou attelages : il faut ralentir et tenir fermement le volant pour anticiper les rafales."},
  {"id":"kq194","type":"knowledge","theme":"circulation","question":"Un panneau de rappel de limitation de vitesse, identique au panneau initial mais placé plus loin sur le même axe, sert à :","options":["Annoncer une nouvelle limitation plus basse que la précédente","Rappeler que la limitation annoncée reste en vigueur","Indiquer la fin de la zone de limitation","Signaler une zone de contrôle de vitesse"],"correctIndex":1,"explanation":"Un panneau de rappel confirme qu'une limitation de vitesse déjà annoncée continue de s'appliquer sur un axe long, sans qu'elle ait changé entre-temps."},
  {"id":"kq195","type":"knowledge","theme":"conducteur","question":"0,5 gramme d'alcool par litre de sang correspond, en air expiré, à environ :","options":["0,10 mg/L","0,50 mg/L","0,25 mg/L","0,40 mg/L"],"correctIndex":2,"explanation":"Le taux légal de 0,5 g/L de sang correspond à environ 0,25 mg d'alcool par litre d'air expiré, seuil mesuré lors d'un contrôle par éthylotest ou éthylomètre."},
  {"id":"kq196","type":"knowledge","theme":"conducteur","question":"L'alcool affecte la conduite principalement en :","options":["Améliorant les réflexes tout en réduisant la vision de nuit","Stimulant la concentration pendant la première heure","Maintenant la conduite intacte en dessous de 0,8 g/L","Ralentissant les réflexes et en donnant une fausse confiance"],"correctIndex":3,"explanation":"Même à faible dose, l'alcool ralentit les réflexes, réduit le champ visuel et augmente la prise de risque en donnant une confiance excessive en ses capacités."},
  {"id":"kq197","type":"knowledge","theme":"conducteur","question":"La conduite après une consommation d'alcool comprise entre 0,5 g/L et 0,8 g/L de sang constitue :","options":["Une contravention de 4e classe, avec amende et retrait de points","Un délit puni d'une amende et d'une suspension du permis","Une contravention de 5e classe, avec amende et retrait de 6 points","Une contravention de 3e classe, avec simple amende forfaitaire"],"correctIndex":0,"explanation":"Entre 0,5 et 0,8 g/L, l'infraction reste une contravention (4e classe) sanctionnée par une amende, un retrait de 6 points et une possible suspension du permis, sans être un délit."},
  {"id":"kq198","type":"knowledge","theme":"conducteur","question":"Le temps nécessaire pour éliminer totalement l'alcool consommé dépend principalement de :","options":["De la température ambiante et du café bu ensuite","De la quantité bue et du métabolisme de chacun","Du type de boisson : la bière s'élimine deux fois plus vite que le vin","Du temps passé à l'air frais après la dernière consommation"],"correctIndex":1,"explanation":"Seul le temps élimine l'alcool du sang (environ 0,10 à 0,15 g/L par heure) : café fort, douche froide ou exercice physique ne réduisent en rien l'alcoolémie réelle."},
  {"id":"kq199","type":"knowledge","theme":"conducteur","question":"Un éthylotest affichant un résultat positif signifie que :","options":["Le taux est proche de zéro, mais un second test est conseillé","Le conducteur peut partir s'il attend 5 minutes avant de repartir","Le taux dépasse probablement le seuil légal : il ne faut pas conduire","L'appareil est défectueux et le test est à refaire après un café"],"correctIndex":2,"explanation":"Un résultat positif à l'éthylotest indique un taux d'alcoolémie probablement supérieur à la limite légale : il ne faut alors pas prendre le volant."},
  {"id":"kq200","type":"knowledge","theme":"conducteur","question":"La consommation de stupéfiants au volant, même en petite quantité, expose à :","options":["Une contravention de 4e classe avec amende et retrait de 3 points","Une suspension administrative du permis, sans poursuite pénale","Un simple retrait de 6 points, sans amende ni suspension","Un délit : amende, retrait de points, suspension du permis et prison possible"],"correctIndex":3,"explanation":"Conduire après usage de stupéfiants est un délit pénal, sanctionné par une amende, un retrait de 6 points, une suspension ou annulation du permis, et jusqu'à deux ans de prison."},
  {"id":"kq201","type":"knowledge","theme":"conducteur","question":"Associer la consommation d'alcool et de stupéfiants au volant :","options":["Constitue une double infraction, aux sanctions aggravées","Ne change rien : seule l'infraction la plus grave est sanctionnée","Est puni comme une simple contravention de 4e classe","Est sanctionné si un accident corporel est survenu, sinon toléré"],"correctIndex":0,"explanation":"Le cumul alcool et stupéfiants constitue une double infraction, avec des sanctions pénales aggravées, les effets des deux substances s'additionnant sur les capacités de conduite."},
  {"id":"kq202","type":"knowledge","theme":"conducteur","question":"Un dépistage de stupéfiants après un contrôle positif se confirme généralement par :","options":["Une déclaration écrite du conducteur sur ses consommations","Une analyse salivaire ou sanguine faite par un professionnel de santé","Un test d'équilibre et de coordination réalisé sur place","Un second test salivaire passé 15 minutes plus tard devant témoin"],"correctIndex":1,"explanation":"Un dépistage positif (test salivaire) est généralement confirmé par une analyse biologique (salivaire ou sanguine) réalisée par un professionnel de santé, avec valeur probante pour les poursuites."},
  {"id":"kq203","type":"knowledge","theme":"conducteur","question":"Refuser de se soumettre à un contrôle d'alcoolémie ou de stupéfiants est :","options":["Une simple contravention de 3e classe avec 90€ d'amende","Toléré une fois, la sanction ne s'appliquant qu'à la seconde fois","Un délit sanctionné aussi sévèrement que l'infraction elle-même","Sans sanction si le conducteur laisse son véhicule sur place"],"correctIndex":2,"explanation":"Le refus de se soumettre aux vérifications d'alcoolémie ou de dépistage de stupéfiants constitue en lui-même un délit, sanctionné aussi sévèrement que l'infraction qu'il visait à établir."},
  {"id":"kq204","type":"knowledge","theme":"conducteur","question":"La fatigue au volant est responsable d'une part importante des accidents mortels sur autoroute, notamment parce qu'elle :","options":["Réduit la vitesse de réaction mais sans lien avec les sorties de route","Touche surtout les trajets de nuit, la fatigue étant nulle de jour","Se manifeste par de l'agressivité, rarement par de la somnolence","Provoque des micro-sommeils de quelques secondes qui suffisent à causer un accident"],"correctIndex":3,"explanation":"La fatigue peut provoquer des micro-sommeils de quelques secondes, largement suffisants pour qu'un véhicule sorte de sa voie ou percute un obstacle à grande vitesse."},
  {"id":"kq205","type":"knowledge","theme":"conducteur","question":"La meilleure prévention contre l'endormissement au volant lors d'un trajet long consiste à :","options":["Dormir avant de partir, faire des pauses régulières et s'arrêter dès les premiers signes","Boire un café avant de partir pour tenir plusieurs heures sans s'arrêter","Rouler fenêtres ouvertes et radio forte pour rester éveillé jusqu'à l'arrivée","Rouler plus vite pour réduire la durée du trajet et la fatigue"],"correctIndex":0,"explanation":"La prévention efficace repose sur un sommeil suffisant avant le départ, des pauses régulières toutes les deux heures, et un arrêt immédiat dès les premiers signes de fatigue."},
  {"id":"kq206","type":"knowledge","theme":"conducteur","question":"Envoyer ou lire un SMS en conduisant, même à l'arrêt à un feu rouge, est :","options":["Toléré à l'arrêt à un feu rouge, tant que le véhicule est immobile","Interdit et sanctionné comme l'usage du téléphone tenu en main","Autorisé si le téléphone est posé sur les genoux","Autorisé pour un message court de moins de dix mots"],"correctIndex":1,"explanation":"L'usage d'un téléphone tenu en main est interdit même à l'arrêt à un feu ou dans un bouchon, y compris moteur coupé, tant que le véhicule n'est pas régulièrement stationné : 135 € d'amende et 3 points."},
  {"id":"kq207","type":"knowledge","theme":"conducteur","question":"Un kit mains-libres ou un système Bluetooth intégré pour téléphoner en conduisant est :","options":["Interdit, car il est assimilé au téléphone tenu en main","Interdit sauf sur autoroute, où la circulation est fluide","Autorisé par la loi, mais déconseillé car il distrait le conducteur","Autorisé sans réserve, la conversation ne distrayant pas"],"correctIndex":2,"explanation":"Le kit mains-libres est légalement autorisé, contrairement au téléphone tenu en main, mais la conversation téléphonique elle-même détourne l'attention du conducteur et reste déconseillée."},
  {"id":"kq208","type":"knowledge","theme":"conducteur","question":"Régler son GPS, sa musique ou sa climatisation devrait idéalement se faire :","options":["En roulant, mais sur une route droite et dégagée","Sur autoroute, où la circulation est régulière et peu risquée","Pendant un ralentissement, quand le trafic est dense et fluide","Avant de partir ou à l'arrêt, pour garder les yeux sur la route"],"correctIndex":3,"explanation":"Régler ses équipements avant le départ ou à l'arrêt évite de détourner le regard et l'attention de la route pendant la conduite, source fréquente d'accidents."},
  {"id":"kq209","type":"knowledge","theme":"conducteur","question":"Le stress au volant peut se traduire notamment par :","options":["Une conduite plus agressive et une perte de concentration","Une conduite plus prudente et une meilleure anticipation","Une meilleure vigilance qui compense la fatigue","Des réflexes améliorés grâce à l'adrénaline"],"correctIndex":0,"explanation":"Le stress altère le jugement et peut pousser à une conduite plus agressive (excès de vitesse, dépassements risqués) ou au contraire à une perte de concentration dangereuse."},
  {"id":"kq210","type":"knowledge","theme":"conducteur","question":"Un conducteur qui se sent en colère après un différend sur la route devrait avant tout :","options":["Rattraper l'autre véhicule dès que possible pour s'expliquer","Se calmer, ne pas répondre à l'agressivité et laisser de la distance","Faire des appels de phares pour montrer son mécontentement","Rouler près du pare-chocs pour marquer sa désapprobation"],"correctIndex":1,"explanation":"Face à la colère, il vaut mieux se calmer et éviter toute escalade : les comportements agressifs entre conducteurs sont une cause reconnue d'accidents graves."},
  {"id":"kq211","type":"knowledge","theme":"conducteur","question":"Une bonne anticipation de la conduite consiste notamment à :","options":["Se concentrer sur le véhicule qui précède et suivre ses réactions","Garder une vitesse élevée pour dégager vite les intersections","Regarder loin devant et repérer en continu les dangers possibles","Réagir au dernier moment par un freinage appuyé"],"correctIndex":2,"explanation":"Anticiper, c'est regarder loin devant, repérer les indices de danger (piétons, intersections, véhicules qui ralentissent) avant qu'ils ne deviennent critiques."},
  {"id":"kq212","type":"knowledge","theme":"conducteur","question":"Concernant les seniors au volant, la loi française impose :","options":["Une visite médicale obligatoire tous les 5 ans à partir de 75 ans","Un test de conduite obligatoire dès 80 ans pour le permis B","Un certificat médical à renouveler tous les 10 ans dès 70 ans","Aucune visite médicale systématique liée à l'âge pour le permis B"],"correctIndex":3,"explanation":"Contrairement à une idée répandue, il n'existe pas en France de visite médicale obligatoire liée à l'âge pour conserver un permis B classique ; chacun reste responsable d'évaluer son aptitude à conduire."},
  {"id":"kq213","type":"knowledge","theme":"conducteur","question":"Un conducteur souffrant d'une pathologie pouvant affecter sa vigilance (épilepsie non stabilisée, apnée du sommeil sévère non traitée...) :","options":["Doit consulter un médecin agréé pour évaluer son aptitude à la conduite","Peut conduire sans restriction tant qu'il se sent en forme","Doit attendre trois ans sans conduire avant tout nouvel examen","Perd automatiquement son permis à vie, sans recours possible"],"correctIndex":0,"explanation":"Certaines pathologies peuvent nécessiter une évaluation par un médecin agréé, qui détermine l'aptitude à la conduite et d'éventuelles restrictions ou un suivi régulier."},
  {"id":"kq214","type":"knowledge","theme":"conducteur","question":"Le champ visuel utile à la conduite se réduit notamment :","options":["Lorsque la vitesse diminue ou que la luminosité augmente","Lorsque la vitesse augmente ou en cas de fatigue et de distraction","De nuit ou par temps de pluie, mais pas en plein jour","Lorsque le conducteur est reposé et attentif à son environnement"],"correctIndex":1,"explanation":"Le champ visuel utile se rétrécit avec l'augmentation de la vitesse, mais aussi sous l'effet de la fatigue, du stress ou de la distraction, réduisant la perception des dangers périphériques."},
  {"id":"kq215","type":"knowledge","theme":"conducteur","question":"Porter des lunettes de vue ou de soleil adaptées est important car :","options":["Elles n'ont d'effet que sur la lecture des panneaux de signalisation","Elles réduisent le champ visuel et ralentissent les réflexes","Une vision bien corrigée aide à percevoir les dangers à temps","Elles sont indispensables à partir de 60 ans, pas avant"],"correctIndex":2,"explanation":"Une vision correctement corrigée, ainsi qu'une protection adaptée contre l'éblouissement, sont essentielles pour percevoir à temps les dangers sur la route."},
  {"id":"kq216","type":"knowledge","theme":"conducteur","question":"L'accompagnateur en conduite accompagnée (AAC) doit notamment :","options":["Avoir le permis B depuis 2 ans et ne pas avoir plus de 65 ans","Avoir le permis B depuis 3 ans et être un parent de l'élève","Être titulaire du permis depuis moins d'un an, avec l'accord de l'assureur","Avoir le permis B depuis 5 ans au moins, sans suspension ni annulation"],"correctIndex":3,"explanation":"L'accompagnateur doit être titulaire du permis B depuis au moins 5 ans sans interruption due à une annulation ou une suspension, afin de garantir une expérience suffisante pour encadrer l'apprenti conducteur."},
  {"id":"kq217","type":"knowledge","theme":"conducteur","question":"Pendant la conduite accompagnée, l'apprenti conducteur doit respecter :","options":["Des vitesses un peu inférieures aux limites générales","Les mêmes vitesses que tout conducteur, avec un accompagnateur à côté","Une vitesse limitée à 80 km/h sur tous les types de route","Des vitesses réduites de moitié par rapport aux limites générales"],"correctIndex":0,"explanation":"Pendant l'AAC, des vitesses maximales légèrement inférieures aux limites générales s'appliquent (par exemple sur autoroute), afin de sécuriser l'apprentissage."},
  {"id":"kq218","type":"knowledge","theme":"conducteur","question":"Un conducteur en permis probatoire doit apposer sur son véhicule :","options":["Un disque « A » bleu sur fond blanc à l'avant du véhicule","Un disque « A » rouge sur fond blanc, visible à l'arrière","Un disque « L » rouge sur fond blanc, visible à l'arrière","Un disque « P » vert sur fond blanc, collé sur la lunette arrière"],"correctIndex":1,"explanation":"Le conducteur novice doit apposer à l'arrière de son véhicule un disque « A » (lettre A rouge sur fond blanc), visible par les autres usagers, pendant toute la durée du permis probatoire."},
  {"id":"kq219","type":"knowledge","theme":"conducteur","question":"En période probatoire, la vitesse maximale autorisée sur autoroute est réduite à :","options":["120 km/h, soit 10 km/h de moins que la limite générale","100 km/h, soit 30 km/h de moins que la limite générale","110 km/h, soit 20 km/h de moins que la limite générale","130 km/h, comme tout conducteur titulaire du permis"],"correctIndex":2,"explanation":"Un conducteur en période probatoire est limité à 110 km/h sur autoroute (au lieu de 130 km/h), une réduction similaire s'appliquant aussi sur les autres types de routes."},
  {"id":"kq220","type":"knowledge","theme":"conducteur","question":"La visibilité réduite due à un pare-brise sale ou à des vitres embuées doit être traitée :","options":["En roulant vitre ouverte, sans qu'il soit utile de s'arrêter","Au prochain entretien du véhicule, sans urgence particulière","En allumant les feux de détresse et en roulant à vitesse normale","Avant de partir, ou en s'arrêtant dès que possible, pour voir clairement"],"correctIndex":3,"explanation":"Un pare-brise sale ou embué réduit dangereusement la visibilité : il faut le nettoyer avant de partir ou s'arrêter dès que possible pour rétablir une vision claire."},
  {"id":"kq221","type":"knowledge","theme":"conducteur","question":"Manger un repas copieux juste avant de prendre la route peut :","options":["Favoriser la somnolence pendant la digestion","Stimuler l'attention grâce au sucre apporté par le repas","Améliorer la vigilance grâce à l'apport d'énergie","Rester sans conséquence tant que le repas est pris assis"],"correctIndex":0,"explanation":"Une digestion lourde favorise la somnolence ; il est conseillé de privilégier un repas léger avant un trajet, surtout long ou de nuit."},
  {"id":"kq222","type":"knowledge","theme":"conducteur","question":"Face à un fort éblouissement par les phares d'un véhicule venant en face la nuit, il faut :","options":["Regarder fixement les phares pour apprécier la distance","Regarder vers le bord droit de la chaussée et ralentir si besoin","Fermer brièvement les yeux en gardant le volant droit","Passer en feux de route pour se faire voir de l'autre conducteur"],"correctIndex":1,"explanation":"Face à l'éblouissement, il faut éviter de fixer les phares, regarder plutôt le bord droit de la chaussée comme repère, et ralentir si la visibilité devient insuffisante."},
  {"id":"kq223","type":"knowledge","theme":"conducteur","question":"Prendre le volant après une nuit très courte (moins de 4 à 5 heures de sommeil) présente un risque :","options":["Négligeable si le trajet dure moins d'une heure","Réel sur autoroute, pas sur route de campagne","Comparable à celui de la conduite sous l'emprise de l'alcool","Nul chez les conducteurs jeunes, dont la récupération est rapide"],"correctIndex":2,"explanation":"Un manque de sommeil important dégrade les réflexes et la vigilance de façon comparable à l'alcool, augmentant fortement le risque d'accident, y compris sur de courts trajets."},
  {"id":"kq224","type":"knowledge","theme":"route","question":"Un panneau rond à fond bleu représentant une flèche blanche indique :","options":["Une interdiction de tourner à gauche ou à droite","Un itinéraire touristique conseillé mais facultatif","Une zone de stationnement réservée à certains véhicules","Une direction obligatoire à suivre"],"correctIndex":3,"explanation":"Un panneau rond à fond bleu avec une flèche blanche est un panneau d'obligation (B21) : il impose la direction indiquée. Les panneaux carrés ou rectangulaires bleus relèvent de l'indication (parking, sens unique...)."},
  {"id":"kq225","type":"knowledge","theme":"route","question":"Le panneau triangulaire représentant une chaussée qui se rétrécit annonce :","options":["Un rétrécissement de la chaussée, nécessitant prudence","Une voie de décélération à l'approche d'une sortie","Une chaussée glissante sur la section à venir","Un passage à niveau sans barrières, à 150 m"],"correctIndex":0,"explanation":"Ce panneau de danger prévient d'un rétrécissement prochain de la chaussée, invitant à ralentir et à anticiper un éventuel resserrement du trafic."},
  {"id":"kq226","type":"knowledge","theme":"route","question":"Un panneau rond à fond blanc, barré de plusieurs traits obliques gris, indique :","options":["Le début d'une zone où la réglementation est renforcée","La fin d'une prescription annoncée précédemment","Une interdiction de circuler jusqu'à la prochaine intersection","Une simple recommandation de prudence pour les usagers"],"correctIndex":1,"explanation":"Un panneau de fin de prescription signale que la règle précédemment imposée (vitesse limitée, interdiction de dépasser...) cesse de s'appliquer à partir de cet endroit."},
  {"id":"kq227","type":"knowledge","theme":"route","question":"Le panneau d'agglomération (nom de ville sur fond blanc, lettres noires) marque notamment :","options":["La fin des limitations de vitesse","Le début d'une zone limitée à 30 km/h","Le début de la limitation à 50 km/h par défaut","L'entrée dans une zone où le dépassement est interdit"],"correctIndex":2,"explanation":"Le panneau d'entrée d'agglomération fixe le début de la zone où la vitesse est limitée à 50 km/h par défaut, sauf signalisation contraire à l'intérieur de cette zone."},
  {"id":"kq228","type":"knowledge","theme":"route","question":"Le même panneau, barré d'un trait oblique rouge, marque :","options":["L'entrée dans une zone où la vitesse est limitée à 30 km/h","La fin d'une zone de rencontre limitée à 20 km/h","Le début d'une section où le dépassement est interdit","La sortie de l'agglomération et la fin du 50 km/h par défaut"],"correctIndex":3,"explanation":"Le panneau de nom de ville barré signale la sortie de l'agglomération : la limitation par défaut à 50 km/h cesse, sauf autre signalisation."},
  {"id":"kq230","type":"knowledge","theme":"route","question":"Un panneau représentant un « cédez le passage » associé à un panonceau « à 150 m » annonce :","options":["Que la priorité s'applique pendant 150 mètres à partir d'ici","Que le cédez le passage se trouve à 150 mètres plus loin","Que la vitesse est limitée sur les 150 prochains mètres","Qu'une zone de stationnement commence 150 mètres plus loin"],"correctIndex":1,"explanation":"Le panonceau de distance annonce à l'avance un panneau de prescription (ici cédez le passage), permettant au conducteur d'anticiper la situation."},
  {"id":"kq231","type":"knowledge","theme":"route","question":"Les panneaux de type « danger » sont le plus souvent implantés :","options":["Avant le danger, à environ 500 m hors agglomération","Juste au niveau du danger, sans distance d'anticipation","Avant le danger, à environ 150 m hors agglomération","Après le danger, pour confirmer qu'il est terminé"],"correctIndex":2,"explanation":"Les panneaux de danger sont implantés en amont du danger, généralement à environ 150 mètres hors agglomération, pour laisser au conducteur le temps d'adapter sa conduite."},
  {"id":"kq232","type":"knowledge","theme":"route","question":"Les panneaux signalant un site touristique ou culturel (signalisation d'animation) sont de couleur :","options":["Blanche, avec inscriptions noires","Jaune, avec inscriptions noires","Rouge, avec inscriptions blanches","Marron, avec inscriptions blanches"],"correctIndex":3,"explanation":"Les sites touristiques et culturels sont signalés par des panneaux marron à inscriptions blanches. Les autres couleurs correspondent à d'autres usages : bleu (autoroute), vert (grands itinéraires), blanc (voies locales)."},
  {"id":"kq233","type":"knowledge","theme":"route","question":"Une ligne continue de couleur jaune peinte au bord de la chaussée signifie généralement :","options":["Une interdiction de stationner ou de s'arrêter","Un stationnement autorisé uniquement aux riverains","Une voie réservée aux cyclistes et aux cyclomoteurs","Une limite de vitesse de 30 km/h le long du trottoir"],"correctIndex":0,"explanation":"Une ligne jaune continue le long de la chaussée interdit l'arrêt et le stationnement. Une ligne jaune discontinue interdit seulement le stationnement."},
  {"id":"kq234","type":"knowledge","theme":"route","question":"Les flèches de sélection peintes au sol dans les voies d'un carrefour indiquent :","options":["La priorité accordée aux véhicules circulant sur cette voie","La direction imposée à chaque voie au carrefour suivant","La distance restante avant le prochain carrefour à feux","Les voies où le dépassement reste autorisé avant le carrefour"],"correctIndex":1,"explanation":"Ces flèches de pré-signalisation imposent, dès leur franchissement, la direction que devra suivre le véhicule circulant sur cette voie au carrefour."},
  {"id":"kq235","type":"knowledge","theme":"route","question":"Un panneau représentant une silhouette de vache ou d'animal traversant annonce :","options":["La présence d'une ferme avec vente directe à proximité","Un secteur de pâturage clôturé sans risque pour la route","Un risque de traversée d'animaux sur la chaussée","Une zone où la circulation des chevaux est interdite"],"correctIndex":2,"explanation":"Ce panneau de danger signale un risque de traversée d'animaux (domestiques ou sauvages) sur la route, invitant à ralentir et à rester attentif."},
  {"id":"kq236","type":"knowledge","theme":"route","question":"Le marquage au sol en forme de « stop » peint directement sur la chaussée, en plus du panneau vertical, sert à :","options":["Autoriser un simple ralentissement si la voie est dégagée","Matérialiser la limite de la zone de stationnement","Indiquer la distance restante avant la ligne d'arrêt","Renforcer l'obligation d'arrêt si le panneau est peu visible"],"correctIndex":3,"explanation":"Le marquage STOP au sol complète le panneau vertical, notamment lorsque celui-ci pourrait être masqué (neige, véhicule garé) et renforce la visibilité de l'obligation d'arrêt."},
  {"id":"kq237","type":"knowledge","theme":"route","question":"Une voie bus identifiée par un losange blanc peint au sol signifie que cette voie est :","options":["Réservée aux transports en commun, taxis et parfois vélos","Réservée aux véhicules de livraison et aux riverains en journée","Réservée aux motos et aux véhicules de plus de 3,5 t en transit","Une voie de dépassement réservée aux véhicules circulant vite"],"correctIndex":0,"explanation":"Le losange blanc marque une voie réservée à certains usagers (bus, taxis, parfois covoiturage ou vélos), dont l'accès est limité aux véhicules autorisés par la signalisation locale."},
  {"id":"kq238","type":"knowledge","theme":"route","question":"Le panneau représentant deux flèches, l'une noire vers le haut et l'une rouge vers le bas, sur un fond blanc annonce :","options":["Une chaussée à sens unique","Une route à double sens de circulation","Une route à trois voies","Un carrefour giratoire"],"correctIndex":1,"explanation":"Ce panneau de danger annonce que l'on va aborder une section à double sens de circulation, après avoir potentiellement circulé sur une portion à sens unique ou séparée."},
  {"id":"kq239","type":"knowledge","theme":"route","question":"Un panneau représentant un feu tricolore dans un triangle annonce :","options":["Un carrefour où les feux sont en panne ou clignotants à certaines heures","Un passage à niveau équipé de feux et de barrières automatiques","La présence d'un feu tricolore, parfois peu attendu hors agglomération","Une section où la priorité à droite est supprimée par des feux"],"correctIndex":2,"explanation":"Ce panneau de danger annonce la présence prochaine d'un feu tricolore, notamment dans des zones où ce type de signalisation est moins attendu par les usagers."},
  {"id":"kq240","type":"knowledge","theme":"route","question":"Une bande blanche discontinue très rapprochée (traits courts, espaces courts) au centre de la chaussée signifie généralement :","options":["Une voie réservée aux véhicules lents à l'approche d'un virage","Une zone où le stationnement devient interdit à l'approche","Un changement de revêtement de la chaussée à l'approche","Une approche d'une zone où le dépassement va devenir interdit"],"correctIndex":3,"explanation":"Cette ligne discontinue à traits rapprochés est une ligne d'avertissement (ou d'annonce) : elle prévient qu'une ligne continue va suivre et que le dépassement va devenir interdit."},
  {"id":"kq241","type":"knowledge","theme":"route","question":"Le panneau représentant un « i » entouré ou encadré, sur fond bleu, indique généralement :","options":["Un point d'information (office de tourisme, aire de service...)","Un poste de secours équipé d'un téléphone d'urgence gratuit","Une aire de repos réservée aux poids lourds et aux cars de tourisme","Un point de péage avec information sur les tarifs du jour"],"correctIndex":0,"explanation":"Le pictogramme « i » signale un point d'information, souvent situé sur les aires d'autoroute ou à l'entrée de zones touristiques."},
  {"id":"kq242","type":"knowledge","theme":"route","question":"Sur une route à sens unique, un panneau représentant une flèche blanche verticale sur fond bleu, placé au début de la voie, signifie :","options":["Voie à double sens réservée aux riverains","Sens unique dans la direction indiquée","Impasse sans issue à partir de cet endroit","Voie réservée aux véhicules prioritaires dans ce sens"],"correctIndex":1,"explanation":"Ce panneau carré bleu (C12) est un panneau d'indication : la route est à sens unique dans le sens de la flèche. Il est interdit de circuler dans le sens inverse."},
  {"id":"kq243","type":"knowledge","theme":"route","question":"Un panonceau représentant une distance (par exemple « 500 m ») sous un panneau de danger signifie :","options":["Que la vitesse est limitée sur la distance indiquée","Que la prochaine aire de repos est à cette distance","Que le danger se situe à la distance indiquée devant toi","Que la zone dangereuse sera signalée à nouveau à cette distance"],"correctIndex":2,"explanation":"Ce panonceau précise la distance à laquelle se situe le danger annoncé par le panneau principal, permettant d'évaluer le moment où redoubler de prudence."},
  {"id":"kq244","type":"knowledge","theme":"route","question":"La signalisation d'une zone de rencontre impose notamment :","options":["Une vitesse maximale de 30 km/h et une priorité aux piétons","Une vitesse maximale de 20 km/h et un sens unique obligatoire","Une vitesse maximale de 50 km/h et des trottoirs réservés aux piétons","Une vitesse maximale de 20 km/h et une priorité aux piétons"],"correctIndex":3,"explanation":"Dans une zone de rencontre, la vitesse est limitée à 20 km/h. Les piétons peuvent circuler sur la chaussée et sont prioritaires sur les véhicules, sans toutefois les gêner inutilement."},
  {"id":"kq245","type":"knowledge","theme":"route","question":"Une aire piétonne (zone strictement piétonne) est en principe :","options":["Interdite aux véhicules, sauf ceux autorisés par la signalisation","Réservée aux piétons et aux cyclistes, avec priorité aux véhicules de livraison","Ouverte à tous les véhicules aux heures de faible affluence, à 30 km/h","Réservée aux piétons, mais les voitures peuvent y circuler à 20 km/h"],"correctIndex":0,"explanation":"Dans une aire piétonne, seuls les véhicules autorisés (livraisons à certaines heures, riverains, services) peuvent circuler, à l'allure du pas, en cédant toujours le passage aux piétons."},
  {"id":"kq246","type":"knowledge","theme":"route","question":"Une voie de détresse (voie d'échappatoire pour véhicules en perte de freinage) est généralement recouverte de :","options":["Bitume rainuré pour améliorer l'adhérence en descente","Gravier ou sable pour ralentir rapidement le véhicule","Herbe rase et terre meuble, à l'écart de la chaussée","Béton drainant avec une pente descendante"],"correctIndex":1,"explanation":"Les voies de détresse en montée, remplies de gravier ou de sable, permettent de ralentir puis d'immobiliser un véhicule ayant perdu ses freins dans une longue descente."},
  {"id":"kq247","type":"knowledge","theme":"route","question":"Un panneau à fond blanc bordé de rouge représentant un cycliste barré interdit :","options":["Le stationnement des vélos sur la chaussée","Le dépassement des cyclistes par les voitures","La circulation des cyclistes à cet endroit","La circulation des cyclomoteurs sur cette voie"],"correctIndex":2,"explanation":"Ce panneau d'interdiction signale que la circulation des cycles est interdite sur la voie ou la portion de route concernée."},
  {"id":"kq248","type":"knowledge","theme":"route","question":"Le panneau représentant un piéton dans un triangle rouge annonce :","options":["Une interdiction de circuler pour les piétons sur cette voie","La fin d'une aire piétonne ou d'une zone de rencontre limitée à 20 km/h","Un cheminement piéton obligatoire le long de la route","Un passage piéton proche ou une zone fréquentée par des piétons"],"correctIndex":3,"explanation":"Ce panneau de danger prévient de la présence probable de piétons traversant ou circulant à proximité, notamment près des écoles ou zones commerçantes."},
  {"id":"kq249","type":"knowledge","theme":"route","question":"Un panneau rond à fond bleu représentant une bicyclette blanche impose :","options":["L'obligation pour les cyclistes d'emprunter cet aménagement","Le droit de circuler à vélo sur le trottoir à vitesse réduite","L'interdiction pour les cyclistes de quitter la chaussée","Une zone de stationnement réservée aux vélos et aux trottinettes"],"correctIndex":0,"explanation":"Ce panneau d'obligation impose aux cyclistes d'utiliser la piste ou bande cyclable signalée, plutôt que la chaussée principale, lorsque cet aménagement existe."},
  {"id":"kq252","type":"knowledge","theme":"route","question":"Une ligne de triangles blancs, pointe vers le conducteur, peinte en travers de la voie à l'approche d'un carrefour signifie :","options":["Voie sans issue à partir de cette intersection","Stationnement autorisé sur le bord de la voie","Limitation de vitesse à 30 km/h sur la voie","Cédez le passage à l'approche du carrefour"],"correctIndex":3,"explanation":"La ligne de triangles blancs reproduit au sol l'obligation du panneau « Cédez le passage » : on doit céder le passage aux véhicules de la voie prioritaire."},
  {"id":"kq253","type":"knowledge","theme":"route","question":"Un panneau représentant un radar photographique stylisé annonce :","options":["Un contrôle de vitesse fixe ou une zone de contrôle radar","Une zone de contrôle de l'alcoolémie à proximité","Un poste de péage équipé d'une caméra de surveillance","Une zone de surveillance vidéo des stationnements gênants"],"correctIndex":0,"explanation":"Ce panneau prévient les usagers de la présence d'un dispositif de contrôle de vitesse (radar fixe ou zone contrôlée), afin d'inciter au respect des limitations."},
  {"id":"kq254","type":"knowledge","theme":"usagers","question":"Un piéton qui souhaite traverser en dehors d'un passage protégé, à plus de 50 mètres d'un passage piéton :","options":["Doit rejoindre le passage piéton, même s'il se trouve à 300 m","Doit s'assurer de pouvoir traverser sans danger, car il n'est pas prioritaire","Peut traverser en priorité si les véhicules sont à plus de 30 m","Est prioritaire dès qu'il est engagé sur la chaussée"],"correctIndex":1,"explanation":"Hors passage protégé, un piéton n'est pas prioritaire : il doit s'assurer que la traversée est possible sans danger, même si les conducteurs doivent rester attentifs à sa présence."},
  {"id":"kq255","type":"knowledge","theme":"usagers","question":"Un enfant qui joue à proximité de la chaussée, même sans intention apparente de traverser, doit inciter le conducteur à :","options":["Garder sa vitesse tant que l'enfant ne regarde pas la route","Klaxonner pour l'avertir, puis passer sans changer d'allure","Ralentir et redoubler de vigilance, un enfant étant imprévisible","S'écarter par la gauche et accélérer pour passer au plus vite"],"correctIndex":2,"explanation":"Le comportement des enfants est imprévisible : la prudence impose de ralentir et de redoubler de vigilance à leur approche, même sans signe de traversée."},
  {"id":"kq256","type":"knowledge","theme":"usagers","question":"Les cyclistes peuvent circuler à deux de front sur la chaussée :","options":["Non, la file indienne s'impose dès qu'un véhicule les suit","Oui, mais hors agglomération et sur route à double sens","Oui, à condition de ne pas ralentir les véhicules qui les suivent","Oui, en se mettant en file simple pour un dépassement ou la nuit"],"correctIndex":3,"explanation":"Les cyclistes peuvent circuler à deux de front, mais doivent se mettre en file simple dès qu'un véhicule veut les dépasser ou dès la tombée de la nuit, et systématiquement sur chaussée étroite ou à visibilité réduite."},
  {"id":"kq257","type":"knowledge","theme":"usagers","question":"Un cycliste doit-il respecter les feux tricolores comme un automobiliste ?","options":["Oui, sauf là où un panonceau les y autorise","Non, les feux ne s'adressent qu'aux véhicules à moteur","Oui, mais ils peuvent franchir le rouge si la voie est libre","Oui, mais ils peuvent passer à l'orange fixe sans s'arrêter"],"correctIndex":0,"explanation":"Un cycliste est soumis aux mêmes règles de feux tricolores qu'un automobiliste, sauf dérogation signalée par un panonceau spécifique autorisant certains mouvements au rouge."},
  {"id":"kq258","type":"knowledge","theme":"usagers","question":"Le port du casque à vélo est obligatoire en France pour :","options":["Les enfants de moins de 8 ans, comme conducteurs","Les enfants de moins de 12 ans, conducteurs ou passagers","Les cyclistes qui circulent hors agglomération, sans exception","Les cyclistes sur les routes limitées à plus de 50 km/h"],"correctIndex":1,"explanation":"En France, le port du casque à vélo est obligatoire pour les enfants de moins de 12 ans, qu'ils soient conducteurs de leur propre vélo ou transportés comme passagers ; il reste fortement recommandé pour les adultes."},
  {"id":"kq259","type":"knowledge","theme":"usagers","question":"Les conducteurs de trottinettes électriques doivent avoir un âge minimum de :","options":["14 ans, âge fixé par le code de la route","16 ans, âge requis pour tout engin motorisé","12 ans, âge exigé pour le casque à vélo","8 ans, si un adulte l'accompagne à pied"],"correctIndex":0,"explanation":"Depuis le 1er septembre 2023, la conduite d'une trottinette électrique (EDPM) est interdite aux enfants de moins de 14 ans (l'âge minimum était de 12 ans auparavant)."},
  {"id":"kq260","type":"knowledge","theme":"usagers","question":"Rouler à deux personnes sur une trottinette électrique conçue pour un seul utilisateur est :","options":["Autorisé si le passager est un enfant de moins de 8 ans","Autorisé à condition de rouler à moins de 10 km/h","Autorisé sur piste cyclable, mais pas sur la chaussée ni en ville","Interdit, ces engins sont conçus pour un seul utilisateur"],"correctIndex":3,"explanation":"Une trottinette électrique standard est homologuée pour un seul utilisateur ; transporter un passager supplémentaire est interdit et dangereux."},
  {"id":"kq261","type":"knowledge","theme":"usagers","question":"La vitesse maximale autorisée pour une trottinette électrique en agglomération est généralement de :","options":["25 km/h, parfois moins selon la commune","30 km/h, comme dans les zones 30 de la commune","20 km/h, limite des zones de rencontre","45 km/h, comme pour un cyclomoteur"],"correctIndex":0,"explanation":"Les engins de déplacement personnel motorisés (trottinettes électriques) sont limités à 25 km/h, la vitesse pouvant être réduite localement (zones piétonnes, certaines rues)."},
  {"id":"kq262","type":"knowledge","theme":"usagers","question":"Un utilisateur de trottinette électrique doit obligatoirement, la nuit ou par visibilité insuffisante, disposer de :","options":["Un feu blanc à l'avant et un gilet rétro-réfléchissant, sans feu arrière","Feux avant et arrière et dispositif rétro-réfléchissant","Un casque et un gilet fluorescent, l'éclairage restant facultatif","Un feu avant, le feu rouge arrière étant facultatif"],"correctIndex":1,"explanation":"Comme un vélo, la trottinette électrique doit être équipée de feux avant et arrière ainsi que de catadioptres, obligatoires de nuit ou en cas de faible visibilité."},
  {"id":"kq263","type":"knowledge","theme":"usagers","question":"Un conducteur de véhicule agricole (tracteur) circulant lentement sur une route doit :","options":["Rouler au centre de sa voie pour empêcher les dépassements","Accélérer dans les lignes droites pour ne pas gêner","Faciliter le dépassement quand c'est sûr, en se rabattant","Laisser les autres véhicules le suivre sans le doubler"],"correctIndex":2,"explanation":"Un conducteur de véhicule lent doit faciliter les dépassements par les véhicules plus rapides dès que les conditions de sécurité et de visibilité le permettent, par exemple en se rabattant sur le bas-côté."},
  {"id":"kq264","type":"knowledge","theme":"usagers","question":"Les personnes en fauteuil roulant circulant sur la chaussée en l'absence de trottoir doivent être considérées comme :","options":["Des cyclistes, soumis aux règles de circulation du vélo","Des conducteurs de véhicules lents","Des usagers sans statut juridique précis","Des piétons, avec les mêmes droits de priorité"],"correctIndex":3,"explanation":"Une personne en fauteuil roulant est considérée comme un piéton, y compris lorsqu'elle est contrainte d'emprunter la chaussée faute de trottoir accessible."},
  {"id":"kq265","type":"knowledge","theme":"usagers","question":"Croiser un cycliste circulant en sens inverse sur une route étroite nécessite de :","options":["Ralentir et lui laisser assez de place pour passer","Maintenir sa vitesse, le cycliste devant se ranger sur le bas-côté","Rouler sur l'axe de la chaussée pour le croiser en sécurité","Faire des appels de phares pour qu'il s'arrête au croisement"],"correctIndex":0,"explanation":"Sur une route étroite, il faut ralentir et laisser un espace suffisant en croisant un cycliste, quitte à serrer légèrement à droite si la sécurité le permet."},
  {"id":"kq266","type":"knowledge","theme":"usagers","question":"L'ouverture d'une portière de voiture garée doit se faire :","options":["En ouvrant d'un geste vif pour dégager le passage plus vite","En regardant derrière soi pour vérifier qu'aucun cycliste n'arrive","En regardant seulement si une voiture arrive sur la voie","En ouvrant à moitié, puis en regardant avant de descendre"],"correctIndex":1,"explanation":"Avant d'ouvrir une portière, il faut vérifier la circulation, notamment celle des cyclistes qui longent le trottoir : ouvrir sans regarder est une cause fréquente d'accidents avec les deux-roues."},
  {"id":"kq267","type":"knowledge","theme":"usagers","question":"Les conducteurs de quads homologués pour la route doivent :","options":["Avoir 16 ans révolus et un casque, sans autre condition","Posséder le seul permis B, quelle que soit la puissance du quad","Posséder un permis adapté à la catégorie du quad (AM, A1, B)","Posséder une attestation de formation de sept heures, sans permis"],"correctIndex":2,"explanation":"Selon leur puissance et leur catégorie, les quads homologués route nécessitent un permis adapté (AM, A1 ou B), le port du casque étant obligatoire pour les quads non carrossés."},
  {"id":"kq268","type":"knowledge","theme":"usagers","question":"Face à un car scolaire à l'arrêt, feux de détresse allumés, un conducteur doit :","options":["Passer lentement sans s'arrêter, en s'écartant sur la gauche","S'arrêter derrière lui jusqu'à son redémarrage","Maintenir son allure car les enfants sont attendus sur le trottoir","Ralentir fortement, des enfants pouvant traverser"],"correctIndex":3,"explanation":"Un car scolaire à l'arrêt n'impose pas l'arrêt des autres véhicules en France, mais des enfants peuvent traverser de façon imprévisible, parfois masqués par le car : il faut ralentir fortement et redoubler de prudence."},
  {"id":"kq269","type":"knowledge","theme":"usagers","question":"Les conducteurs de véhicules de transport public de personnes (bus, cars) bénéficient de facilités de circulation, notamment :","options":["De voies réservées et d'une priorité à la sortie des arrêts en agglomération","D'une dispense de respecter les feux tricolores aux carrefours","D'un droit de stationner sur les trottoirs pour les arrêts de ligne","D'un droit de dépasser à droite sur les routes à chaussées séparées"],"correctIndex":0,"explanation":"Les bus et cars bénéficient souvent de voies réservées et d'une priorité pour quitter leur arrêt en agglomération, afin de fluidifier les transports en commun."},
  {"id":"kq270","type":"knowledge","theme":"usagers","question":"Face à un attelage de chevaux ou un cavalier sur la route, un automobiliste doit :","options":["Klaxonner de loin pour prévenir le cavalier","Ralentir, garder ses distances et éviter tout bruit soudain","Le doubler à vive allure pour limiter la gêne","Le suivre de très près pour ne pas perdre de temps"],"correctIndex":1,"explanation":"Un cheval peut être effrayé par un bruit soudain ou un dépassement trop rapide : il faut ralentir, garder ses distances et éviter klaxon ou accélération brusque."},
  {"id":"kq271","type":"knowledge","theme":"usagers","question":"Les livreurs à vélo ou à trottinette doivent respecter :","options":["Des règles assouplies pour tenir compte des délais","Celles de leur plateforme, qui priment sur le code de la route","Les mêmes règles que tout autre cycliste ou utilisateur d'EDPM","Le code de la route, sauf aux feux rouges pendant une course"],"correctIndex":2,"explanation":"Un livreur à vélo ou à trottinette reste soumis aux mêmes règles du code de la route que tout autre usager, malgré la pression liée aux délais de livraison."},
  {"id":"kq272","type":"knowledge","theme":"usagers","question":"Un motocycliste doit porter, en plus du casque, des équipements de protection :","options":["Un blouson et un pantalon renforcés, les gants restant facultatifs","Des bottes montantes et une protection dorsale, quelle que soit la cylindrée","Une combinaison complète homologuée dès que la cylindrée dépasse 125 cm3","Des gants homologués, le reste étant fortement recommandé"],"correctIndex":3,"explanation":"Le port de gants homologués est obligatoire pour tout conducteur ou passager de deux-roues motorisé ; blouson, pantalon renforcé et bottes sont vivement recommandés sans être une obligation légale directe."},
  {"id":"kq273","type":"knowledge","theme":"usagers","question":"Les deux-roues motorisés doivent-ils allumer leurs feux de croisement en permanence, même de jour ?","options":["Oui, feux de croisement allumés de jour comme de nuit","Non, un feu de position suffit en agglomération le jour","Oui, mais hors agglomération et sur voie rapide","Non, par temps de pluie, de brouillard ou dans les tunnels"],"correctIndex":0,"explanation":"Les deux-roues motorisés doivent circuler feux de croisement allumés en permanence, de jour comme de nuit, afin d'être mieux repérés par les autres usagers."},
  {"id":"kq274","type":"knowledge","theme":"usagers","question":"Un piéton isolé qui marche sur une route sans trottoir ni accotement, hors agglomération, doit en principe se tenir :","options":["À droite de la chaussée, dans le sens de circulation des véhicules","À gauche, face aux véhicules qui arrivent en sens inverse","Au milieu de la chaussée, en file, pour être mieux vus","Du côté de leur choix, sans règle imposée hors agglomération"],"correctIndex":1,"explanation":"Hors agglomération, sauf danger ou circonstances particulières, le piéton marche près du bord gauche de la chaussée, face aux véhicules (art. R412-36). Les groupes de piétons suivent une règle propre (art. R412-42)."},
  {"id":"kq275","type":"knowledge","theme":"usagers","question":"Un piéton portant des écouteurs et regardant son téléphone en traversant :","options":["Perd sa priorité et le conducteur n'a plus à ralentir","Est entièrement responsable en cas de choc, même sur un passage protégé","Se met en danger lui-même, sans dispenser le conducteur de rester prudent","N'est plus considéré comme un piéton vulnérable par le code"],"correctIndex":2,"explanation":"Un piéton distrait se met en danger par son propre comportement, mais cela n'enlève rien à l'obligation du conducteur de rester attentif et prudent envers tous les usagers vulnérables."},
  {"id":"kq276","type":"knowledge","theme":"usagers","question":"Les véhicules de collecte des déchets (bennes à ordures) à l'arrêt avec leurs feux spéciaux activés imposent aux véhicules qui les croisent de :","options":["Ne rien changer si la voie est libre, les agents restant sur le trottoir","S'arrêter à plus de 10 mètres jusqu'à la fin de la collecte","Passer à distance en klaxonnant pour prévenir les agents","Ralentir et redoubler de prudence, des agents travaillant à proximité"],"correctIndex":3,"explanation":"À l'approche d'un véhicule de collecte avec ses feux spéciaux, il faut ralentir et rester très prudent, des agents pouvant se trouver sur ou à proximité de la chaussée."},
  {"id":"kq277","type":"knowledge","theme":"usagers","question":"Les motos et scooters peuvent-ils se garer sur les places réservées aux deux-roues situées sur les trottoirs ?","options":["Oui, quand la commune a aménagé et signalé ces emplacements","Non, le stationnement sur trottoir est interdit même aux deux-roues","Oui, partout où le trottoir fait plus de deux mètres de large","Oui, de jour, à condition de laisser un mètre aux piétons"],"correctIndex":0,"explanation":"Certaines municipalités aménagent des emplacements de stationnement pour deux-roues sur une partie du trottoir, clairement signalés : leur usage y est alors autorisé."},
  {"id":"kq278","type":"knowledge","theme":"usagers","question":"Un titulaire du permis A2 est soumis à :","options":["Une interdiction de transporter un passager","Une limitation de la puissance des motos qu'il conduit","Une limitation de vitesse à 90 km/h sur les routes","Une interdiction de circuler sur autoroute la première année"],"correctIndex":1,"explanation":"Le permis A2 limite la puissance des motos pouvant être conduites, une étape intermédiaire avant l'accès à la catégorie A sans restriction de puissance après deux ans d'expérience minimum et une formation complémentaire."},
  {"id":"kq279","type":"knowledge","theme":"usagers","question":"Un cycliste peut légalement circuler sur un trottoir :","options":["Oui, à condition de rouler au pas et de céder aux piétons","Oui, quand la piste cyclable est occupée ou en travaux","Non, sauf à pied en poussant son vélo, ou enfant de moins de 8 ans","Oui, si la chaussée est limitée à plus de 50 km/h"],"correctIndex":2,"explanation":"Un cycliste en selle ne doit pas circuler sur le trottoir, réservé aux piétons ; il peut y marcher en tenant son vélo à la main. Seuls les enfants de moins de 8 ans y sont autorisés, à l'allure du pas et sans gêner les piétons (R431-9)."},
  {"id":"kq280","type":"knowledge","theme":"usagers","question":"Les enfants de moins de 8 ans peuvent circuler à vélo sur le trottoir :","options":["Jamais, le trottoir étant réservé aux piétons de tout âge","À vitesse normale, si le trottoir est large et sans piéton","S'ils ont moins de 5 ans et un adulte à côté","À l'allure du pas, en laissant la priorité aux piétons"],"correctIndex":3,"explanation":"Les enfants de moins de 8 ans sont autorisés à circuler à vélo sur les trottoirs, mais uniquement à l'allure du pas et en cédant systématiquement le passage aux piétons."},
  {"id":"kq281","type":"knowledge","theme":"usagers","question":"Un motard qui circule avec un phare avant éteint ou défectueux de jour :","options":["Commet une infraction, car les feux de croisement sont obligatoires","Ne commet pas d'infraction tant qu'il roule en agglomération à moins de 50 km/h","Ne risque qu'un simple avertissement, l'éclairage de jour étant facultatif","Commet une infraction si la visibilité est réduite par la pluie"],"correctIndex":0,"explanation":"L'allumage des feux de croisement est obligatoire pour tout deux-roues motorisé de jour comme de nuit : rouler feux éteints de jour constitue une infraction."},
  {"id":"kq283","type":"knowledge","theme":"usagers","question":"Les véhicules de transport de fonds ou véhicules blindés bénéficient-ils d'une priorité particulière sur la route ?","options":["Oui, comme les véhicules de secours (pompiers, SAMU)","Oui, quand les feux spéciaux sont allumés","Non, ils n'ont aucune priorité et suivent les règles normales","Non, sauf si l'équipage signale une attaque avec ses feux de détresse"],"correctIndex":2,"explanation":"Contrairement aux véhicules de secours ou d'intervention, les véhicules de transport de fonds n'ont aucune priorité particulière et doivent respecter les règles de circulation comme tout autre véhicule."},
  {"id":"kq284","type":"knowledge","theme":"usagers","question":"Les nouveaux engins de déplacement personnel motorisés (gyroroues, hoverboards, monoroues) sont soumis :","options":["À une réglementation distincte autorisant la circulation sur trottoir","À des règles propres à chaque engin, sans âge minimum ni équipements","À une interdiction de circuler en agglomération, sauf en zone piétonne","Aux mêmes règles que les trottinettes : âge, lieux de circulation, équipements"],"correctIndex":3,"explanation":"Les engins de déplacement personnel motorisés (EDPM), qu'il s'agisse de trottinettes, gyroroues ou hoverboards, sont soumis à une réglementation commune : interdiction de circuler sur le trottoir sauf autorisation, âge minimum, équipements de sécurité."},
  {"id":"kq285","type":"knowledge","theme":"reglementation","question":"Le nombre de points retirés pour une infraction dépend :","options":["De la gravité de l'infraction, allant généralement de 1 à 6 points","Du type de véhicule conduit, avec un maximum de 12 points par infraction","De l'ancienneté du permis, avec un maximum de 3 points par infraction","De la gravité de l'infraction, mais jamais plus de 3 points au total"],"correctIndex":0,"explanation":"Le retrait de points varie selon la gravité de l'infraction : de 1 point pour un petit excès de vitesse à 6 points pour les infractions les plus graves (grand excès de vitesse, alcool, stupéfiants, délit de fuite...)."},
  {"id":"kq286","type":"knowledge","theme":"reglementation","question":"Une amende forfaitaire correspond en général à :","options":["Un montant fixé par le juge selon les revenus du contrevenant, après une audience","Un montant prédéterminé, applicable sans passage devant un tribunal pour les contraventions courantes","Une amende pénale réservée aux délits, avec comparution obligatoire devant un tribunal","Un barème fixé par chaque commune, payable uniquement en mairie sous huit jours"],"correctIndex":1,"explanation":"L'amende forfaitaire est un montant fixé à l'avance pour les contraventions les plus courantes, payable directement sans comparution devant un tribunal, sauf contestation."},
  {"id":"kq288","type":"knowledge","theme":"reglementation","question":"Une infraction qualifiée de « délit » (par opposition à une contravention) se caractérise par :","options":["Une gravité intermédiaire, jugée par le tribunal de police et punie d'une amende uniquement","Une gravité identique à une contravention, mais jugée par le seul tribunal de police","Une gravité moindre, sanctionnée par une amende forfaitaire payable sans juge","Une gravité supérieure, avec risque de prison et jugement devant un tribunal correctionnel"],"correctIndex":3,"explanation":"Un délit routier (conduite sans permis, grand excès de vitesse, alcoolémie délictuelle, délit de fuite...) est plus grave qu'une contravention : il peut entraîner une peine de prison et se juge devant un tribunal correctionnel."},
  {"id":"kq289","type":"knowledge","theme":"reglementation","question":"Conduire alors que son permis est suspendu ou annulé expose à :","options":["Un délit sévèrement sanctionné (amende importante, prison possible, confiscation du véhicule)","Une contravention de 4e classe, avec retrait de points et amende forfaitaire de 135 €","Un délit puni d'une simple amende, sans peine de prison ni confiscation possible","Une suspension supplémentaire de même durée, sans aucune poursuite pénale"],"correctIndex":0,"explanation":"Conduire malgré une suspension ou une annulation de permis est un délit grave, passible d'une lourde amende, d'une peine de prison et d'une possible confiscation du véhicule."},
  {"id":"kq290","type":"knowledge","theme":"reglementation","question":"La carte grise (certificat d'immatriculation) doit être mise à jour notamment en cas de :","options":["Changement de compagnie d'assurance du conducteur","Changement de propriétaire du véhicule ou de domicile","Remplacement des pneus ou des jantes par un autre modèle","Passage au contrôle technique ou vidange chez un garagiste"],"correctIndex":1,"explanation":"La carte grise doit être mise à jour lors d'un changement de propriétaire (vente) ou d'un changement d'adresse du titulaire, dans les délais fixés par la réglementation."},
  {"id":"kq291","type":"knowledge","theme":"reglementation","question":"En cas de vente d'un véhicule d'occasion, le vendeur doit notamment remettre à l'acheteur :","options":["Le certificat de cession et la facture d'achat d'origine, sans la carte grise","La carte grise non barrée, pour que l'acheteur la fasse modifier seul","Le certificat de cession, la carte grise barrée et le certificat de situation administrative","Le certificat de cession seul, la carte grise restant à demander à la préfecture"],"correctIndex":2,"explanation":"La vente d'un véhicule d'occasion nécessite un certificat de cession, la carte grise barrée et datée, ainsi qu'un certificat de situation administrative attestant l'absence de gage ou d'opposition."},
  {"id":"kq292","type":"knowledge","theme":"reglementation","question":"Une attestation d'assurance (vignette verte) doit être :","options":["Collée sur le pare-brise, côté passager, sous peine d'amende","Apposée sur la plaque d'immatriculation arrière du véhicule","Remplacée par un autocollant vert à renouveler chaque année","N'a plus à être affichée, mais l'obligation d'être assuré demeure"],"correctIndex":3,"explanation":"L'obligation d'apposer la vignette verte d'assurance sur le pare-brise a été supprimée, mais l'obligation d'être assuré demeure totale et vérifiable via le fichier des véhicules assurés."},
  {"id":"kq293","type":"knowledge","theme":"reglementation","question":"Un véhicule impliqué dans un accident matériel entre deux conducteurs doit donner lieu, si possible, à :","options":["Un constat amiable rempli et signé par les deux parties","Une déclaration à la mairie dans les 24 heures qui suivent l'accident","Un procès-verbal établi par la police, dans tous les cas, sur place","Un échange de coordonnées verbal, suivi d'un courrier à la préfecture"],"correctIndex":0,"explanation":"En cas d'accident matériel, il est recommandé de remplir un constat amiable avec l'autre conducteur, document essentiel pour la déclaration à l'assurance."},
  {"id":"kq294","type":"knowledge","theme":"reglementation","question":"Le défaut de contrôle technique, lorsqu'il est constaté lors d'un contrôle routier, expose notamment à :","options":["Une amende et un retrait de 2 points, sans immobilisation possible","Une amende et une immobilisation possible du véhicule jusqu'à régularisation","Une suspension du permis de 3 mois et la saisie des plaques d'immatriculation","Un délai de régularisation de 30 jours, sans amende ni immobilisation"],"correctIndex":1,"explanation":"Rouler sans contrôle technique valide expose à une amende et le véhicule peut être immobilisé jusqu'à ce que la situation soit régularisée."},
  {"id":"kq295","type":"knowledge","theme":"reglementation","question":"Un jeune conducteur ayant obtenu son permis peut-il conduire seul immédiatement après l'examen pratique ?","options":["Non, il doit d'abord suivre un stage obligatoire de sécurité routière d'une journée","Non, il doit attendre la réception du permis définitif, soit plusieurs semaines","Oui, dès l'annonce du résultat favorable, en période probatoire, avec une attestation provisoire si besoin","Oui, mais accompagné d'un conducteur titulaire du permis depuis 5 ans pendant un mois"],"correctIndex":2,"explanation":"Dès l'annonce du résultat favorable à l'examen, le candidat peut conduire seul en période probatoire, le permis définitif ou une attestation provisoire lui permettant de circuler en attendant le titre définitif."},
  {"id":"kq296","type":"knowledge","theme":"reglementation","question":"Un excès de vitesse constaté entre 20 et 30 km/h au-dessus de la limite autorisée entraîne généralement :","options":["Un retrait de 3 points et une suspension de permis immédiate de 1 mois","Un retrait de 1 point, avec la même amende qu'un excès de moins de 20 km/h","Un retrait de 4 points et une amende forfaitaire majorée de moitié","Un retrait de 2 points et une amende forfaitaire de 135 €"],"correctIndex":3,"explanation":"Un excès de vitesse de 20 à moins de 30 km/h au-dessus de la limite entraîne un retrait de 2 points et une amende forfaitaire de 135 € (contravention de 4e classe)."},
  {"id":"kq297","type":"knowledge","theme":"reglementation","question":"Le fait de rouler sans permis (jamais obtenu) constitue :","options":["Un délit puni d'une amende élevée et possiblement de prison","Une contravention de 4e classe, punie d'une amende forfaitaire de 135 €","Un délit puni uniquement d'un retrait de points, sans amende","Une contravention de 5e classe, sans possibilité de peine de prison"],"correctIndex":0,"explanation":"Conduire un véhicule sans jamais avoir obtenu le permis correspondant est un délit, passible d'une amende pouvant atteindre 15 000€ et d'un an de prison."},
  {"id":"kq298","type":"knowledge","theme":"reglementation","question":"L'usage d'un avertisseur de radars (détecteur signalant la présence exacte d'un radar) est en France :","options":["Autorisé si l'appareil est homologué et déclaré en préfecture, avec vignette de conformité","Interdit ; seuls les avertisseurs de zones de danger, sans localisation précise de radar, sont tolérés","Interdit sur autoroute et voie rapide, mais autorisé en agglomération et sur route","Réservé aux véhicules professionnels et aux transports en commun, sous conditions"],"correctIndex":1,"explanation":"La détection précise de radars est interdite en France ; seule une signalisation de zones de danger plus large (sans localisation exacte de l'appareil) est tolérée, sous conditions."},
  {"id":"kq299","type":"knowledge","theme":"reglementation","question":"En cas de contrôle, présenter un permis de conduire falsifié ou appartenant à une autre personne constitue :","options":["Une contravention de 4e classe, avec amende forfaitaire de 135 €","Une faute administrative sanctionnée par un retrait de 3 points au plus","Un délit grave, sanctionné pénalement","Une irrégularité régularisable sous 48 heures au commissariat"],"correctIndex":2,"explanation":"L'usage d'un faux document ou du permis d'autrui constitue un délit grave (usage de faux, notamment), sévèrement sanctionné par la loi pénale."},
  {"id":"kq300","type":"knowledge","theme":"reglementation","question":"La responsabilité civile d'un conducteur couvre principalement :","options":["Les dommages subis par le conducteur responsable, y compris ses blessures et son propre véhicule","Les dommages causés par le vol, l'incendie ou le bris de glace du véhicule assuré","Les dommages corporels des passagers, mais pas les dégâts matériels causés aux autres véhicules","Les dommages matériels et corporels causés à des tiers (autres personnes, véhicules, biens)"],"correctIndex":3,"explanation":"L'assurance responsabilité civile obligatoire couvre les dommages, matériels et corporels, que le conducteur peut causer à autrui en cas d'accident dont il est responsable."},
  {"id":"kq301","type":"knowledge","theme":"reglementation","question":"Un conducteur qui subit un vol de son véhicule doit notamment :","options":["Déposer plainte rapidement et informer son assureur dans les délais prévus par le contrat","Faire opposition à la carte grise en préfecture et attendre un mois avant toute déclaration","Informer son assureur, sans dépôt de plainte, le vol étant couvert d'office","Déposer plainte dans les trois mois qui suivent et signaler le vol à la préfecture seulement"],"correctIndex":0,"explanation":"En cas de vol, il faut déposer plainte rapidement auprès des forces de l'ordre et déclarer le sinistre à son assureur dans le délai contractuel prévu (généralement 2 jours ouvrés)."},
  {"id":"kq302","type":"knowledge","theme":"reglementation","question":"Le malus applicable après un accident responsable a pour effet :","options":["De retirer 1 point au permis du conducteur responsable de l'accident","D'augmenter la prime d'assurance du conducteur responsable","De diminuer la prime du conducteur responsable l'année suivante","D'annuler le contrat d'assurance dès le premier accident responsable"],"correctIndex":1,"explanation":"Le système bonus-malus augmente la prime d'assurance après un accident responsable, indépendamment d'un éventuel retrait de points qui relève, lui, de l'infraction commise."},
  {"id":"kq303","type":"knowledge","theme":"reglementation","question":"Un conducteur peut-il être verbalisé pour excès de vitesse par un radar automatique sans interception par les forces de l'ordre ?","options":["Non, un agent doit constater l'infraction et interpeller le conducteur sur place","Non, le radar sert seulement à la prévention, la verbalisation relevant de la gendarmerie","Oui, l'avis de contravention est envoyé directement au domicile du titulaire de la carte grise","Oui, mais l'avis est envoyé à l'employeur du conducteur et non au titulaire"],"correctIndex":2,"explanation":"Les radars automatiques (fixes, mobiles, embarqués) photographient l'infraction et l'avis de contravention est envoyé par courrier directement au titulaire du certificat d'immatriculation."},
  {"id":"kq304","type":"knowledge","theme":"reglementation","question":"Le titulaire d'une carte grise qui n'était pas le conducteur au moment de l'infraction constatée par radar automatique doit, pour éviter un retrait de points :","options":["Payer l'amende majorée et conserver le justificatif pour récupérer les points","Contester l'infraction devant le tribunal de police dans un délai d'un an","Faire une déclaration de perte ou de vol de la carte grise en gendarmerie","Désigner le véritable conducteur dans le délai imparti sur l'avis de contravention"],"correctIndex":3,"explanation":"Le titulaire de la carte grise doit désigner le conducteur réel dans le délai indiqué, sous peine de devoir payer l'amende sans transfert du retrait de points, ou de s'exposer à une amende pour non-désignation."},
  {"id":"kq305","type":"knowledge","theme":"reglementation","question":"Une contravention pour stationnement gênant (hors zones très gênantes) est en général classée en :","options":["2e classe, avec une amende forfaitaire de 35 €","4e classe, comme le stationnement très gênant","1re classe, sans possibilité d'amende majorée","Un délit, dès la deuxième infraction constatée"],"correctIndex":0,"explanation":"Le stationnement gênant est une contravention de 2e classe (35 € en amende forfaitaire), moins sévère que le stationnement très gênant, de 4e classe (135 €)."},
  {"id":"kq306","type":"knowledge","theme":"reglementation","question":"Un véhicule circulant avec des plaques d'immatriculation illisibles ou non conformes s'expose à :","options":["Un retrait de 3 points et une suspension de permis de 6 mois","Une amende, le véhicule pouvant également être immobilisé","Une amende, mais seulement si le contrôle a lieu de nuit","Une régularisation sous 72 heures, sans amende ni immobilisation"],"correctIndex":1,"explanation":"Des plaques illisibles, mal fixées ou non conformes constituent une infraction sanctionnée par une amende, avec un risque d'immobilisation du véhicule jusqu'à mise en conformité."},
  {"id":"kq307","type":"knowledge","theme":"reglementation","question":"Le fait de ne pas s'arrêter à la demande des forces de l'ordre (refus d'obtempérer) constitue :","options":["Une contravention de 4e classe, avec un retrait de 2 points","Une faute civile, sanctionnée uniquement par l'assureur du conducteur","Un délit, avec des sanctions aggravées si mise en danger d'autrui","Un délit seulement en cas de récidive dans les cinq ans, sinon une simple amende"],"correctIndex":2,"explanation":"Le refus d'obtempérer est un délit sévèrement sanctionné, les peines étant aggravées lorsque ce refus met en danger la vie d'autrui, notamment des forces de l'ordre."},
  {"id":"kq308","type":"knowledge","theme":"reglementation","question":"L'obligation d'installer un dispositif d'antidémarrage par éthylotest électronique (EAD) peut être imposée :","options":["Pour tout excès de vitesse de plus de 20 km/h constaté par un radar automatique","À tous les conducteurs en période probatoire, dès leur premier contrôle d'alcoolémie","Lors du passage du contrôle technique, pour les véhicules de plus de dix ans","Comme alternative ou complément à une suspension de permis dans certains cas d'infraction liée à l'alcool"],"correctIndex":3,"explanation":"Dans certains cas d'infraction liée à l'alcool, un juge ou le préfet peut imposer l'installation d'un éthylotest anti-démarrage (EAD), permettant de continuer à conduire sous conditions strictes."},
  {"id":"kq309","type":"knowledge","theme":"reglementation","question":"Un conducteur peut consulter le solde de points de son permis de conduire :","options":["Via le site officiel de l'administration (télépoints) ou en préfecture","Auprès de l'assureur du véhicule, sur présentation de la carte grise et du permis","En mairie, sur présentation d'une pièce d'identité et du permis de conduire","Par courrier recommandé adressé au tribunal de police du domicile"],"correctIndex":0,"explanation":"Chaque conducteur peut consulter son solde de points via le service officiel en ligne dédié ou en se rendant en préfecture, afin de suivre l'évolution de son capital de points."},
  {"id":"kq310","type":"knowledge","theme":"reglementation","question":"Le délai pour contester une amende forfaitaire est généralement de :","options":["30 jours à compter du paiement de l'amende forfaitaire","45 jours à compter de l'avis de contravention","60 jours à compter de la date de verbalisation","15 jours à compter de la date de l'avis de contravention"],"correctIndex":1,"explanation":"Le délai légal pour contester une amende forfaitaire est en général de 45 jours à compter de la date de l'avis de contravention, faute de quoi elle devient définitive et majorée."},
  {"id":"kq311","type":"knowledge","theme":"reglementation","question":"Circuler avec un véhicule dont le poids ou les dimensions dépassent la réglementation sans autorisation spéciale (convoi exceptionnel) est :","options":["Toléré si un véhicule d'accompagnement suit le convoi, sans autre démarche","Autorisé de nuit et le week-end, sur simple déclaration en mairie","Interdit, sauf obtention préalable d'une autorisation de transport exceptionnel","Autorisé pour les trajets de moins de 50 km, sans aucune démarche préalable"],"correctIndex":2,"explanation":"Le transport de charges ou de véhicules hors gabarit ou hors poids réglementaire nécessite une autorisation préalable de transport exceptionnel, avec des conditions de circulation encadrées."},
  {"id":"kq312","type":"knowledge","theme":"reglementation","question":"L'obligation d'équiper son véhicule de pneus hiver ou de disposer de chaînes/chaussettes neige, dans les zones montagneuses concernées, s'applique :","options":["D'octobre à avril sur tout le territoire, quelle que soit l'altitude","Uniquement les jours de neige déclarés par la préfecture, dans toute la France","De décembre à février, dans les massifs concernés, pour les seuls véhicules lourds","Pendant une période hivernale (généralement de novembre à mars), dans les massifs concernés"],"correctIndex":3,"explanation":"La loi Montagne impose, dans les zones concernées et pendant une période hivernale définie (souvent du 1er novembre au 31 mars), l'équipement en pneus hiver ou la présence de dispositifs antidérapants (chaînes, chaussettes)."},
  {"id":"kq313","type":"knowledge","theme":"reglementation","question":"Un conducteur étranger résidant en France depuis plus d'un an doit en principe :","options":["Échanger son permis contre un permis français dans le délai prévu, selon les accords avec son pays","Faire valider son permis étranger par une traduction assermentée, valable à vie","Repasser le code et la conduite après un an de séjour, quel que soit son pays d'origine","Conduire avec un permis international, à renouveler tous les trois ans"],"correctIndex":0,"explanation":"Selon les accords bilatéraux ou le pays d'origine, un résident étranger doit généralement faire échanger son permis contre un titre français dans un délai déterminé après l'installation en France."},
  {"id":"kq314","type":"knowledge","theme":"environnement","question":"La vignette Crit'Air numéro 0 (véhicule 100% électrique ou hydrogène) permet :","options":["D'accéder aux ZFE en journée, sauf lors des pics de pollution","De circuler sans restriction en ZFE, y compris en cas de pic de pollution","D'obtenir le stationnement gratuit dans les zones urbaines","D'être dispensé du contrôle technique tant que le véhicule roule"],"correctIndex":1,"explanation":"Les véhicules classés Crit'Air 0 (électriques, hydrogène) bénéficient d'un accès privilégié aux zones à faibles émissions, y compris lors des restrictions de circulation liées aux pics de pollution."},
  {"id":"kq315","type":"knowledge","theme":"environnement","question":"En cas de pic de pollution avec circulation différenciée, les véhicules les plus anciens ou les plus polluants (Crit'Air 4, 5 ou non classés) :","options":["Doivent rouler au pas dans toutes les zones concernées","Sont interdits de circulation de façon définitive dans toute la région","Peuvent être restreints ou interdits temporairement dans les zones concernées","Sont autorisés à circuler les week-ends dans les zones concernées"],"correctIndex":2,"explanation":"Lors d'un pic de pollution, les autorités peuvent mettre en place une circulation différenciée restreignant ou interdisant temporairement les véhicules les plus polluants dans les zones concernées."},
  {"id":"kq316","type":"knowledge","theme":"environnement","question":"L'écoconduite recommande de changer de vitesse (boîte manuelle) :","options":["Le plus tard possible, en gardant un haut régime moteur","Dès 1000 tr/min, quel que soit le rapport engagé","Seulement après avoir atteint la vitesse maximale du rapport","À un régime moteur modéré, sans faire hurler le moteur"],"correctIndex":3,"explanation":"Passer les vitesses à un régime moteur modéré, sans le faire monter inutilement haut, permet de réduire la consommation de carburant et l'usure du moteur."},
  {"id":"kq317","type":"knowledge","theme":"environnement","question":"L'utilisation du frein moteur en descente, en anticipant le relâchement de l'accélérateur, permet notamment de :","options":["Économiser du carburant et ménager les freins classiques","Consommer un peu plus mais ménager les freins classiques","Faire baisser la température du moteur et la consommation d'huile","Éviter le recours au frein de stationnement en pente"],"correctIndex":0,"explanation":"Utiliser le frein moteur en descente, en anticipant, permet d'économiser du carburant (l'injection est souvent coupée) et de préserver les freins classiques d'une surchauffe."},
  {"id":"kq318","type":"knowledge","theme":"environnement","question":"Un véhicule hybride combine généralement :","options":["Un moteur thermique et une pile à combustible à hydrogène","Un moteur thermique et un ou plusieurs moteurs électriques","Deux moteurs thermiques fonctionnant avec des carburants différents","Un moteur électrique et un turbocompresseur à gaz"],"correctIndex":1,"explanation":"Un véhicule hybride associe un moteur thermique classique à un ou plusieurs moteurs électriques, permettant de réduire la consommation de carburant et les émissions selon le mode de conduite."},
  {"id":"kq319","type":"knowledge","theme":"environnement","question":"La recharge d'un véhicule électrique sur une borne publique nécessite généralement :","options":["Une identification par plaque d'immatriculation auprès de la mairie locale","Un badge délivré par le constructeur, valable sur toutes les bornes","Une carte ou une application dédiée selon l'opérateur de la borne","Une autorisation préalable de l'opérateur d'électricité à chaque recharge"],"correctIndex":2,"explanation":"Selon l'opérateur de la borne, la recharge nécessite généralement une carte RFID, une application mobile ou un badge dédié pour identifier l'utilisateur et facturer la recharge."},
  {"id":"kq320","type":"knowledge","theme":"environnement","question":"L'autonomie d'un véhicule électrique peut être réduite significativement par :","options":["Une charge complète de la batterie avant chaque départ","Une conduite souple avec récupération d'énergie au freinage","Des pneus gonflés à la pression recommandée par le constructeur","Le froid, l'usage intensif du chauffage et une conduite à vitesse élevée"],"correctIndex":3,"explanation":"Le froid, l'usage important du chauffage ou de la climatisation, ainsi qu'une conduite rapide et peu anticipée, réduisent notablement l'autonomie réelle d'un véhicule électrique."},
  {"id":"kq321","type":"knowledge","theme":"environnement","question":"Le bruit excessif d'un véhicule (pot d'échappement modifié, klaxon abusif) constitue :","options":["Une infraction, pouvant être sanctionnée par une amende","Une incivilité non sanctionnée si le véhicule est homologué","Une infraction passible d'un retrait de permis immédiat","Une infraction ne concernant que les véhicules de plus de 3,5 t"],"correctIndex":0,"explanation":"Un véhicule dont le bruit dépasse les normes réglementaires (échappement modifié notamment) constitue une infraction sanctionnable, la pollution sonore étant aussi prise en compte par la loi."},
  {"id":"kq322","type":"knowledge","theme":"environnement","question":"Le rejet volontaire de déchets par la fenêtre d'un véhicule en circulation (mégot, emballage...) est :","options":["Toléré sur les routes peu fréquentées, si le déchet est biodégradable","Une infraction sanctionnée, avec un risque d'incendie ou de pollution","Autorisé sur autoroute, où la vitesse disperse les déchets","Sans sanction si le déchet est petit et éteint, comme un mégot"],"correctIndex":1,"explanation":"Jeter un déchet depuis un véhicule en mouvement est une infraction sanctionnée par une amende, ce geste pouvant en plus provoquer un incendie (mégot) ou polluer l'environnement."},
  {"id":"kq323","type":"knowledge","theme":"environnement","question":"Le principe du « stop and start » (arrêt automatique du moteur à l'arrêt) présent sur de nombreux véhicules récents vise à :","options":["Augmenter la puissance du moteur lors des redémarrages en ville","Recharger plus vite la batterie pendant les longs trajets sur autoroute","Réduire la consommation et les émissions lors des arrêts fréquents","Protéger le démarreur en limitant le nombre de démarrages à froid"],"correctIndex":2,"explanation":"Le système stop and start coupe automatiquement le moteur lors des arrêts brefs (feu rouge, bouchon), réduisant la consommation de carburant et les émissions polluantes en ville."},
  {"id":"kq324","type":"knowledge","theme":"environnement","question":"Anticiper les feux tricolores et ralentisseurs pour éviter les freinages puis accélérations inutiles relève :","options":["D'une conduite sportive sans lien avec l'écologie","D'un comportement qui fait perdre du temps au conducteur","D'une technique réservée aux conducteurs de poids lourds","D'une conduite économique et écologique (écoconduite)"],"correctIndex":3,"explanation":"Anticiper la circulation pour éviter les freinages et relances inutiles est l'un des principes fondamentaux de l'écoconduite, réduisant consommation et émissions."},
  {"id":"kq325","type":"knowledge","theme":"environnement","question":"Le choix d'un itinéraire évitant les zones très embouteillées permet généralement de :","options":["Réduire le temps passé au ralenti et donc la consommation","Allonger la distance parcourue et donc la consommation","Gagner du temps sans effet sur la consommation","Limiter l'usure des pneus, sans effet sur les émissions"],"correctIndex":0,"explanation":"Éviter les zones très embouteillées réduit le temps passé au ralenti ou à vitesse très faible, une situation où la consommation rapportée à la distance parcourue est particulièrement élevée."},
  {"id":"kq326","type":"knowledge","theme":"environnement","question":"L'indice de performance environnementale d'un pneu (étiquette pneu) prend notamment en compte :","options":["La durée de vie, la résistance à la crevaison et le prix","La résistance au roulement, l'adhérence sur sol mouillé et le bruit","La charge maximale, l'indice de vitesse et la largeur","L'adhérence sur sol sec, la résistance à l'usure et le prix"],"correctIndex":1,"explanation":"L'étiquetage européen des pneus informe sur la résistance au roulement (liée à la consommation), l'adhérence sur sol mouillé (sécurité) et le niveau de bruit extérieur émis."},
  {"id":"kq327","type":"knowledge","theme":"environnement","question":"Une conduite avec un rapport de vitesse trop bas par rapport à l'allure (sur-régime) entraîne :","options":["Une baisse de la consommation grâce à un meilleur couple moteur à bas régime","Une consommation stable mais un échauffement plus rapide des disques de frein","Une augmentation de la consommation et une usure prématurée du moteur","Une meilleure reprise en côte, sans effet notable sur la consommation"],"correctIndex":2,"explanation":"Rouler en sur-régime (rapport trop bas pour la vitesse) augmente inutilement la consommation de carburant et accélère l'usure du moteur."},
  {"id":"kq328","type":"knowledge","theme":"environnement","question":"L'aérodynamisme d'un véhicule influence sa consommation, notamment :","options":["Surtout à faible vitesse, dans la circulation urbaine dense","De façon constante quelle que soit l'allure du véhicule","Principalement lors des démarrages et des arrêts répétés","Surtout à vitesse élevée, comme sur autoroute"],"correctIndex":3,"explanation":"La résistance de l'air augmente fortement avec la vitesse : l'aérodynamisme (et donc les accessoires ajoutés comme une galerie) influence surtout la consommation à haute vitesse, notamment sur autoroute."},
  {"id":"kq329","type":"knowledge","theme":"environnement","question":"Le dispositif de recyclage des gaz d'échappement (EGR) sur un moteur diesel vise notamment à :","options":["Réduire certaines émissions polluantes (oxydes d'azote)","Accroître la puissance du moteur à haut régime","Éliminer les particules fines à la place du filtre à particules","Réduire la consommation d'huile du moteur diesel"],"correctIndex":0,"explanation":"La vanne EGR recycle une partie des gaz d'échappement dans la combustion, ce qui permet de réduire la température de combustion et donc les émissions d'oxydes d'azote."},
  {"id":"kq330","type":"knowledge","theme":"environnement","question":"L'utilisation du covoiturage pour les trajets domicile-travail contribue notamment à :","options":["Réduire le nombre de places de stationnement disponibles dans les centres-villes","Réduire la congestion routière et les émissions liées aux trajets pendulaires","Diminuer les embouteillages le week-end mais pas aux heures de pointe en semaine","Limiter surtout les émissions liées aux trajets touristiques de longue distance"],"correctIndex":1,"explanation":"Le covoiturage pour les trajets domicile-travail réduit le nombre de véhicules en circulation aux heures de pointe, limitant congestion et émissions polluantes."},
  {"id":"kq331","type":"knowledge","theme":"environnement","question":"Le choix d'un mode de transport alternatif (vélo, marche, transports en commun) pour les courts trajets urbains permet notamment de :","options":["Garantir un trajet toujours plus rapide qu'en voiture, quelle que soit la distance","Diminuer le bruit en ville sans effet sur la qualité de l'air","Réduire les émissions polluantes et améliorer sa condition physique","Éviter les frais de stationnement mais sans impact sur la pollution"],"correctIndex":2,"explanation":"Pour les trajets courts en ville, privilégier la marche, le vélo ou les transports en commun réduit les émissions polluantes locales tout en favorisant l'activité physique."},
  {"id":"kq332","type":"knowledge","theme":"environnement","question":"Un véhicule surchargé (au-delà du poids autorisé) consomme et pollue :","options":["Moins, car le moteur travaille à un régime plus stable","Autant qu'à vide, mais avec un freinage plus long","Davantage seulement en côte, sans risque pour le freinage","Davantage, avec des risques pour la tenue de route et le freinage"],"correctIndex":3,"explanation":"Un véhicule surchargé consomme davantage de carburant et pollue plus, tout en présentant des risques accrus pour la tenue de route, le freinage et l'usure des pneus."},
  {"id":"kq333","type":"knowledge","theme":"environnement","question":"Les zones à trafic limité (ZTL), que l'on trouve notamment dans certains centres-villes, ont pour objectif principal de :","options":["Réduire la circulation automobile dans les centres historiques ou sensibles","Fluidifier le trafic de transit sur les grands axes et les rocades","Interdire l'accès des rues piétonnes aux vélos et aux trottinettes","Augmenter l'offre de stationnement en surface pour les riverains"],"correctIndex":0,"explanation":"Les zones à trafic limité restreignent l'accès des véhicules motorisés dans certains secteurs urbains, souvent historiques, afin de réduire la circulation, le bruit et la pollution."},
  {"id":"kq334","type":"knowledge","theme":"environnement","question":"L'entretien régulier de la climatisation (recharge de gaz, filtres) d'un véhicule contribue à :","options":["Réduire la consommation d'huile moteur et limiter la formation de buée en hiver","Limiter les fuites de gaz réfrigérant nocif pour le climat et la surconsommation","Prolonger la durée de vie de la batterie et du démarreur, mais sans enjeu écologique","Diminuer le bruit du moteur et la consommation d'huile"],"correctIndex":1,"explanation":"Un entretien régulier limite les fuites de gaz réfrigérant, souvent nocif pour l'effet de serre, tout en assurant un fonctionnement optimal qui limite la surconsommation de carburant liée à la climatisation."},
  {"id":"kq335","type":"knowledge","theme":"environnement","question":"Le fait de rouler avec des vitres ouvertes à vitesse élevée sur autoroute, plutôt qu'avec la climatisation, peut :","options":["Réduire la consommation, quelle que soit la vitesse pratiquée","Améliorer l'aérodynamisme en évacuant l'air chaud de l'habitacle","Augmenter la traînée et donc parfois la consommation à haute vitesse","Réduire le bruit dans l'habitacle et la consommation de carburant"],"correctIndex":2,"explanation":"À haute vitesse, rouler vitres ouvertes augmente la résistance aérodynamique, ce qui peut in fine consommer davantage de carburant que d'utiliser la climatisation, contrairement à une conduite urbaine lente."},
  {"id":"kq336","type":"knowledge","theme":"environnement","question":"Les biocarburants (comme l'E85 ou le B100) ont pour objectif principal de :","options":["Éliminer les émissions de CO2 des véhicules thermiques dès leur emploi","Réduire le prix du carburant en supprimant les taxes","Servir de carburant exclusif aux véhicules hybrides rechargeables","Réduire en partie la dépendance aux fossiles et certaines émissions"],"correctIndex":3,"explanation":"Les biocarburants, produits à partir de matières organiques, visent à réduire une partie de la dépendance aux énergies fossiles et peuvent diminuer certaines émissions, selon leur mode de production."},
  {"id":"kq337","type":"knowledge","theme":"environnement","question":"L'écoconduite recommande, à l'approche d'un feu visiblement rouge depuis longtemps, de :","options":["Lever le pied tôt et laisser le véhicule ralentir en frein moteur","Maintenir sa vitesse jusqu'au dernier moment, puis freiner à fond","Rester sur un rapport élevé et accélérer légèrement pour garder l'élan","Passer au point mort et rouler sur l'élan pour économiser le carburant"],"correctIndex":0,"explanation":"En anticipant un feu rouge visible de loin, il vaut mieux lever le pied tôt et laisser le véhicule décélérer naturellement, économisant du carburant plutôt que de freiner fort au dernier moment."},
  {"id":"kq338","type":"knowledge","theme":"environnement","question":"Le suivi de l'indicateur de changement de vitesse (souvent présent sur le tableau de bord) sert à :","options":["Indiquer la vitesse maximale autorisée sur le tronçon où l'on circule","Suggérer le moment pour changer de rapport et limiter la consommation","Avertir le conducteur que le moteur approche de sa température critique","Prévenir le conducteur qu'une révision du moteur est devenue nécessaire"],"correctIndex":1,"explanation":"Cet indicateur, présent sur de nombreux véhicules à boîte manuelle, suggère le moment optimal pour passer un rapport supérieur ou inférieur afin d'optimiser la consommation de carburant."},
  {"id":"kq339","type":"knowledge","theme":"environnement","question":"Un véhicule mal réglé (parallélisme incorrect des roues) peut entraîner :","options":["Une usure régulière des pneus avec une consommation en baisse sensible","Une usure irrégulière des pneus sans effet sur la consommation","Une usure irrégulière des pneus et une augmentation de la consommation","Une surchauffe des freins avec une consommation inchangée"],"correctIndex":2,"explanation":"Un mauvais parallélisme entraîne une résistance au roulement accrue, une usure irrégulière et prématurée des pneus, ainsi qu'une surconsommation de carburant."},
  {"id":"kq340","type":"knowledge","theme":"environnement","question":"Les certificats qualité de l'air (vignettes Crit'Air) sont classés de :","options":["1 à 5","0 à 3","A à E","0 à 5"],"correctIndex":3,"explanation":"Les vignettes Crit'Air sont classées de 0 (véhicules électriques/hydrogène) à 5 (véhicules les plus anciens et polluants), les véhicules non éligibles restant non classés."},
  {"id":"kq341","type":"knowledge","theme":"environnement","question":"Ne pas obtenir ou ne pas apposer une vignette Crit'Air obligatoire dans une zone qui l'exige expose à :","options":["Une amende forfaitaire pour circulation en ZFE","Un simple avertissement écrit, sans amende, lors du premier contrôle","Un retrait de trois points sur le permis de conduire","Une immobilisation du véhicule pendant quarante-huit heures"],"correctIndex":0,"explanation":"Circuler dans une zone à faibles émissions sans la vignette Crit'Air requise, ou sans en disposer alors qu'elle est obligatoire, expose à une amende forfaitaire."},
  {"id":"kq342","type":"knowledge","theme":"environnement","question":"Le bilan carbone d'un déplacement en voiture individuelle comparé au même trajet en train est généralement :","options":["Équivalent pour les deux modes dès que le train n'est pas électrifié","Nettement plus élevé pour la voiture individuelle que pour le train","Plus faible pour la voiture sur les trajets de plus de 500 km","Sans rapport avec le mode de transport, seule la durée compte"],"correctIndex":1,"explanation":"Pour un trajet comparable, une voiture individuelle thermique émet en général nettement plus de CO2 par passager qu'un trajet équivalent en train, notamment sur les longues distances."},
  {"id":"kq343","type":"knowledge","theme":"environnement","question":"L'usage d'une application d'aide à l'écoconduite (affichant la consommation en temps réel) permet notamment de :","options":["Calculer automatiquement la vitesse maximale autorisée sur l'itinéraire","Se dispenser de l'entretien régulier du moteur et des pneus","Prendre conscience de l'impact de son style de conduite et l'adapter","Réduire la durée du trajet en augmentant la vitesse moyenne"],"correctIndex":2,"explanation":"Visualiser sa consommation en temps réel aide à identifier les comportements consommateurs (accélérations brusques, sur-régime) et à ajuster sa conduite en conséquence."},
  {"id":"kq344","type":"knowledge","theme":"environnement","question":"Au-delà des économies de carburant, une conduite souple et anticipée permet aussi de :","options":["Diminuer le montant de la prime d'assurance automobile","Limiter la pollution sonore de la circulation, sans autre bénéfice","Faciliter le recyclage des pneus usagés en fin de vie","Réduire l'usure des pièces et donc les déchets liés à l'entretien"],"correctIndex":3,"explanation":"Une conduite souple réduit aussi l'usure des freins, pneus et pièces mécaniques, ce qui limite indirectement la production de déchets liés à l'entretien et au remplacement des pièces."},
  {"id":"kq345","type":"knowledge","theme":"environnement","question":"Un contrôle technique intègre notamment un volet relatif aux émissions polluantes, en vérifiant :","options":["L'opacité des fumées (diesel) ou les émissions polluantes selon la motorisation","Le niveau de CO2 émis par kilomètre, comparé à la vignette Crit'Air","La conformité de la vignette Crit'Air apposée sur le pare-brise","Le niveau de remplissage du réservoir de carburant et d'huile"],"correctIndex":0,"explanation":"Le contrôle technique inclut une mesure des émissions polluantes du véhicule (opacité des fumées pour le diesel notamment), un dépassement des seuils pouvant entraîner une contre-visite."},
  {"id":"kq346","type":"knowledge","theme":"notions","question":"Un siège auto du groupe 0+ est conçu pour :","options":["Les enfants de 9 à 18 kg, installés face à la route avec un harnais intégré","Les nourrissons, jusqu'à environ 13 kg, installés dos à la route","Les enfants de 15 à 36 kg, qui utilisent directement la ceinture du véhicule","Les nourrissons jusqu'à 18 kg, installés face à la route sur le siège avant"],"correctIndex":1,"explanation":"Le groupe 0+ concerne les nourrissons jusqu'à environ 13 kg (ou selon la taille pour la norme i-Size), toujours installés dos à la route pour protéger leur tête et leur nuque fragiles."},
  {"id":"kq347","type":"knowledge","theme":"notions","question":"Un réhausseur (groupe 2/3) sert principalement à :","options":["Maintenir l'enfant avec un harnais intégré à cinq points d'attache, comme les sièges du groupe 1","Fixer l'enfant dos à la route pour protéger sa nuque et sa tête","Surélever l'enfant pour que la ceinture de sécurité adulte passe correctement sur son corps","Permettre à l'enfant de s'asseoir à l'avant même s'il a moins de 10 ans, sans désactiver l'airbag"],"correctIndex":2,"explanation":"Le réhausseur surélève l'enfant afin que la ceinture de sécurité du véhicule passe correctement sur l'épaule et le bassin, et non sur le cou ou l'abdomen, ce qui serait dangereux en cas de choc."},
  {"id":"kq348","type":"knowledge","theme":"notions","question":"Le poids total roulant autorisé (PTRA) correspond au :","options":["Poids maximal autorisé du véhicule tracteur seul, remorque exclue","Poids maximal que la remorque peut supporter, lesté de son chargement","Poids à vide de l'ensemble, indiqué sur les certificats d'immatriculation","Poids maximal autorisé de l'ensemble véhicule tracteur + remorque en charge"],"correctIndex":3,"explanation":"Le PTRA indique le poids maximal autorisé pour l'ensemble formé par le véhicule tracteur et sa remorque, tous deux chargés, une donnée essentielle pour savoir ce que l'on peut légalement tracter."},
  {"id":"kq349","type":"knowledge","theme":"notions","question":"Un chargement doit être arrimé de manière à :","options":["Ne pas se déplacer, tomber ou gêner la conduite, même en cas de freinage brusque","Pouvoir se déplacer légèrement tant qu'il ne tombe pas sur la chaussée","Être solidement fixé seulement lorsque le trajet dépasse 50 kilomètres","Être arrimé par une seule sangle, quelle que soit sa masse ou sa forme"],"correctIndex":0,"explanation":"Tout chargement doit être solidement arrimé afin de ne jamais se déplacer, tomber sur la chaussée ou gêner la conduite, y compris lors d'un freinage d'urgence ou d'un virage serré."},
  {"id":"kq350","type":"knowledge","theme":"notions","question":"Le permis B96 (ou la catégorie BE) permet notamment de :","options":["Conduire un ensemble de plus de 3,5 tonnes de PTAC sans aucune formation","Tracter des remorques plus lourdes que la limite du permis B, après formation","Conduire un autocar de plus de neuf places assises après un stage de 7 h","Conduire un deux-roues de plus de 125 cm³ après sept heures de formation"],"correctIndex":1,"explanation":"La formation B96 (ou le permis BE) permet, après une formation complémentaire, de tracter des remorques dépassant les limites de poids autorisées avec le seul permis B classique."},
  {"id":"kq351","type":"knowledge","theme":"notions","question":"Le port de la ceinture de sécurité pour une femme enceinte est :","options":["Obligatoire, mais avec la sangle basse passée sur le ventre pour mieux le protéger","Facultative dès le septième mois, la ceinture comprimant le ventre","Obligatoire, avec la sangle basse passée sous le ventre et non dessus","Obligatoire, mais seulement avec la sangle ventrale, sans sangle diagonale"],"correctIndex":2,"explanation":"Le port de la ceinture reste obligatoire et recommandé pour les femmes enceintes, à condition de bien positionner la sangle basse sous le ventre et la sangle diagonale entre les seins, sans passer sur le ventre."},
  {"id":"kq352","type":"knowledge","theme":"notions","question":"Un enfant de 4 ans pesant 17 kg doit, en principe, être installé dans :","options":["Un siège du groupe 0+ dos à la route, le groupe 1 étant réservé aux enfants de plus de 6 ans","Sur la banquette arrière avec la ceinture adulte, grâce à son poids de 17 kg","Sur le siège avant avec un coussin, ce qui évite le recours au siège auto","Un siège ou réhausseur adapté à son poids/sa taille, souvent un siège du groupe 1"],"correctIndex":3,"explanation":"À cet âge et ce poids, un enfant doit encore utiliser un dispositif de retenue adapté (souvent groupe 1), la ceinture adulte seule n'étant pas sûre avant environ 135 cm."},
  {"id":"kq353","type":"knowledge","theme":"notions","question":"Concernant le nombre maximal de personnes transportées dans un véhicule, il ne doit jamais dépasser :","options":["Le nombre de places assises indiqué sur la carte grise","Le nombre de places assises, auquel on peut ajouter un enfant sur les genoux","Cinq personnes pour toute voiture particulière, quelle que soit sa carte grise","Le nombre de places assises, plus deux passagers debout en agglomération"],"correctIndex":0,"explanation":"Le nombre de personnes transportées ne doit jamais excéder le nombre de places assises mentionné sur la carte grise, chaque occupant devant disposer d'une place et, si prévue, d'une ceinture."},
  {"id":"kq354","type":"knowledge","theme":"notions","question":"Un vélo transporté sur un porte-vélo arrière masquant la plaque d'immatriculation impose de :","options":["Rien de particulier si le porte-vélo est homologué, la plaque pouvant rester masquée","Disposer d'une plaque et de feux additionnels reproduisant ceux du véhicule","Coller la plaque d'immatriculation sur le vélo avec l'accord de la préfecture","Équiper le vélo d'un feu blanc à l'arrière et d'un catadioptre"],"correctIndex":1,"explanation":"Lorsque le chargement masque la plaque ou les feux du véhicule, il faut installer une plaque et des feux additionnels conformes, afin que le véhicule reste identifiable et visible."},
  {"id":"kq355","type":"knowledge","theme":"notions","question":"Le covoiturage régulier organisé via une plateforme dédiée relève :","options":["D'une activité de transport rémunéré, soumise à une licence de taxi ou de VTC dès le premier passager","D'un échange de services où le conducteur fixe librement un tarif lui laissant un bénéfice sur chaque trajet","D'un partage de frais entre particuliers pour un trajet que le conducteur effectue de toute façon","D'une pratique tolérée uniquement entre membres d'une même famille"],"correctIndex":2,"explanation":"Le covoiturage repose sur le partage des frais d'un trajet que le conducteur effectue pour son propre compte, ce qui le distingue juridiquement d'une activité de transport rémunéré comme le taxi ou le VTC."},
  {"id":"kq356","type":"knowledge","theme":"notions","question":"Transporter un enfant de moins de 3 ans à l'avant du véhicule, dos à la route, avec un airbag frontal actif, est :","options":["Toléré sur trajet court, à condition de reculer le siège passager au maximum","Sans risque si l'enfant est attaché par la ceinture, l'airbag s'adaptant au poids","Autorisé en agglomération, l'airbag étant moins puissant à vitesse réduite","Extrêmement dangereux : l'airbag doit impérativement être désactivé dans ce cas"],"correctIndex":3,"explanation":"Le déploiement d'un airbag frontal sur un siège dos à la route peut être mortel pour un nourrisson : l'airbag doit toujours être désactivé lorsqu'un tel siège est installé à l'avant."},
  {"id":"kq357","type":"knowledge","theme":"notions","question":"Le PTAC (poids total autorisé en charge) d'un véhicule se trouve généralement :","options":["Sur la carte grise (certificat d'immatriculation), à la rubrique F2","Sur le certificat de contrôle technique, à la ligne du poids maximal","Sur l'attestation d'assurance, à la rubrique des caractéristiques","Sur le permis de conduire, à la rubrique de la catégorie B"],"correctIndex":0,"explanation":"Le PTAC est indiqué sur la carte grise à la rubrique F.2 (poids maximal autorisé du véhicule chargé). La rubrique F.1 donne la masse techniquement admissible et F.3 le PTRA."},
  {"id":"kq358","type":"knowledge","theme":"notions","question":"Voyager avec un chien non attaché ou libre à l'intérieur de l'habitacle est :","options":["Sans risque tant que le chien est dressé et ne bouge pas pendant le trajet","Risqué et potentiellement sanctionnable, car il peut gêner le conducteur","Autorisé pour les petits chiens, mais interdit pour les chiens de plus de 20 kg","Réservé aux chiens munis d'une muselière, qui peuvent alors voyager librement"],"correctIndex":1,"explanation":"Un animal libre dans l'habitacle peut gêner la conduite et devient un projectile dangereux en cas de freinage brusque ou de choc : il doit être maintenu par un harnais, une caisse ou une grille de séparation."},
  {"id":"kq359","type":"knowledge","theme":"notions","question":"La largeur maximale autorisée pour un véhicule ou un attelage circulant sans autorisation spéciale est généralement de :","options":["2,25 mètres, 2,40 mètres pour les véhicules frigorifiques","3 mètres, 3,20 mètres pour certains véhicules frigorifiques","2,55 mètres (2,60 m pour certains véhicules frigorifiques)","2,40 mètres, rétroviseurs compris pour tous les véhicules"],"correctIndex":2,"explanation":"La largeur maximale autorisée pour circuler sans autorisation de transport exceptionnel est généralement de 2,55 mètres, portée à 2,60 mètres pour certains véhicules frigorifiques."},
  {"id":"kq360","type":"knowledge","theme":"notions","question":"Un enfant transporté en poussette près de la chaussée doit être maintenu :","options":["Avec la poussette placée en bordure du trottoir, roues tournées vers la chaussée pour surveiller les voitures","Avec le frein serré uniquement en pente, sans autre précaution tant que la poussette reste sur le trottoir","Avec le frein desserré, pour pouvoir reculer vite en cas de danger","Avec le frein de la poussette engagé à l'arrêt, et à distance de sécurité de la circulation"],"correctIndex":3,"explanation":"Une poussette doit toujours avoir son frein engagé à l'arrêt et être maintenue à distance de sécurité de la circulation, un enfant en poussette étant particulièrement vulnérable près de la route."},
  {"id":"kq361","type":"knowledge","theme":"notions","question":"Le poids à vide d'un véhicule (indiqué sur la carte grise) correspond :","options":["Au poids du véhicule sans chargement ni passagers, avec les niveaux de fluides pleins","Au poids maximal du véhicule chargé, indiqué à la rubrique F2","Au poids du véhicule avec un chargement équivalent à la moitié de sa charge utile","Au poids de la seule caisse, sans moteur ni boîte de vitesses"],"correctIndex":0,"explanation":"Le poids à vide (ou poids en ordre de marche) correspond au véhicule prêt à circuler, avec ses fluides pleins, mais sans passagers ni chargement supplémentaire."},
  {"id":"kq362","type":"knowledge","theme":"notions","question":"Utiliser un siège auto d'occasion nécessite de vérifier notamment :","options":["Que la notice a été conservée, un choc antérieur n'étant pas un critère","Qu'il n'a jamais subi de choc important et n'est pas trop ancien","Qu'il porte la marque d'un grand constructeur, ce qui garantit sa sécurité","Qu'il possède un harnais intégré, seul garant d'une bonne protection"],"correctIndex":1,"explanation":"Un siège auto d'occasion doit être vérifié : absence de choc antérieur (accident), respect de la date limite d'utilisation, présence de la notice et conformité aux normes en vigueur."},
  {"id":"kq363","type":"knowledge","theme":"notions","question":"Un enfant peut, à titre exceptionnel, être installé à l'avant d'un véhicule sans place arrière (utilitaire, certaines voitures deux places) :","options":["Non, le code de la route l'interdit pour tous les enfants de moins de 10 ans","Oui, avec la ceinture adulte seule, sans dispositif ni précaution pour l'airbag","Oui, avec un dispositif de retenue adapté, et l'airbag désactivé si besoin","Seulement si un adulte le tient sur ses genoux, ceinture bouclée pour deux, à l'arrière du véhicule"],"correctIndex":2,"explanation":"Dans un véhicule sans place arrière, un enfant peut exceptionnellement voyager à l'avant, à condition d'utiliser un dispositif de retenue adapté à son âge et de désactiver l'airbag frontal si le siège est dos à la route."},
  {"id":"kq364","type":"knowledge","theme":"notions","question":"Le fait de laisser un enfant seul dans un véhicule, même quelques minutes, notamment en cas de forte chaleur, est :","options":["Acceptable quelques minutes si le véhicule est garé à l'ombre, vitres entrouvertes","Toléré si l'enfant dort et que l'on reste à proximité immédiate du véhicule","Sans danger en hiver comme en été, puisque l'habitacle reste fermé","Extrêmement dangereux, la température intérieure pouvant monter très rapidement"],"correctIndex":3,"explanation":"La température à l'intérieur d'un véhicule peut monter de plusieurs dizaines de degrés en quelques minutes seulement, même par temps modéré : laisser un enfant seul dans une voiture est extrêmement dangereux, voire mortel."},
  {"id":"kq365","type":"knowledge","theme":"notions","question":"Une remorque légère (moins de 750 kg de PTAC) attelée à une voiture peut en général être tractée :","options":["Avec un simple permis B, sans formation complémentaire obligatoire","Avec un permis B, après une formation de 7 heures obligatoire pour toute remorque","Avec un permis B, mais seulement si le véhicule tracteur pèse plus d'une tonne","Avec un permis BE exclusivement, dès lors qu'elle pèse plus de 500 kg"],"correctIndex":0,"explanation":"Une remorque de 750 kg de PTAC au plus peut être tractée avec un simple permis B, sans formation complémentaire, à condition que le véhicule tracteur ait un PTAC d'au plus 3,5 t et soit apte à la tracter (PTRA respecté)."},
  {"id":"kq366","type":"knowledge","theme":"notions","question":"Charger une galerie de toit au-delà de la charge maximale autorisée par le constructeur peut entraîner :","options":["Une usure prématurée des pneus uniquement, sans effet sur la tenue de route","Une déstabilisation du véhicule, notamment dans les virages ou par vent latéral","Une amélioration de la stabilité, le poids en hauteur plaquant le véhicule au sol","Un simple dépassement de consommation, sans incidence sur la sécurité"],"correctIndex":1,"explanation":"Dépasser la charge maximale autorisée d'une galerie de toit modifie le centre de gravité du véhicule et peut le déstabiliser dangereusement, en particulier dans les virages ou par vent fort."},
  {"id":"kq367","type":"knowledge","theme":"notions","question":"Le fait de transporter des animaux dans le coffre d'un break ou d'un SUV, sans grille de séparation, expose en cas de freinage brusque à :","options":["Un risque de glissement vers l'arrière, sans conséquence pour les occupants","Un risque limité à l'animal, qui ne peut pas atteindre l'habitacle","Un risque de projection de l'animal vers l'avant, pouvant blesser les occupants","Une simple amende, sans aucun danger physique pour les occupants"],"correctIndex":2,"explanation":"Sans grille de séparation ni système de fixation, un animal dans le coffre peut être violemment projeté vers l'avant lors d'un freinage brusque, représentant un danger pour lui-même et pour les occupants."},
  {"id":"kq368","type":"knowledge","theme":"notions","question":"Il est recommandé de ne cesser d'utiliser un réhausseur que lorsque :","options":["Il a 6 ans révolus, âge à partir duquel la ceinture adulte suffit","Il pèse plus de 25 kg, quelle que soit sa taille ou sa morphologie","Il mesure plus de 1,10 m, taille où la ceinture adulte est suffisante","La ceinture adulte passe correctement sur son épaule et son bassin, vers 135-150 cm"],"correctIndex":3,"explanation":"C'est la taille de l'enfant, et non son âge seul, qui détermine quand la ceinture adulte peut passer correctement sans dispositif : généralement autour de 135 à 150 cm selon la morphologie."},
  {"id":"kq369","type":"knowledge","theme":"notions","question":"Avec un permis B, pour tracter une remorque de plus de 750 kg de PTAC, le PTAC de l'ensemble ne doit pas dépasser :","options":["3,5 tonnes, porté à 4,25 tonnes avec la formation B96","3,5 tonnes, porté à 5 tonnes avec la formation B96","4,25 tonnes sans formation, 3,5 tonnes avec le B96","3,5 tonnes, sans possibilité d'aller au-delà avec le B96"],"correctIndex":0,"explanation":"Avec un permis B, si la remorque dépasse 750 kg de PTAC, l'ensemble ne doit pas dépasser 3,5 t. La formation B96 (7 h) permet d'aller jusqu'à 4,25 t ; au-delà il faut le permis BE."},
  {"id":"kq370","type":"knowledge","theme":"notions","question":"Concernant les enfants en bas âge, l'installation d'un pare-soleil ou d'un rideau sur les vitres arrière :","options":["Est interdite dès lors que l'enfant a moins de 3 ans, même à l'arrière","Peut être utile contre l'éblouissement, sans gêner la visibilité du conducteur","Dispense d'utiliser le dispositif de retenue sur les trajets de moins de 20 km","Est obligatoire dès que la température extérieure dépasse 25 degrés, pour tout le trajet"],"correctIndex":1,"explanation":"Un pare-soleil sur les vitres arrière peut protéger l'enfant de l'éblouissement, à condition de ne jamais réduire la visibilité nécessaire du conducteur ni empêcher de surveiller l'enfant."},
  {"id":"kq371","type":"knowledge","theme":"notions","question":"Le fait de transporter plus de personnes que de ceintures de sécurité disponibles est :","options":["Toléré pour de courtes distances en agglomération, si la vitesse reste inférieure à 30 km/h","Autorisé pour les enfants de moins de 10 ans, qui peuvent alors partager une même ceinture à deux","Interdit, chaque occupant devant disposer d'une ceinture ou d'un dispositif de retenue adapté","Sanctionné seulement lorsqu'un accident corporel survient pendant le trajet"],"correctIndex":2,"explanation":"Chaque occupant doit disposer d'une place assise avec ceinture de sécurité (ou dispositif adapté pour un enfant) ; transporter plus de personnes que de ceintures disponibles est interdit et sanctionnable."},
  {"id":"kq372","type":"knowledge","theme":"notions","question":"L'installation d'un attelage de remorque sur un véhicule doit être :","options":["Déclarée à la préfecture avant chaque trajet avec une remorque","Limitée aux véhicules de plus de 3,5 tonnes de PTAC","Réalisée par un professionnel agréé uniquement sur les véhicules neufs de moins d'un an","Conforme aux normes en vigueur et compatible avec le véhicule concerné"],"correctIndex":3,"explanation":"Un attelage doit être homologué et compatible avec le véhicule, sa présence et son état étant susceptibles d'être vérifiés lors du contrôle technique."},
  {"id":"kq373","type":"knowledge","theme":"notions","question":"Un chargement empilé dépassant la hauteur du véhicule doit notamment tenir compte :","options":["Des hauteurs limites des ponts, tunnels et autres ouvrages sur l'itinéraire emprunté","De la limite de vitesse, abaissée de 20 km/h pour tout chargement dépassant la hauteur du véhicule","Du poids du chargement uniquement, la hauteur n'étant pas réglementée en dehors des autoroutes","Des seuls feux de gabarit, à ajouter à partir de 3 mètres de hauteur"],"correctIndex":0,"explanation":"Un chargement en hauteur impose de vérifier au préalable les hauteurs limitées signalées sur l'itinéraire (ponts, tunnels, passages sous voie), pour éviter tout accrochage dangereux."},
  {"id":"kq374","type":"knowledge","theme":"notions","question":"Concernant le transport de plusieurs enfants à l'arrière d'un véhicule à trois places assises, avec seulement deux sièges auto disponibles :","options":["Deux enfants peuvent partager un même siège auto si leur poids cumulé reste sous 36 kg","Chaque enfant doit avoir un dispositif de retenue adapté, faute de quoi il ne voyage pas","Le troisième enfant peut voyager sur les genoux d'un passager si la place est comptée","La ceinture suffit pour le troisième enfant s'il a plus de 6 ans, quelle que soit sa taille"],"correctIndex":1,"explanation":"Chaque enfant devant utiliser un dispositif de retenue adapté doit en disposer d'un individuellement ; il n'est pas possible de le transporter en toute légalité sans ce dispositif, même si une place assise existe."},
  {"id":"kq375","type":"knowledge","theme":"notions","question":"Un chien ou un animal domestique transporté doit, selon le code de la route, être installé de façon à :","options":["Être placé à l'avant, sur les genoux du passager, tant qu'il reste calme","Rester libre à l'arrière, s'il ne dépasse pas 10 kg","Ne pas gêner la conduite ni causer de danger aux passagers en cas de mouvement brusque","Porter une muselière en permanence, celle-ci étant imposée à tous les chiens"],"correctIndex":2,"explanation":"Le code de la route impose que les animaux transportés ne gênent pas la conduite et ne représentent pas un danger pour les occupants en cas de freinage ou de choc, d'où l'usage de dispositifs de sécurisation adaptés."},
  {"id":"kq376","type":"knowledge","theme":"notions","question":"Une remorque de camping (caravane) doit disposer, à l'arrière, d'un éclairage :","options":["Limité à des feux de position, les stops et clignotants restant ceux de la voiture tractrice","Complet, mais seulement lorsqu'elle dépasse 750 kg de PTAC, sinon réduit à des feux de position","Remplacé par un panneau triangulaire de présignalisation fixé à l'arrière de la caravane","Complet et fonctionnel (feux stop, clignotants, feux de position), identique à celui d'un véhicule"],"correctIndex":3,"explanation":"Une caravane doit être équipée d'un système d'éclairage complet et fonctionnel à l'arrière (feux de position, stop, clignotants, plaque d'immatriculation éclairée), comme tout véhicule circulant sur la route."},
  {"id":"kq377","type":"knowledge","theme":"notions","question":"Concernant l'installation d'un siège auto avec le système Isofix, ce dispositif permet notamment de :","options":["Fixer le siège de façon rigide aux points d'ancrage du véhicule, sans la ceinture","Remplacer le harnais intégré du siège par la ceinture de sécurité du véhicule","Désactiver automatiquement l'airbag frontal lorsque le siège est installé","Fixer le siège à l'avant sans désactiver l'airbag, le système l'amortissant"],"correctIndex":0,"explanation":"Le système Isofix permet de fixer le siège auto directement aux points d'ancrage standardisés du véhicule, offrant une installation plus rigide, stable et sécurisée qu'un maintien par la ceinture classique."},
  {"id":"kq378","type":"knowledge","theme":"securite_passagers","question":"Une ceinture de sécurité mal ajustée, trop lâche, en cas de choc :","options":["Offre une protection équivalente car les airbags compensent le jeu de la sangle","Réduit nettement la protection, le corps étant projeté avant d'être retenu","Améliore l'amorti du choc, la sangle laissant le corps avancer","N'a d'effet que sur le confort, la sangle se resserrant d'elle-même au choc"],"correctIndex":1,"explanation":"Une ceinture trop lâche laisse le corps se déplacer avant d'être retenu, ce qui réduit fortement son efficacité et peut aggraver les blessures en cas de choc."},
  {"id":"kq379","type":"knowledge","theme":"securite_passagers","question":"Faire passer la sangle diagonale de la ceinture de sécurité sous le bras plutôt que sur l'épaule est :","options":["Sans risque, dès lors que la boucle est bien verrouillée","Toléré quand la sangle gêne, tant que la ceinture ventrale reste bien serrée","Dangereux, la protection est très réduite en cas de choc","Sans conséquence si la ceinture reste bien tendue sur le bassin"],"correctIndex":2,"explanation":"Passer la sangle sous le bras au lieu de sur l'épaule réduit fortement son efficacité et peut causer des blessures graves (fractures de côtes, lésions internes) en cas de choc, la ceinture ne répartissant plus correctement les forces."},
  {"id":"kq380","type":"knowledge","theme":"securite_passagers","question":"Le prétensionneur de ceinture de sécurité, présent sur de nombreux véhicules récents, a pour fonction de :","options":["Desserrer la ceinture après le choc pour faciliter l'évacuation","Bloquer la sangle lors d'un freinage brusque ou d'une forte pente","Régler automatiquement la hauteur de la ceinture selon la taille","Retendre la ceinture dès le début d'un choc pour plaquer l'occupant au siège"],"correctIndex":3,"explanation":"Le prétensionneur retend instantanément la ceinture dès la détection d'un choc, réduisant le jeu de la sangle et plaquant l'occupant contre son siège pour limiter les déplacements dangereux."},
  {"id":"kq381","type":"knowledge","theme":"securite_passagers","question":"Les airbags latéraux ont pour rôle principal de protéger :","options":["Le thorax et/ou la tête des occupants en cas de choc latéral","Les jambes et le bassin des occupants en cas de choc arrière","Le visage du conducteur en cas de choc frontal violent","Les passagers arrière en cas de tonneau, mais pas les passagers avant"],"correctIndex":0,"explanation":"Les airbags latéraux (thorax, rideau) protègent principalement le buste et la tête des occupants lors d'un choc latéral, un type d'impact où la protection de la carrosserie est plus limitée."},
  {"id":"kq382","type":"knowledge","theme":"securite_passagers","question":"Un siège auto orienté face à la route, avant l'âge recommandé, augmente le risque :","options":["De fractures des jambes, surtout lors d'un choc arrière violent","De blessures à la tête et à la nuque en cas de choc frontal","De mal des transports sur les trajets de plus d'une heure et demie","De déformation du siège lors d'un tonneau ou d'un choc latéral"],"correctIndex":1,"explanation":"Chez le jeune enfant dont la nuque est encore fragile, un siège orienté face à la route trop tôt augmente le risque de lésions graves de la tête et de la nuque en cas de choc frontal, d'où la recommandation de garder le dos à la route le plus longtemps possible."},
  {"id":"kq383","type":"knowledge","theme":"securite_passagers","question":"Porter un casque de moto non homologué (sans marquage réglementaire) est :","options":["Toléré tant que le casque est intégral et en bon état","Considéré comme un simple défaut d'équipement, sans retrait de points","Considéré comme une absence de casque, sanctionnée comme telle","Toléré à condition de rouler à moins de 50 km/h"],"correctIndex":2,"explanation":"Un casque non homologué (sans marquage ECE ou équivalent) n'offre pas les garanties de protection requises et est assimilé légalement à une absence de casque, sanctionnée de la même façon."},
  {"id":"kq384","type":"knowledge","theme":"securite_passagers","question":"Le port de gants pour les deux-roues motorisés est obligatoire :","options":["Pour le conducteur, le passager en étant dispensé s'il est mineur","Pendant l'hiver, dès que la température passe sous 5 degrés","Une simple recommandation, sauf sur les motos de plus de 125 cm3","Pour le conducteur et le passager, avec des gants homologués (norme CE)"],"correctIndex":3,"explanation":"Depuis 2016, le port de gants homologués (norme CE) est obligatoire aussi bien pour le conducteur que pour tout passager d'un deux-roues motorisé."},
  {"id":"kq385","type":"knowledge","theme":"securite_passagers","question":"Un enfant transporté dans une remorque à vélo (attelée à un vélo) doit notamment :","options":["Porter un casque et être sanglé par un harnais dans la remorque","Être âgé d'au moins 8 ans et tenir la barre de la remorque","Porter un gilet réfléchissant, le casque restant facultatif","Être âgé de plus de 12 ans, la remorque étant réservée aux grands enfants"],"correctIndex":0,"explanation":"Un enfant transporté en remorque de vélo doit porter un casque adapté et être maintenu par un harnais de sécurité, la remorque devant elle-même répondre à des normes de sécurité."},
  {"id":"kq386","type":"knowledge","theme":"securite_passagers","question":"Le siège passager avant équipé d'un airbag frontal actif doit-il accueillir un enfant en siège dos à la route ?","options":["Oui, à condition de reculer le siège au maximum","Non, sauf si l'airbag frontal est désactivé","Non, sauf si le siège est fixé par un système Isofix","Oui, si le siège est maintenu par la ceinture trois points"],"correctIndex":1,"explanation":"Un siège dos à la route ne doit jamais être installé à l'avant avec un airbag frontal actif : celui-ci doit impérativement être désactivé pour éviter un risque mortel pour l'enfant en cas de déclenchement."},
  {"id":"kq387","type":"knowledge","theme":"securite_passagers","question":"Une personne de très petite taille (par exemple certaines personnes en situation de handicap) peut, si besoin, utiliser :","options":["Une ceinture ventrale seule, jugée suffisante pour sa morphologie","Un coussin d'airbag fixé sur la sangle, sans ceinture classique","Un guide-sangle ou un dispositif d'adaptation pour ajuster la ceinture","Une dérogation préfectorale pour rouler sans ceinture"],"correctIndex":2,"explanation":"Des dispositifs d'adaptation (guide-sangle, coussin réducteur) existent pour ajuster la ceinture aux morphologies particulières, garantissant une protection efficace sans dispense injustifiée."},
  {"id":"kq388","type":"knowledge","theme":"securite_passagers","question":"La dispense de port de la ceinture de sécurité pour raison médicale nécessite :","options":["Une autorisation écrite de la préfecture, valable un an renouvelable","Une attestation de l'assurance du conducteur, à présenter au contrôle","Une simple déclaration orale auprès des forces de l'ordre","Un certificat médical d'exemption délivré par un médecin"],"correctIndex":3,"explanation":"Une dispense de port de la ceinture pour raison médicale doit être justifiée par un certificat médical d'exemption délivré par un médecin, à présenter en cas de contrôle."},
  {"id":"kq389","type":"knowledge","theme":"securite_passagers","question":"En cas de tonneau ou de retournement du véhicule, le port de la ceinture de sécurité :","options":["Reste essentiel pour éviter l'éjection hors du véhicule","Peut piéger l'occupant, mieux vaut la déboucler avant","Devient facultatif si le véhicule est équipé d'airbags rideaux","Est moins efficace qu'en choc frontal, au point d'être déconseillé"],"correctIndex":0,"explanation":"En cas de tonneau, la ceinture de sécurité reste déterminante pour maintenir l'occupant à sa place et éviter une éjection du véhicule, situation particulièrement mortelle."},
  {"id":"kq390","type":"knowledge","theme":"securite_passagers","question":"Un enfant transporté dans un siège auto doit avoir les sangles du harnais réglées de façon à :","options":["Laisser environ la largeur de quatre doigts pour le confort","Être bien ajustées, sans laisser plus de deux doigts de jeu","Être serrées au maximum pour éviter tout mouvement de l'enfant","Être réglées une seule fois à l'achat, sans ajustement ultérieur"],"correctIndex":1,"explanation":"Le harnais du siège auto doit être ajusté correctement : ni trop lâche (protection réduite) ni trop serré, l'espace de deux doigts entre la sangle et l'enfant étant le repère communément recommandé."},
  {"id":"kq391","type":"knowledge","theme":"securite_passagers","question":"Porter des vêtements épais ou une doudoune volumineuse sous le harnais d'un siège auto peut :","options":["Améliorer l'amorti du choc grâce à l'épaisseur du vêtement","Être recommandé en hiver, à condition de bien serrer le harnais","Fausser le réglage du harnais et réduire son efficacité en cas de choc","Être sans effet, le harnais s'adaptant à l'épaisseur du tissu"],"correctIndex":2,"explanation":"Un vêtement épais se comprime lors d'un choc, laissant alors un jeu excessif dans le harnais qui devient moins efficace ; il est recommandé d'attacher l'enfant en vêtements fins puis de le couvrir ensuite d'une couverture par-dessus le harnais."},
  {"id":"kq392","type":"knowledge","theme":"securite_passagers","question":"La ceinture ventrale seule (sans sangle diagonale), présente sur certains sièges centraux arrière anciens, offre :","options":["Une protection comparable à celle des ceintures trois points","Une protection renforcée pour les enfants de moins de 10 ans","Une protection correcte, à condition de rouler sous 50 km/h","Une protection inférieure, surtout pour le haut du corps"],"correctIndex":3,"explanation":"La ceinture ventrale seule protège moins bien le haut du corps qu'une ceinture trois points, le buste pouvant être fortement projeté vers l'avant lors d'un choc frontal."},
  {"id":"kq393","type":"knowledge","theme":"securite_passagers","question":"Un airbag genoux, présent sur certains véhicules, vise à :","options":["Protéger les genoux et le bassin du conducteur ou du passager avant","Remplacer l'airbag frontal sur les petits véhicules urbains","Protéger les jambes des passagers arrière lors d'un choc latéral","Se déployer au plafond pour protéger la tête lors d'un tonneau"],"correctIndex":0,"explanation":"L'airbag genoux se déploie sous le tableau de bord pour limiter les mouvements des jambes et protéger les genoux et le bassin lors d'un choc frontal, en complément des autres airbags."},
  {"id":"kq394","type":"knowledge","theme":"securite_passagers","question":"Le voyant d'alerte de ceinture non bouclée, présent sur le tableau de bord, sert à :","options":["Indiquer que la ceinture est trop usée et doit être remplacée","Rappeler à l'occupant concerné d'attacher sa ceinture","Avertir d'un défaut du système d'airbags du véhicule","Signaler que le prétensionneur s'est déclenché lors d'un choc"],"correctIndex":1,"explanation":"Ce voyant, souvent accompagné d'un signal sonore, rappelle qu'une ceinture de sécurité n'est pas bouclée, incitant l'occupant concerné à l'attacher avant de circuler."},
  {"id":"kq395","type":"knowledge","theme":"securite_passagers","question":"Un siège auto endommagé lors d'un accident, même léger, doit en principe être :","options":["Contrôlé visuellement, puis réutilisé si aucune fissure n'apparaît","Réutilisé après changement de la housse et du harnais","Remplacé, sa structure pouvant être fragilisée sans dommage visible","Réutilisé pour un enfant plus petit, la charge étant moindre"],"correctIndex":2,"explanation":"Après un choc, même léger en apparence, la structure interne d'un siège auto peut être fragilisée sans dommage visible ; par précaution, il est recommandé de le remplacer."},
  {"id":"kq396","type":"knowledge","theme":"securite_passagers","question":"Concernant le port du casque à vélo pour les adultes en France :","options":["Obligatoire sur les routes hors agglomération, facultatif en ville","Obligatoire pour les cyclistes qui dépassent 25 km/h","Remplacé par le gilet rétro-réfléchissant hors agglomération","Pas obligatoire pour les adultes, mais fortement recommandé"],"correctIndex":3,"explanation":"Le port du casque à vélo n'est pas obligatoire pour les adultes en France, contrairement aux enfants de moins de 12 ans, mais il reste vivement recommandé pour limiter les traumatismes crâniens."},
  {"id":"kq397","type":"knowledge","theme":"securite_passagers","question":"Le système de retenue enfant dit « i-Size » se distingue des groupes classiques (0+, 1, 2, 3) car il se base principalement sur :","options":["La taille de l'enfant, avec une protection renforcée contre les chocs latéraux","Le poids de l'enfant, avec des critères identiques aux groupes classiques","L'âge de l'enfant, avec un maintien face à la route dès 9 mois","Le type de véhicule, avec des exigences propres à chaque constructeur"],"correctIndex":0,"explanation":"La norme i-Size classe les sièges selon la taille de l'enfant plutôt que son poids seul, avec des exigences renforcées, notamment en matière de protection contre les chocs latéraux et de maintien dos à la route plus prolongé."},
  {"id":"kq398","type":"knowledge","theme":"securite_passagers","question":"Les vitres teintées (film sur-teinté) posées sur les vitres avant d'un véhicule, au-delà des normes autorisées, sont :","options":["Tolérées tant que le film est posé par un professionnel agréé","Interdites lorsqu'elles réduisent la transparence sous le seuil légal","Admises si la teinte est uniforme et sans reflet métallisé","Réservées aux véhicules utilitaires, qui peuvent les teinter librement"],"correctIndex":1,"explanation":"Un sur-teintage excessif des vitres avant, réduisant la transparence en dessous du seuil légal, est interdit car il nuit à la visibilité du conducteur et complique l'identification des occupants lors des contrôles."},
  {"id":"kq399","type":"knowledge","theme":"securite_passagers","question":"Un enfant transporté à moto ou en scooter, en tant que passager, doit notamment :","options":["Avoir 12 ans révolus et porter casque et gants homologués","Être âgé de 14 ans et présenter l'accord écrit d'un parent","Pouvoir poser les pieds sur les repose-pieds et porter un équipement adapté","Être assis devant le conducteur, un adulte lui tenant les épaules"],"correctIndex":2,"explanation":"Un enfant passager de deux-roues motorisé doit pouvoir atteindre les repose-pieds et se tenir de façon stable, en plus de porter casque et équipements adaptés, pour limiter les risques en cas de manœuvre ou de choc."},
  {"id":"kq400","type":"knowledge","theme":"securite_passagers","question":"Les feux stop supplémentaires (troisième feu stop central, souvent situé sur la lunette arrière) ont pour objectif de :","options":["Éclairer l'arrière du véhicule en marche arrière","Indiquer que le frein de stationnement est serré à l'arrêt","Remplacer les feux stop classiques en cas d'ampoule grillée","Améliorer la visibilité du freinage pour les véhicules suivants"],"correctIndex":3,"explanation":"Ce troisième feu stop, plus haut placé, améliore la visibilité du freinage pour les conducteurs suivants, en particulier lorsque la vue sur les feux stop classiques est masquée par un véhicule intermédiaire."},
  {"id":"kq401","type":"knowledge","theme":"securite_passagers","question":"Concernant la position du siège conducteur, une distance trop faible entre le volant et le buste augmente le risque de :","options":["Blessures liées à l'airbag lors de son déploiement","Fatigue du dos au bout de plusieurs heures de conduite","Mauvaise visibilité des instruments du tableau de bord","Déclenchement intempestif de l'airbag au moindre freinage"],"correctIndex":0,"explanation":"Une distance trop faible entre le buste et le volant augmente le risque de blessures lors du déploiement de l'airbag, celui-ci se gonflant à très grande vitesse ; une distance d'environ 25 à 30 cm est généralement recommandée."},
  {"id":"kq402","type":"knowledge","theme":"securite_passagers","question":"En cas d'accident, les airbags latéraux et rideaux se déploient généralement :","options":["Lors d'un choc frontal violent, en même temps que l'airbag volant","En cas de choc latéral ou de risque de tonneau, selon les capteurs","Au démarrage du moteur, pour vérifier leur bon fonctionnement","Quand le conducteur appuie sur le bouton du tableau de bord"],"correctIndex":1,"explanation":"Les airbags latéraux et rideaux se déclenchent automatiquement en fonction des capteurs du véhicule, principalement lors d'un choc latéral ou d'un risque de retournement, en complément des airbags frontaux."},
  {"id":"kq403","type":"knowledge","theme":"securite_passagers","question":"Porter des écouteurs ou un casque audio en conduisant une voiture est :","options":["Autorisé tant que le conducteur roule en dessous de 50 km/h","Autorisé si un seul écouteur est porté, à volume modéré","Interdit, et sanctionné de 135 € d'amende et de 3 points","Autorisé la nuit, quand la circulation est moins dense"],"correctIndex":2,"explanation":"Le port à l'oreille de tout dispositif susceptible d'émettre du son (écouteurs, oreillette, casque audio) est interdit au volant (R412-6-1) : 135 € d'amende et retrait de 3 points. Seules les prothèses auditives sont exclues de cette interdiction."},
  {"id":"kq404","type":"knowledge","theme":"securite_passagers","question":"Une ceinture de sécurité endommagée (sangle effilochée, boucle défectueuse) doit être :","options":["Utilisée jusqu'au prochain contrôle technique, qui décidera du remplacement","Conservée tant que la boucle se verrouille correctement","Réservée aux places arrière jusqu'à son remplacement","Réparée ou remplacée sans attendre, car elle ne protège plus"],"correctIndex":3,"explanation":"Une ceinture endommagée peut céder ou mal fonctionner lors d'un choc : elle doit être réparée ou remplacée rapidement, ce point étant d'ailleurs vérifié lors du contrôle technique."},
  {"id":"kq405","type":"knowledge","theme":"securite_passagers","question":"En France, le port du casque est-il obligatoire pour les enfants transportés en vélo cargo ou biporteur ?","options":["Oui, comme pour tout enfant de moins de 12 ans à vélo, passager compris","Non, il n'est exigé que pour l'enfant qui conduit lui-même le vélo","Oui, mais à partir de 6 ans, âge où il peut tenir seul sur le siège","Non, la ceinture du siège enfant du vélo cargo remplace le casque"],"correctIndex":0,"explanation":"Le port du casque s'applique à tout enfant de moins de 12 ans circulant à vélo, qu'il en soit le conducteur ou simplement transporté comme passager, y compris dans un vélo cargo ou biporteur."},
  {"id":"kq406","type":"knowledge","theme":"securite_passagers","question":"Un siège auto installé face à la route trop tôt, avant que l'enfant n'ait la maturité osseuse suffisante, expose principalement à un risque accru en cas de :","options":["Choc arrière, la nuque étant projetée violemment contre le dossier du siège","Choc frontal, le plus fréquent et le plus violent statistiquement","Choc latéral, la tête étant moins bien maintenue par la coque du siège","Tonneau, le siège pouvant se détacher de ses fixations Isofix"],"correctIndex":1,"explanation":"Le choc frontal étant le type d'accident le plus fréquent et souvent le plus violent, un enfant trop tôt installé face à la route y est particulièrement exposé, d'où la recommandation de rester dos à la route le plus longtemps possible."},
  {"id":"kq407","type":"knowledge","theme":"securite_passagers","question":"Les rétroviseurs extérieurs, en plus du rétroviseur intérieur, doivent être réglés de façon à :","options":["Montrer largement les flancs du véhicule afin de mieux se positionner dans la voie","Être inclinés vers le sol pour surveiller les roues en permanence","Réduire les angles morts, avec un léger recouvrement du rétroviseur intérieur","Être réglés une fois pour toutes par un professionnel agréé"],"correctIndex":2,"explanation":"Un bon réglage des rétroviseurs extérieurs, complétant le rétroviseur intérieur avec une légère zone de recouvrement, permet de réduire au maximum les angles morts dangereux lors des changements de direction."},
  {"id":"kq408","type":"knowledge","theme":"securite_passagers","question":"Concernant un enfant transporté en trottinette électrique en tant que passager (debout devant ou derrière le conducteur), cette pratique est :","options":["Autorisée à condition que l'enfant porte un casque et reste debout devant le conducteur","Tolérée en agglomération, l'enfant tenant le guidon avec le conducteur","Autorisée sur piste cyclable, où la vitesse est limitée à 25 km/h","Interdite, une trottinette électrique n'étant prévue que pour une personne"],"correctIndex":3,"explanation":"Une trottinette électrique classique n'est conçue et homologuée que pour un seul utilisateur : y transporter un enfant en plus est interdit et particulièrement dangereux, l'engin devenant instable."},
  {"id":"kq409","type":"knowledge","theme":"equipements","question":"Le témoin lumineux orange en forme de moteur (« check engine ») allumé au tableau de bord signale :","options":["Un dysfonctionnement du moteur ou de la dépollution à faire vérifier","Une pression insuffisante dans l'un des pneus, à corriger au plus vite","Un simple rappel d'entretien périodique, sans lien avec un défaut du moteur","Un niveau de carburant bas, à compléter dans les cinquante prochains kilomètres"],"correctIndex":0,"explanation":"Ce témoin signale un dysfonctionnement détecté par l'électronique du moteur ou du système antipollution ; il est recommandé de faire vérifier le véhicule rapidement, sans attendre une panne plus grave."},
  {"id":"kq410","type":"knowledge","theme":"equipements","question":"Le témoin rouge en forme de burette d'huile allumé pendant la conduite indique généralement :","options":["Une surchauffe du liquide de refroidissement, à surveiller en roulant doucement","Une pression d'huile insuffisante, nécessitant l'arrêt immédiat du moteur","Une batterie qui ne se recharge plus, sans danger pour le moteur","Un simple rappel de vidange à prévoir lors de la prochaine révision"],"correctIndex":1,"explanation":"Un témoin rouge de pression d'huile signale un problème grave et immédiat : il faut arrêter le moteur au plus vite pour éviter une casse mécanique majeure."},
  {"id":"kq411","type":"knowledge","theme":"equipements","question":"Les phares antibrouillard avant doivent être utilisés :","options":["Par temps clair, sur les routes étroites et sinueuses de montagne","De nuit sur route non éclairée, en complément des feux de route","En cas de conditions de visibilité réduite (brouillard, forte pluie, neige)","En agglomération, pour être mieux vu des piétons à l'approche"],"correctIndex":2,"explanation":"Les feux antibrouillard avant, positionnés bas, servent à améliorer l'éclairage de la chaussée en cas de conditions de visibilité réduite (brouillard, fortes pluies, neige), et non en usage permanent de nuit."},
  {"id":"kq412","type":"knowledge","theme":"equipements","question":"L'usage abusif des feux de route (pleins phares) en présence d'un véhicule venant en face est sanctionné car il :","options":["Fait perdre de la puissance au moteur et augmente la consommation","Est réservé aux routes à chaussées séparées, comme les autoroutes et voies rapides","Fatigue la batterie et réduit la durée de vie des ampoules","Peut éblouir et donc mettre en danger le conducteur venant en face"],"correctIndex":3,"explanation":"Les feux de route, très puissants, doivent être basculés en feux de croisement dès qu'un véhicule arrive en face ou est suivi de près, pour ne pas éblouir et provoquer un accident."},
  {"id":"kq413","type":"knowledge","theme":"equipements","question":"Un rétroviseur cassé ou manquant sur un véhicule constitue :","options":["Une infraction sanctionnable, car la visibilité vers l'arrière est réduite","Un simple défaut esthétique, sans conséquence lors d'un contrôle routier ou technique","Un motif de retrait automatique de plusieurs points du permis, dès le contrôle","Une situation tolérée pendant un mois après la casse, le temps de la réparation"],"correctIndex":0,"explanation":"Un rétroviseur manquant ou cassé réduit la visibilité du conducteur sur son environnement et constitue une infraction sanctionnable, en plus d'être un point de contrôle technique."},
  {"id":"kq414","type":"knowledge","theme":"equipements","question":"Le liquide de frein d'un véhicule doit être :","options":["Complété dès que la pédale devient molle, sans remplacement périodique","Contrôlé régulièrement et remplacé selon les préconisations du constructeur","Remplacé tous les ans, quel que soit le kilométrage du véhicule","Vidangé en même temps que l'huile moteur à chaque révision annuelle"],"correctIndex":1,"explanation":"Le liquide de frein absorbe l'humidité avec le temps, ce qui réduit son efficacité ; il doit être contrôlé régulièrement et changé selon les recommandations du constructeur, faute de quoi le freinage peut être compromis."},
  {"id":"kq415","type":"knowledge","theme":"equipements","question":"Le témoin ABS allumé en permanence au tableau de bord signifie :","options":["Que l'ABS est activé et que les roues risquent de se bloquer","Que les freins classiques sont hors service et le véhicule à immobiliser","Qu'une anomalie a été détectée sur le système antiblocage, à faire vérifier","Que le niveau de liquide de frein est bas, sans lien avec l'ABS"],"correctIndex":2,"explanation":"Un témoin ABS allumé en continu (hors phase de démarrage) signale une anomalie du système antiblocage, qui doit être diagnostiquée rapidement, le freinage classique restant néanmoins opérationnel."},
  {"id":"kq416","type":"knowledge","theme":"equipements","question":"Les pneus doivent être remplacés lorsque :","options":["Ils atteignent cinq ans d'âge, quel que soit leur état d'usure apparent","Leur sculpture passe sous 3 mm, seuil à partir duquel le remplacement est exigé","Ils ont parcouru 20 000 km, quel que soit l'état de leur bande de roulement","Leur sculpture atteint ou approche 1,6 mm, ou qu'ils sont endommagés"],"correctIndex":3,"explanation":"Un pneu doit être remplacé dès que sa profondeur de sculpture approche le seuil légal de 1,6 mm, ou en cas de dommage visible (hernie, coupure), indépendamment de son âge seul."},
  {"id":"kq417","type":"knowledge","theme":"equipements","question":"L'utilisation de pneus différents à l'avant et à l'arrière (marque, dimension, type) est :","options":["Réglementée : certains écarts sont interdits pour garder la stabilité du véhicule","Interdite sans exception, y compris avec une roue de secours","Libre dès lors que les pneus ont la même profondeur de sculpture","Autorisée pour les véhicules à traction avant, qui répartissent mieux la charge"],"correctIndex":0,"explanation":"Monter des pneus de dimensions ou de types très différents entre l'avant et l'arrière peut déstabiliser le comportement du véhicule ; la réglementation encadre strictement ces écarts pour garantir la sécurité."},
  {"id":"kq418","type":"knowledge","theme":"equipements","question":"Les essuie-glaces arrière sont particulièrement utiles sur :","options":["Les berlines tricorps, dont le coffre est plus haut que la lunette arrière","Les véhicules à hayon (break, SUV, monospace), où la lunette reçoit plus de projections","Les véhicules sans lunette arrière chauffante, pour compenser le givre","Les cabriolets, dont la capote textile se couvre davantage de salissures"],"correctIndex":1,"explanation":"Sur les véhicules à hayon, la lunette arrière est particulièrement exposée aux projections de boue ou d'eau ; l'essuie-glace arrière y est donc très utile pour maintenir une bonne visibilité."},
  {"id":"kq419","type":"knowledge","theme":"equipements","question":"Une batterie de véhicule déchargée en hiver s'explique notamment par :","options":["Une surcharge produite par l'alternateur, qui s'aggrave quand la température chute","Une évaporation de l'électrolyte, qui touche surtout les batteries en hiver","Une baisse de capacité au froid, alors que la demande électrique augmente","Un phénomène propre aux véhicules électriques, dont la batterie gèle plus vite"],"correctIndex":2,"explanation":"Le froid réduit la capacité chimique d'une batterie tout en augmentant les besoins électriques (chauffage, dégivrage, éclairage), ce qui explique la fréquence des pannes de batterie en hiver."},
  {"id":"kq420","type":"knowledge","theme":"equipements","question":"Concernant les feux de jour (DRL) présents sur de nombreux véhicules récents, ils permettent notamment :","options":["D'éclairer la route aussi bien que des feux de croisement, de nuit comme de jour","De réduire la consommation de carburant du moteur en économisant l'alternateur","D'éviter d'allumer les feux de position dans les tunnels, en cas de brouillard ou de forte pluie","D'être mieux vu de jour, sans remplacer les feux de croisement obligatoires de nuit"],"correctIndex":3,"explanation":"Les feux de jour améliorent la visibilité du véhicule en journée, mais ne remplacent jamais les feux de croisement obligatoires de nuit ou par visibilité insuffisante, ces derniers éclairant bien plus la route."},
  {"id":"kq421","type":"knowledge","theme":"equipements","question":"Une roue de secours dite « galette » (roue de dépannage temporaire) impose généralement :","options":["De limiter sa vitesse (souvent à 80 km/h) et de la remplacer rapidement par un pneu standard","De la remplacer au plus tard après 1 000 km, sans limitation de vitesse","De rouler à 110 km/h au maximum, et de la conserver jusqu'au contrôle technique","De la monter à l'avant et de ne l'utiliser que sur route sèche, sans limite de durée"],"correctIndex":0,"explanation":"Une roue de secours temporaire (galette) impose une limitation de vitesse, généralement autour de 80 km/h, et doit être remplacée par un pneu standard dès que possible, n'étant pas conçue pour un usage prolongé."},
  {"id":"kq422","type":"knowledge","theme":"equipements","question":"Le contrôle du niveau de liquide de refroidissement est important car :","options":["Un niveau trop bas fait geler l'huile moteur et bloque le démarrage","Un niveau trop bas peut entraîner une surchauffe et de graves dégâts moteur","Il sert à lubrifier les pièces en mouvement, au même titre que l'huile moteur","Un niveau trop haut provoque l'usure des plaquettes de frein"],"correctIndex":1,"explanation":"Le liquide de refroidissement évite la surchauffe du moteur ; un niveau insuffisant peut entraîner une surchauffe et des dommages mécaniques graves, parfois irréversibles."},
  {"id":"kq423","type":"knowledge","theme":"equipements","question":"Les catadioptres (réflecteurs) placés à l'arrière d'un véhicule servent à :","options":["Éclairer la plaque d'immatriculation arrière quand les feux de position sont allumés","Signaler aux autres usagers que le véhicule freine, en renforçant les feux stop","Réfléchir la lumière des phares des véhicules suiveurs, même feux éteints","Indiquer la largeur du véhicule en s'allumant avec les feux de position, de nuit"],"correctIndex":2,"explanation":"Les catadioptres ne produisent pas de lumière eux-mêmes mais réfléchissent celle des phares d'un véhicule suiveur, rendant le véhicule visible même feux éteints, notamment en cas de panne électrique."},
  {"id":"kq424","type":"knowledge","theme":"equipements","question":"Les plaquettes de frein usées se manifestent souvent par :","options":["Une odeur d'huile brûlée dès les premiers freinages, signe d'usure avancée","Une direction qui tire à gauche sur route sèche, quelle que soit la vitesse","Un voyant de pression des pneus allumé après chaque freinage appuyé","Un grincement ou un crissement lors du freinage, signe d'usure à vérifier rapidement"],"correctIndex":3,"explanation":"Des plaquettes de frein usées produisent souvent un grincement ou un crissement caractéristique lors du freinage : un signal à ne pas ignorer pour éviter une perte d'efficacité du freinage, voire une panne des freins."},
  {"id":"kq425","type":"knowledge","theme":"equipements","question":"L'éthylotest anti-démarrage (EAD), lorsqu'il est imposé, empêche le démarrage du véhicule si :","options":["Le taux d'alcool détecté dépasse le seuil autorisé configuré sur l'appareil","Le conducteur a déjà été condamné pour conduite en état d'ivresse dans les cinq ans","Le conducteur a bu de l'alcool dans les douze heures, même sous le seuil autorisé","Le contrôle technique du véhicule date de plus de deux ans"],"correctIndex":0,"explanation":"L'éthylotest anti-démarrage bloque le démarrage du véhicule tant que le conducteur n'a pas soufflé dans l'appareil et que son taux d'alcool ne dépasse pas le seuil configuré."},
  {"id":"kq426","type":"knowledge","theme":"equipements","question":"Sur autoroute, en cas de crevaison, il est déconseillé de :","options":["Se garer le plus à droite possible sur la bande d'arrêt d'urgence, puis couper le moteur","Continuer à rouler à faible vitesse sur une longue distance pour atteindre la sortie","Allumer ses feux de détresse dès que la crevaison est ressentie, avant de se ranger","Enfiler le gilet de haute visibilité avant de descendre, puis se placer derrière la glissière"],"correctIndex":1,"explanation":"Rouler longtemps sur un pneu crevé, même lentement, endommage la jante et peut faire perdre le contrôle du véhicule : il faut s'arrêter dès que possible sur la bande d'arrêt d'urgence."},
  {"id":"kq427","type":"knowledge","theme":"equipements","question":"Les jantes ou pneus visiblement endommagés (déformation, hernie, fissure) doivent :","options":["Être surveillés lors du prochain entretien, sans urgence particulière","Être colmatés avec un mastic spécial tant que le pneu ne fuit pas","Être remplacés rapidement, le risque d'éclatement étant important","Être conservés tant que le pneu tient l'air, quel que soit son aspect"],"correctIndex":2,"explanation":"Une hernie, une fissure ou une déformation de jante ou de pneu augmente fortement le risque d'éclatement en roulant : un remplacement rapide s'impose, sans attendre un signe de fuite."},
  {"id":"kq428","type":"knowledge","theme":"equipements","question":"Concernant le port de la ceinture, les prétensionneurs pyrotechniques doivent-ils être remplacés après un déclenchement ?","options":["Non, ils se réarment automatiquement après quelques secondes","Cela dépend de la marque du véhicule et de l'âge de la ceinture","Non, seul l'airbag doit être changé, la ceinture reste utilisable","Oui, un prétensionneur pyrotechnique déclenché doit être remplacé, comme un airbag"],"correctIndex":3,"explanation":"Comme les airbags, les prétensionneurs pyrotechniques utilisent une charge à usage unique : une fois déclenchés lors d'un choc, ils doivent être remplacés pour rester efficaces en cas de nouvel accident."},
  {"id":"kq429","type":"knowledge","theme":"equipements","question":"Les phares xénon ou LED mal réglés, éblouissant les autres usagers, constituent :","options":["Un danger et une infraction : le réglage doit limiter l'éblouissement","Une simple gêne, les technologies xénon et LED étant dispensées de réglage","Un avantage pour le conducteur, qui voit mieux, sans conséquence pour autrui","Une tolérance admise tant que les phares ne sont ni teintés ni modifiés"],"correctIndex":0,"explanation":"Un mauvais réglage des projecteurs, quelle que soit leur technologie, peut éblouir dangereusement les autres usagers : le réglage correct des feux est un point vérifié lors du contrôle technique."},
  {"id":"kq430","type":"knowledge","theme":"equipements","question":"Le port de chaînes à neige nécessite en général de :","options":["Rouler à 90 km/h au maximum, comme sur route normale, et les garder jusqu'à la fin de l'hiver","Rouler lentement (souvent 50 km/h au plus) et les retirer dès que la route est dégagée","Ne pas dépasser 10 km/h, quelle que soit la route empruntée","Les poser sur les quatre roues et les laisser en place jusqu'au printemps"],"correctIndex":1,"explanation":"Les chaînes à neige imposent une vitesse réduite (souvent limitée à environ 50 km/h) et doivent être retirées dès que la route redevient praticable sans elles, pour ne pas endommager la chaussée ni les pneus."},
  {"id":"kq431","type":"knowledge","theme":"equipements","question":"Un pare-brise fissuré, même légèrement, dans le champ de vision du conducteur :","options":["Peut être ignoré tant que la fissure reste inférieure à dix centimètres de longueur","Se règle en le laissant tel quel, le verre feuilleté empêchant la fissure de s'étendre","Doit être réparé ou remplacé rapidement : elle peut gêner la vue et fragiliser le pare-brise","Est toléré au contrôle technique, à condition de le signaler à son assureur"],"correctIndex":2,"explanation":"Une fissure dans le champ de vision du conducteur gêne la perception des dangers et peut s'agrandir, fragilisant la structure du pare-brise qui participe à la rigidité de l'habitacle ; une réparation rapide est recommandée."},
  {"id":"kq432","type":"knowledge","theme":"equipements","question":"L'entretien de la courroie de distribution d'un moteur, selon les préconisations du constructeur, est important car :","options":["Sa rupture provoque un simple calage, sans conséquence sur le moteur","Elle se change à chaque vidange, quel que soit le moteur","Elle ne se change qu'après la panne, le moteur n'étant pas affecté","Sa rupture peut endommager gravement, voire détruire le moteur"],"correctIndex":3,"explanation":"La rupture d'une courroie de distribution usée peut provoquer une casse moteur importante et coûteuse ; son remplacement selon les préconisations du constructeur (kilométrage ou durée) est essentiel."},
  {"id":"kq433","type":"knowledge","theme":"equipements","question":"Concernant les feux de recul (marche arrière), ils s'allument automatiquement pour :","options":["Éclairer l'arrière et avertir les usagers lors d'une manœuvre de recul","Avertir les véhicules suiveurs que le conducteur s'apprête à se ranger sur le bas-côté","Signaler un ralentissement brutal en renforçant l'éclairage des feux stop arrière","Remplacer les feux de position lorsque le véhicule est à l'arrêt, moteur tournant"],"correctIndex":0,"explanation":"Les feux de recul, blancs, s'allument automatiquement en marche arrière pour éclairer la zone et avertir les autres usagers (piétons, véhicules) de la manœuvre en cours."},
  {"id":"kq434","type":"knowledge","theme":"equipements","question":"Une plaque d'immatriculation non éclairée de nuit constitue :","options":["Une simple tolérance, l'éclairage de la plaque n'étant exigé qu'en agglomération","Une infraction, l'éclairage de la plaque arrière étant obligatoire de nuit","Une infraction dès lors que la plaque n'est pas lisible à 50 mètres de jour","Un défaut relevé au contrôle technique, mais non sanctionné lors d'un contrôle routier"],"correctIndex":1,"explanation":"La plaque d'immatriculation arrière doit être éclairée dès que les feux de position ou de croisement sont allumés, afin de rester lisible de nuit ; son absence d'éclairage est une infraction."},
  {"id":"kq435","type":"knowledge","theme":"equipements","question":"Les vitres et le pare-brise doivent être dégivrés entièrement avant de circuler, car conduire avec une vision partielle (un simple « trou » dégivré) est :","options":["Toléré si l'on roule à vitesse réduite en ville","Sans risque dès que le trou dégivré est face au conducteur","Dangereux et sanctionnable, la visibilité devant être complète","Autorisé si le trajet dure moins de dix minutes"],"correctIndex":2,"explanation":"Conduire avec un pare-brise partiellement dégivré réduit fortement le champ de vision et constitue une infraction, en plus d'un risque important pour la sécurité."},
  {"id":"kq437","type":"knowledge","theme":"equipements","question":"La date de péremption ou de fabrication d'un pneu (indiquée par un code sur le flanc) est utile car :","options":["Un pneu vieillit et perd en performance même s'il est peu usé","Elle indique le pays de fabrication de la gomme","Elle permet de calculer la date limite légale d'utilisation de huit ans","Elle sert à la garantie du fabricant, sans lien avec l'état du pneu"],"correctIndex":0,"explanation":"Le caoutchouc d'un pneu se durcit et perd en performance avec le temps, même s'il est peu usé en surface : le code DOT sur le flanc indique la semaine et l'année de fabrication, une information utile pour évaluer son vieillissement."},
  {"id":"kq438","type":"knowledge","theme":"equipements","question":"Un klaxon (avertisseur sonore) défectueux constitue, en cas de contrôle :","options":["Une simple recommandation d'entretien, sans effet lors du contrôle technique","Une infraction, cet équipement de sécurité devant être fonctionnel","Une infraction qui ne concerne que les motos et les poids lourds","Un défaut toléré lorsque le véhicule circule en agglomération"],"correctIndex":1,"explanation":"L'avertisseur sonore est un équipement de sécurité obligatoire et doit être fonctionnel ; son absence de fonctionnement constitue une infraction, notamment vérifiable lors d'un contrôle technique ou routier."},
  {"id":"kq439","type":"knowledge","theme":"equipements","question":"Une remorque ou une caravane doit disposer de son propre système de freinage lorsque :","options":["Son PTAC dépasse 500 kg, quel que soit le véhicule tracteur utilisé","Elle roule sur autoroute ou sur voie rapide, quel que soit son poids","Son PTAC dépasse un certain seuil (généralement 750 kg)","Son poids total roulant dépasse celui du véhicule tracteur à vide"],"correctIndex":2,"explanation":"Au-delà d'un certain seuil de PTAC (généralement 750 kg), une remorque doit être équipée de son propre système de freinage, se déclenchant automatiquement avec celui du véhicule tracteur."},
  {"id":"kq440","type":"knowledge","theme":"secours","question":"Face à un accident, la deuxième étape du sigle PAS, « Alerter », consiste à :","options":["Déplacer immédiatement les victimes vers un endroit plus sûr hors de la chaussée","Prendre des photos de la scène pour l'assurance avant l'arrivée des secours","Attendre qu'un autre témoin s'en charge pour éviter les appels en double","Prévenir les secours en composant le bon numéro et en donnant des informations précises"],"correctIndex":3,"explanation":"Alerter consiste à prévenir rapidement les services de secours appropriés (15, 17, 18 ou 112) en fournissant une localisation précise et les informations essentielles sur la situation."},
  {"id":"kq441","type":"knowledge","theme":"secours","question":"La troisième étape du sigle PAS, « Secourir », signifie :","options":["Effectuer les gestes de premiers secours à sa portée, dans la limite de ses compétences","Pratiquer systématiquement un massage cardiaque sur toute victime, même consciente, avant l'arrivée des secours","Transporter soi-même la victime à l'hôpital le plus proche en voiture pour gagner du temps","Donner à boire à la victime pour la réconforter et surveiller sa réaction pendant l'attente"],"correctIndex":0,"explanation":"Secourir signifie apporter les gestes de premiers secours adaptés à la situation et à ses compétences (arrêt d'une hémorragie, PLS...) en attendant l'arrivée des secours professionnels, sans se substituer à eux."},
  {"id":"kq442","type":"knowledge","theme":"secours","question":"Avant d'intervenir auprès d'une victime, il faut d'abord vérifier :","options":["L'état de conscience de la victime avant de lui adresser la parole","Qu'aucun danger persistant ne menace le sauveteur lui-même","Que d'autres témoins sont présents pour partager les gestes à effectuer","Que les véhicules impliqués sont bien assurés et leurs papiers à jour"],"correctIndex":1,"explanation":"La première règle de secourisme est de ne jamais se mettre soi-même en danger : il faut s'assurer que la zone est sécurisée avant d'approcher la victime."},
  {"id":"kq443","type":"knowledge","theme":"secours","question":"Pour vérifier si une victime est consciente, le geste habituel consiste à :","options":["La secouer vigoureusement par les épaules pour provoquer une réaction","Lui pincer le bras pour observer si elle réagit à la douleur","Lui parler et lui demander de serrer la main ou d'ouvrir les yeux","Vérifier d'abord sa respiration sans lui adresser la parole ni la toucher"],"correctIndex":2,"explanation":"On évalue la conscience en parlant à la victime et en lui demandant de réagir (serrer la main, ouvrir les yeux), sans la secouer, ce qui pourrait aggraver une éventuelle blessure."},
  {"id":"kq444","type":"knowledge","theme":"secours","question":"Une victime inconsciente qui ne respire pas nécessite immédiatement :","options":["La position latérale de sécurité, en attendant l'arrivée des secours","Une série de claques dans le dos pour relancer la respiration","Une surveillance de la respiration pendant dix minutes avant d'agir","Un massage cardiaque, idéalement associé à l'usage d'un défibrillateur si disponible"],"correctIndex":3,"explanation":"Face à une victime inconsciente qui ne respire pas (arrêt cardio-respiratoire), il faut débuter immédiatement un massage cardiaque et utiliser un défibrillateur automatisé externe si un est disponible à proximité."},
  {"id":"kq445","type":"knowledge","theme":"secours","question":"Un défibrillateur automatisé externe (DAE) accessible au public peut être utilisé par :","options":["Toute personne, même sans formation médicale, l'appareil guidant l'utilisateur","Les professionnels de santé et les secouristes titulaires du PSC1 à jour","Les pompiers et les ambulanciers, après autorisation du médecin du SAMU","Toute personne majeure ayant suivi une formation spécifique de moins de deux ans"],"correctIndex":0,"explanation":"Un DAE est conçu pour être utilisé par toute personne, même sans formation médicale : l'appareil guide vocalement chaque étape et n'administre un choc que si celui-ci est réellement nécessaire."},
  {"id":"kq446","type":"knowledge","theme":"secours","question":"Concernant l'utilisation d'un extincteur en cas de départ de feu dans un véhicule, il faut avant tout :","options":["S'approcher au plus près des flammes pour que le jet soit efficace","Évaluer le danger : ne l'utiliser que si le feu est maîtrisable, avec une voie de repli","L'utiliser sur un feu éteint pour prévenir toute reprise éventuelle","L'utiliser sans couper le contact, pour garder les feux de détresse"],"correctIndex":1,"explanation":"Un extincteur ne doit être utilisé que sur un début d'incendie encore maîtrisable, en gardant toujours une possibilité de repli ; si le feu est trop développé, il vaut mieux s'éloigner et alerter les secours."},
  {"id":"kq447","type":"knowledge","theme":"secours","question":"En cas de choc électrique sur une personne à proximité d'un véhicule électrique accidenté, il faut avant tout :","options":["La saisir par les vêtements ou les bras pour la dégager rapidement de la zone dangereuse","L'arroser abondamment d'eau pour refroidir la carrosserie et la victime avant les secours","Ne pas la toucher directement, couper si possible l'alimentation et alerter les secours","Lui prodiguer un massage cardiaque sans attendre, même au contact direct du véhicule"],"correctIndex":2,"explanation":"Face à un risque électrique, il ne faut jamais toucher directement la victime tant que le courant n'est pas coupé ; il vaut mieux alerter immédiatement les secours formés à ce type d'intervention spécifique."},
  {"id":"kq448","type":"knowledge","theme":"secours","question":"Une victime en état de choc (pâleur, sueurs froides, pouls rapide) après un accident doit être :","options":["Mise debout rapidement pour vérifier que sa tension revient à la normale","Laissée seule au calme, à l'abri des regards, pour se reposer avant l'arrivée des secours","Encouragée à marcher quelques pas pour évacuer le stress de l'accident","Allongée si possible, rassurée, couverte, et surveillée en attendant les secours"],"correctIndex":3,"explanation":"Une victime en état de choc doit être allongée si son état le permet, rassurée, couverte pour éviter le refroidissement, et surveillée attentivement jusqu'à l'arrivée des secours."},
  {"id":"kq449","type":"knowledge","theme":"secours","question":"Pour une brûlure légère consécutive à un accident, le premier geste recommandé est :","options":["Refroidir la zone à l'eau tempérée pendant plusieurs minutes","Appliquer de la glace directement sur la peau pour calmer la douleur","Appliquer une pommade grasse ou du beurre sur la zone brûlée","Percer les cloques avec une aiguille stérilisée pour évacuer le liquide"],"correctIndex":0,"explanation":"Le refroidissement d'une brûlure à l'eau tempérée (ni glacée ni chaude) pendant plusieurs minutes limite l'approfondissement de la lésion ; il ne faut ni glace directe, ni pommade, ni percer les cloques."},
  {"id":"kq450","type":"knowledge","theme":"secours","question":"Face à une fracture apparente d'un membre chez une victime consciente, il faut :","options":["Tenter de remettre l'os en place doucement pour soulager la douleur","Ne pas mobiliser le membre et attendre les secours qui l'immobiliseront correctement","Masser la zone pour détendre les muscles et diminuer l'œdème avant les secours","Faire marcher la victime quelques pas pour tester la gravité de la blessure"],"correctIndex":1,"explanation":"Face à une fracture suspectée, il ne faut surtout pas mobiliser le membre ni tenter de le remettre en place : seuls les secours disposent du matériel et des compétences pour une immobilisation sans risque supplémentaire."},
  {"id":"kq451","type":"knowledge","theme":"secours","question":"Le rôle des « témoins » d'un accident, en dehors des secouristes, peut inclure :","options":["Ne pas s'arrêter pour laisser les professionnels agir, la loi réservant ces gestes aux secouristes","Filmer la scène avant d'agir afin de fournir des preuves à la gendarmerie","Baliser les lieux, alerter les secours et rassurer les victimes, selon leurs compétences","Intervenir sur les victimes après accord d'un médecin ou d'un policier"],"correctIndex":2,"explanation":"Tout témoin peut légitimement contribuer à protéger les lieux, alerter les secours et rassurer les victimes, sans avoir besoin d'une qualification médicale pour ces gestes de base."},
  {"id":"kq452","type":"knowledge","theme":"secours","question":"Ne pas porter secours à une personne en danger, alors qu'on aurait pu le faire sans risque pour soi-même, constitue en droit français :","options":["Une faute civile qui n'ouvre droit qu'à des dommages et intérêts","Une contravention de 4e classe, sans inscription au casier judiciaire","Un manquement moral sans conséquence pénale lorsque la victime survit","Le délit de non-assistance à personne en danger, sanctionné pénalement"],"correctIndex":3,"explanation":"La non-assistance à personne en danger est un délit pénal en France, sanctionné lorsque l'on s'abstient volontairement de porter secours ou de le faire porter alors qu'on le pouvait sans risque pour soi ou pour des tiers."},
  {"id":"kq453","type":"knowledge","theme":"secours","question":"Un extincteur de type ABC convient généralement pour éteindre :","options":["Une large variété de feux : solides, liquides et gaz courants","Les feux de métaux (magnésium, sodium) et de produits chimiques réactifs","Les feux de forêt et de broussailles de grande ampleur","Les feux de liquides inflammables comme l'essence, mais pas ceux de solides"],"correctIndex":0,"explanation":"Un extincteur polyvalent de type ABC est conçu pour être efficace sur les principaux types de feux courants (solides, liquides, gaz), ce qui en fait un bon choix général, notamment pour un véhicule."},
  {"id":"kq454","type":"knowledge","theme":"secours","question":"Face à une personne inconsciente qui respire, dont on soupçonne un traumatisme du dos ou de la nuque, il faut :","options":["La laisser sur le dos sans la bouger, en surveillant seulement sa respiration","La mettre en PLS en gardant la tête, le cou et le tronc alignés, et alerter les secours","La redresser en position assise pour faciliter sa respiration","La faire marcher pour vérifier ses réflexes et la sensibilité des jambes"],"correctIndex":1,"explanation":"La liberté des voies aériennes est prioritaire : une victime inconsciente qui respire est placée en PLS, avec le plus de précautions possible pour garder la tête, le cou et le tronc alignés, puis les secours sont alertés et la respiration surveillée."},
  {"id":"kq455","type":"knowledge","theme":"secours","question":"Concernant une trousse de premiers secours dans un véhicule, bien qu'elle ne soit pas légalement obligatoire pour un véhicule particulier, elle est utile pour :","options":["Se dispenser d'appeler les secours professionnels pour les blessures légères","Justifier d'une assistance aux victimes lors d'un contrôle de gendarmerie","Effectuer les premiers gestes simples (pansement, désinfection) en attendant les secours","Remplir l'obligation légale de transporter une trousse, passible d'une amende en cas d'oubli"],"correctIndex":2,"explanation":"Bien que non obligatoire pour une voiture particulière, une trousse de premiers secours permet de traiter de petites blessures ou d'attendre les secours dans de meilleures conditions en cas d'accident léger."},
  {"id":"kq456","type":"knowledge","theme":"secours","question":"Lorsqu'on alerte les secours par téléphone, il ne faut jamais raccrocher :","options":["Après avoir donné son nom et son numéro de téléphone à l'opérateur","Dès que l'on a donné l'adresse exacte du lieu de l'accident","Après dix secondes de conversation, durée maximale d'un appel d'urgence","Tant que l'opérateur des secours ne l'a pas demandé"],"correctIndex":3,"explanation":"Il est essentiel de rester en ligne et de ne raccrocher qu'à l'indication de l'opérateur des secours, qui peut avoir besoin de précisions complémentaires ou donner des instructions pendant l'attente des secours."},
  {"id":"kq457","type":"knowledge","theme":"secours","question":"Sur route ou autoroute la nuit, en cas d'arrêt d'urgence, en plus du gilet et du triangle, il est recommandé de :","options":["Allumer les feux de détresse et se signaler au plus tôt aux autres usagers","Éteindre les feux du véhicule pour ne pas éblouir les autres conducteurs sur la route","Se placer devant le véhicule, bien visible dans les phares, pour être vu de loin","Allumer les feux de brouillard arrière et attendre à bord du véhicule en sécurité"],"correctIndex":0,"explanation":"De nuit, il est essentiel d'allumer les feux de détresse et de se signaler au plus vite (gilet, triangle) pour être vu par les autres usagers, le risque de sur-accident étant plus élevé dans l'obscurité."},
  {"id":"kq458","type":"knowledge","theme":"secours","question":"Après un accident impliquant plusieurs véhicules, s'il n'y a aucun blessé et que la circulation n'est pas gênée, il est recommandé de :","options":["Laisser les véhicules en l'état sur la chaussée jusqu'à l'arrivée de la police","Dégager si possible les véhicules hors de la chaussée avant de remplir le constat","Appeler les pompiers et le SAMU avant de remplir le constat amiable sur place","Quitter les lieux sans échanger d'informations si les dégâts matériels sont minimes"],"correctIndex":1,"explanation":"En l'absence de blessé, il est conseillé de dégager rapidement les véhicules de la chaussée (pour éviter un sur-accident) avant de remplir tranquillement le constat amiable en sécurité."},
  {"id":"kq459","type":"knowledge","theme":"secours","question":"Concernant l'hémorragie interne (non visible de l'extérieur), les signes pouvant alerter incluent notamment :","options":["Un teint rouge, une peau chaude et sèche et un pouls très lent","Une forte fièvre, des courbatures et une toux persistante","Une pâleur importante, des sueurs, une soif intense et un pouls rapide","Des douleurs articulaires, des fourmillements et une perte de l'odorat"],"correctIndex":2,"explanation":"Une hémorragie interne, invisible directement, peut se traduire par une pâleur marquée, des sueurs, une soif intense et un pouls rapide : des signes de choc hémorragique qui doivent alerter et être signalés aux secours."},
  {"id":"kq460","type":"knowledge","theme":"secours","question":"Concernant un objet planté profondément dans une plaie (corps étranger empalé), il faut :","options":["Le retirer rapidement pour désinfecter la plaie avant l'arrivée des secours","Le pousser davantage pour qu'il ne bouge plus pendant le transport","Le couper à ras de la peau pour pouvoir allonger la victime","Ne jamais le retirer soi-même, mais le stabiliser en attendant les secours"],"correctIndex":3,"explanation":"Un objet empalé ne doit jamais être retiré par un témoin, son retrait pouvant aggraver une hémorragie ; il faut le stabiliser autour (sans appuyer dessus) et attendre les secours qui géreront son extraction en sécurité."},
  {"id":"kq461","type":"knowledge","theme":"secours","question":"Un enfant victime d'un accident nécessite, en cas d'arrêt cardio-respiratoire, une technique de massage cardiaque :","options":["Adaptée à sa morphologie, avec l'aide de l'opérateur des secours au téléphone","Identique à celle d'un adulte, avec la même force et deux mains","Déconseillée avant l'âge de dix ans, sauf pour un médecin","Réservée aux personnes titulaires d'une formation de secouriste"],"correctIndex":0,"explanation":"Le massage cardiaque chez l'enfant nécessite une adaptation de la force et parfois de la technique (une ou deux mains selon l'âge) ; l'opérateur des secours peut guider un témoin non formé au téléphone en attendant les secours."},
  {"id":"kq462","type":"knowledge","theme":"secours","question":"Face à un accident avec plusieurs blessés de gravité différente, en attendant les secours, la priorité doit être donnée à :","options":["Celle qui crie ou se plaint le plus fort, car elle est la plus atteinte","Les urgences vitales (absence de respiration, hémorragie massive) avant les autres blessures","Les enfants d'abord, puis les adultes, quel que soit leur état","Le conducteur du véhicule, qui est le premier responsable de l'accident"],"correctIndex":1,"explanation":"Face à plusieurs victimes, il faut évaluer rapidement les fonctions vitales de chacune et traiter en priorité les urgences vitales (arrêt respiratoire, hémorragie massive), indépendamment de qui se manifeste le plus."},
  {"id":"kq463","type":"knowledge","theme":"secours","question":"Concernant les numéros d'urgence, le 114 en France est réservé :","options":["Aux urgences vétérinaires et aux animaux blessés sur la voie publique","Aux dépannages et remorquages sur le réseau autoroutier et routier","Aux appels d'urgence par SMS pour les personnes sourdes ou malentendantes","Aux signalements de personnes disparues ou d'enfants en danger"],"correctIndex":2,"explanation":"Le 114 est le numéro d'urgence national accessible par SMS ou visio, destiné aux personnes sourdes, malentendantes, aphasiques ou dysphasiques ne pouvant pas téléphoner classiquement."},
  {"id":"kq464","type":"knowledge","theme":"secours","question":"Un airbag qui s'est déclenché lors d'un accident peut, dans les minutes qui suivent, dégager :","options":["Un gaz irritant dangereux qui impose d'évacuer toute la zone sur 50 mètres","Une fumée d'incendie signalant que le véhicule va s'enflammer dans les minutes suivantes","Une vapeur de carburant très inflammable qui interdit tout usage de téléphone","Une poussière et une odeur normalement sans danger, sauf gêne respiratoire chez une personne fragile"],"correctIndex":3,"explanation":"Le déclenchement d'un airbag peut dégager une légère poussière et une odeur particulière, généralement sans danger, bien qu'il soit conseillé d'aérer et de surveiller toute gêne respiratoire chez une personne sensible."},
  {"id":"kq465","type":"knowledge","theme":"secours","question":"Lorsqu'un témoin décide d'intervenir sur une victime, il doit avant tout :","options":["Se présenter, expliquer son intention et rassurer la victime si elle est consciente","Obtenir l'accord écrit de la victime ou d'un proche avant le moindre geste de secours","Attendre l'accord d'un policier ou d'un pompier avant de la toucher ou de lui parler","Vérifier qu'il dispose d'un diplôme de secourisme en cours de validité avant d'agir"],"correctIndex":0,"explanation":"Avant d'intervenir sur une victime consciente, il est recommandé de se présenter, d'expliquer ce que l'on va faire et de la rassurer, ce qui facilite sa coopération et limite son anxiété."},
  {"id":"kq466","type":"knowledge","theme":"secours","question":"Concernant la sécurisation des lieux d'un accident hors agglomération, la nuit, il est conseillé de placer le triangle de présignalisation à une distance minimale d'environ :","options":["10 mètres, distance doublée si la route est mouillée ou si la nuit est tombée","30 mètres, davantage si la visibilité est réduite (courbe, sommet de côte)","5 mètres, car une distance plus grande expose le poseur à la circulation","150 mètres de jour comme de nuit, sauf en agglomération où 30 mètres suffisent"],"correctIndex":1,"explanation":"Le triangle doit être placé à une distance suffisante (au moins 30 mètres) pour laisser aux autres conducteurs le temps de réagir, cette distance devant être augmentée en cas de virage, de sommet de côte ou de faible visibilité."},
  {"id":"kq467","type":"knowledge","theme":"secours","question":"Une personne victime d'un malaise cardiaque (douleur thoracique intense, oppression) au volant doit, si elle en a encore la capacité :","options":["Continuer à rouler lentement jusqu'à la prochaine station-service pour demander de l'aide","Rejoindre l'hôpital le plus proche par ses propres moyens en roulant plus vite","S'arrêter dès que possible en sécurité et alerter les secours (15 ou 112)","Attendre que la douleur passe, puis reprendre la route en conduisant calmement"],"correctIndex":2,"explanation":"Face à des signes de malaise cardiaque, il faut s'arrêter en sécurité dès que possible et alerter immédiatement les secours médicalisés (15 ou 112), plutôt que de continuer à conduire ou d'attendre."},
  {"id":"kq468","type":"knowledge","theme":"secours","question":"Un feu de moteur qui se propage rapidement et ne peut être maîtrisé avec les moyens à disposition impose de :","options":["Poursuivre l'extinction avec tous les moyens disponibles, même au risque de se brûler","Rester à proximité du véhicule pour surveiller l'évolution du feu et guider les secours","Tenter de déplacer le véhicule en marche pour l'éloigner des autres véhicules","S'éloigner immédiatement à bonne distance du véhicule et alerter les secours"],"correctIndex":3,"explanation":"Face à un feu qui se propage rapidement et dépasse les moyens de maîtrise disponibles, la priorité absolue est de s'éloigner à bonne distance (risque d'explosion) et d'alerter immédiatement les secours."},
  {"id":"kq469","type":"knowledge","theme":"secours","question":"La position latérale de sécurité (PLS) a notamment pour but d'éviter :","options":["Que la langue ou des vomissements n'obstruent les voies respiratoires","Que la victime ne se réveille trop vite et ne bouge dans tous les sens","Que la victime ne se refroidisse et ne tombe en hypothermie pendant l'attente","Que la victime ne subisse un arrêt cardiaque dû à la position allongée sur le dos"],"correctIndex":0,"explanation":"La PLS maintient les voies respiratoires dégagées chez une victime inconsciente qui respire, en évitant que sa langue ne bascule en arrière ou que d'éventuels vomissements ne l'étouffent."},
  {"id":"kq470","type":"knowledge","theme":"secours","question":"En résumé, la meilleure façon de se préparer à réagir efficacement en cas d'accident de la route est de :","options":["S'appuyer sur les secours professionnels, qui interviennent assez vite pour tout accident","Suivre une formation aux premiers secours (type PSC1) et connaître la conduite PAS","Conserver une trousse de secours dans le coffre sans suivre de formation","Mémoriser les numéros d'urgence, sans autre préparation"],"correctIndex":1,"explanation":"Suivre une formation aux premiers secours (comme le PSC1) et connaître la conduite à tenir résumée par PAS (Protéger, Alerter, Secourir) permet de réagir efficacement et sereinement en cas d'accident, en complément de l'intervention des secours professionnels."},
  {"id":"kq471","type":"knowledge","theme":"circulation","scene":"inter_droite","question":"Vous conduisez le véhicule A. Aucun panneau ni feu ne régit ce carrefour. Qui passe en premier ?","options":["Vous, car vous êtes arrivé le premier à hauteur du carrefour","Le véhicule B, car il arrive de votre droite","Le véhicule le plus rapide des deux","Celui qui klaxonne ou fait un appel de phares"],"correctIndex":1,"explanation":"En l'absence de signalisation, la règle est la priorité à droite : vous devez céder le passage au véhicule qui arrive de votre droite, quelle que soit sa vitesse ou son gabarit."},
  {"id":"kq472","type":"knowledge","theme":"circulation","scene":"inter_gauche","question":"Aucun panneau ne régit ce carrefour. Le véhicule B arrive par votre gauche. Que faites-vous ?","options":["Vous lui cédez le passage, car il est plus proche de la ligne centrale","Vous vous arrêtez pour le laisser traverser","Vous ralentissez et lui faites un appel de phares pour qu'il passe","Vous passez : vous êtes prioritaire, mais restez vigilant"],"correctIndex":3,"explanation":"Avec la priorité à droite, c'est B qui doit vous céder le passage puisque vous arrivez de sa droite. Restez toutefois vigilant : un autre conducteur peut ne pas respecter la règle."},
  {"id":"kq473","type":"knowledge","theme":"circulation","scene":"inter_gauche","question":"Dans cette situation sans panneau, quelle affirmation est exacte ?","options":["B doit me céder le passage, car j'arrive de sa droite","Je dois céder à B, car il roule plus vite que moi","B passe en premier, car il est plus proche du centre du carrefour","Nous passons en même temps, chacun roulant à droite"],"correctIndex":0,"explanation":"La priorité à droite s'applique : A arrive sur la droite de B, donc B doit lui céder le passage."},
  {"id":"kq474","type":"knowledge","theme":"circulation","scene":"stop","question":"Vous êtes face à un panneau STOP. Le véhicule B arrive sur la route transversale. Que faites-vous ?","options":["Vous ralentissez fortement, puis passez si B est assez loin","Vous vous arrêtez seulement si B arrive assez près de vous","Vous vous arrêtez à la ligne, puis cédez le passage à B","Vous passez directement : B voit le panneau et doit vous laisser passer"],"correctIndex":2,"explanation":"Au STOP, l'arrêt est obligatoire, même si la route paraît libre. Vous devez vous immobiliser à la ligne d'arrêt, puis céder le passage aux véhicules de la route transversale."},
  {"id":"kq475","type":"knowledge","theme":"circulation","scene":"stop","question":"Vous êtes au STOP et la route transversale semble vide. Vous devez malgré tout :","options":["Ralentir et passer sans vous arrêter si personne n'arrive","Réduire votre vitesse à 10 km/h au minimum avant de passer","Vous arrêter seulement si un véhicule apparaît au loin","Marquer l'arrêt complet à la ligne, puis repartir"],"correctIndex":3,"explanation":"Le STOP impose l'immobilisation du véhicule, même quand aucun autre usager n'est visible. Ralentir ne suffit pas."},
  {"id":"kq476","type":"knowledge","theme":"circulation","scene":"cedez","question":"Vous êtes face à un panneau « Cédez le passage ». Le véhicule B arrive par votre droite sur la route transversale. Vous devez :","options":["Vous arrêter obligatoirement à la ligne avant de repartir","Lui céder le passage et ne vous engager que sans le gêner","Passer en premier, car B n'a pas de panneau","Passer si vous mettez votre clignotant à temps"],"correctIndex":1,"explanation":"Le panneau « Cédez le passage » impose de laisser passer les véhicules de la route transversale ; contrairement au STOP, l'arrêt n'est nécessaire que si la circulation l'exige."},
  {"id":"kq477","type":"knowledge","theme":"circulation","scene":"priorite","question":"Vous roulez sur une route signalée par un losange jaune. B arrive d'une route latérale, face à un « Cédez le passage ». Qui doit céder ?","options":["Vous : B vient de votre droite","Celui qui arrive le premier au carrefour","B : vous êtes sur une route à priorité","Personne : ce panneau n'a pas de valeur ici"],"correctIndex":2,"explanation":"Le panneau en losange jaune signale une route prioritaire jusqu'au prochain panneau de fin de priorité : les véhicules des routes latérales doivent vous céder le passage."},
  {"id":"kq478","type":"knowledge","theme":"circulation","scene":"tourne_gauche","question":"Vous voulez tourner à gauche. B arrive en face et va tout droit. Qui passe en premier ?","options":["B, car vous coupez sa trajectoire et devez lui céder","Vous, car vous avez mis votre clignotant avant lui","Vous, car vous êtes déjà engagé dans le carrefour","Le plus petit des deux véhicules, plus facile à croiser"],"correctIndex":0,"explanation":"Un conducteur qui tourne à gauche coupe la trajectoire des véhicules venant en sens inverse : il doit leur céder le passage, sauf signalisation contraire."},
  {"id":"kq479","type":"knowledge","theme":"circulation","scene":"tourne_droite_pieton","question":"Vous tournez à droite. Un piéton traverse la rue dans laquelle vous allez entrer. Que faites-vous ?","options":["Vous passez devant lui en klaxonnant pour l'avertir","Vous le laissez traverser avant de vous engager","Vous passez si vous roulez très lentement et sans l'effleurer","Vous passez derrière lui dès qu'il a fait quelques pas"],"correctIndex":1,"explanation":"En tournant, vous devez céder le passage aux piétons qui traversent la chaussée dans laquelle vous vous engagez, qu'il y ait un passage piéton ou non."},
  {"id":"kq480","type":"knowledge","theme":"circulation","scene":"rond_point","question":"À l'entrée de ce rond-point (« Cédez le passage »), B est déjà dans l'anneau. Que faites-vous ?","options":["Vous passez, car vous venez de la droite de B","Vous passez en premier si vous mettez votre clignotant à droite","Vous accélérez pour entrer avant que B n'arrive","Vous cédez à B et entrez quand l'anneau est libre"],"correctIndex":3,"explanation":"Dans un giratoire, les véhicules déjà engagés dans l'anneau sont prioritaires : ceux qui veulent y entrer leur cèdent le passage."},
  {"id":"kq481","type":"knowledge","theme":"circulation","scene":"pieton","question":"Un piéton est engagé sur le passage devant vous (véhicule A). Que faites-vous ?","options":["Vous vous arrêtez et le laissez traverser","Vous accélérez légèrement pour passer avant qu'il atteigne votre voie","Vous klaxonnez pour l'avertir de votre passage","Vous le contournez par la gauche sans vous arrêter"],"correctIndex":0,"explanation":"Le conducteur doit céder le passage au piéton engagé sur un passage protégé ou s'apprêtant à le traverser, en ralentissant et si besoin en s'arrêtant."},
  {"id":"kq482","type":"knowledge","theme":"route","scene":"ligne_continue","question":"Vous êtes derrière un camion lent. La ligne centrale est continue et B arrive en face au loin. Pouvez-vous dépasser ?","options":["Oui, si vous êtes certain que la route est droite","Oui, si vous roulez assez vite pour dépasser rapidement","Non : une ligne continue ne se franchit pas","Oui, à condition de mettre votre clignotant à gauche"],"correctIndex":2,"explanation":"Une ligne continue interdit de la franchir ou de la chevaucher, même si la route est droite et la visibilité bonne."},
  {"id":"kq483","type":"knowledge","theme":"route","scene":"ligne_discontinue","question":"La ligne centrale est discontinue, la route est dégagée en face et un camion lent roule devant vous. Pour dépasser, vous devez :","options":["Seulement prévenir le chauffeur du camion en klaxonnant avant de déboîter","Accélérer dès que possible, la ligne discontinue autorisant tout dépassement","Attendre qu'aucune ligne ne soit tracée au sol","Avoir bonne visibilité et voie de gauche libre sur toute la manœuvre"],"correctIndex":3,"explanation":"Une ligne discontinue autorise le dépassement, à condition de s'assurer d'une visibilité suffisante, de signaler son intention et de pouvoir se rabattre sans danger."},
  {"id":"kq484","type":"knowledge","theme":"circulation","scene":"passage_niveau","question":"Les feux rouges clignotent et les barrières sont baissées. Un train arrive. Que faites-vous ?","options":["Vous contournez la barrière si le train paraît encore éloigné","Vous attendez que les barrières se relèvent et que les feux s'éteignent","Vous passez si la barrière n'est baissée que d'un côté","Vous passez dès que le train est passé, même si les feux clignotent encore"],"correctIndex":1,"explanation":"À un passage à niveau, les feux rouges clignotants et la fermeture des barrières imposent l'arrêt. Il est interdit de contourner une barrière ou de s'y engager."},
  {"id":"kq485","type":"knowledge","theme":"circulation","scene":"feu_rouge","question":"Le feu est rouge pour vous et aucun autre véhicule n'est en vue. Que faites-vous ?","options":["Vous passez si vous ne voyez personne","Vous vous arrêtez, puis passez à vitesse réduite","Vous vous arrêtez avant la ligne et attendez le feu vert","Vous franchissez la ligne pour mieux voir, puis vous décidez"],"correctIndex":2,"explanation":"Le feu rouge impose l'arrêt avant la ligne, même si la voie est libre ; le franchir est sanctionné par une amende et un retrait de points."},
  {"id":"kq486","type":"knowledge","theme":"circulation","scene":"feu_orange","question":"Le feu passe à l'orange alors que vous pouvez vous arrêter sans danger avant la ligne. Que faites-vous ?","options":["Vous vous arrêtez avant la ligne","Vous accélérez pour passer avant le rouge","Vous passez, car l'orange laisse toujours le temps de traverser","Vous klaxonnez pour signaler que vous passez"],"correctIndex":0,"explanation":"Le feu orange fixe impose l'arrêt, sauf si l'on est trop près au moment où il s'allume pour s'arrêter dans des conditions de sécurité suffisantes."},
  {"id":"kq487","type":"knowledge","theme":"circulation","scene":"t_droite","question":"Vous arrivez au bout d'une route en T, sans panneau. B arrive par votre droite sur la route transversale. Qui cède le passage ?","options":["B, car vous venez de la route perpendiculaire","Vous : B vient de votre droite et est prioritaire","Personne : c'est le premier arrivé qui passe","B, car la route qui continue des deux côtés est toujours prioritaire"],"correctIndex":1,"explanation":"Sans signalisation, la priorité à droite s'applique aussi à une intersection en T : vous devez céder le passage au véhicule qui arrive de votre droite."}
];
